// docs/preguntas-nucleos/*.json: no lo edites a mano (editá el JSON y volvé a correr el script).
(function registerPreguntasNucleos(root, factory) {
  const api = factory();
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  if (root) root.InmunePreguntasNucleos = api;
})(typeof globalThis !== 'undefined' ? globalThis : null, function createPreguntasNucleos() {
  'use strict';
  const PREGUNTAS = Object.freeze([
    {"id":"n6-f-01","nucleo":"6","difficulty":"facil","topic":"Escherichia coli enterohemorrágica","q":"¿Qué alimento se asocia con más frecuencia a los casos de síndrome urémico hemolítico en Argentina?","a":["La carne picada mal cocida","El arroz cocido guardado a temperatura ambiente","La miel en lactantes menores de un año","El pescado crudo de agua dulce"],"c":0,"exp":"La carne picada se contamina durante el faenado y la bacteria queda distribuida en todo el producto: hay que cocinarla a 70 °C o más. El reservorio principal de ECEH es el ganado bovino.","source":"Cuadernillo Núcleo 6 Digestivo 2026 (TP 14, Actividad 5) · Compendio ADN (7.f.c)"},
    {"id":"n6-f-02","nucleo":"6","difficulty":"facil","topic":"Rotavirus","q":"¿A qué edades se aplican las dos dosis de la vacuna contra rotavirus en el calendario nacional argentino?","a":["A los 2 y a los 4 meses de vida","A los 2, 4 y 6 meses, con refuerzo a los 18 meses","Dosis única a los 12 meses de vida","Al nacer y a los 6 meses de vida"],"c":0,"exp":"La primera dosis va a los 2 meses (edad máxima 14 semanas y 6 días) y la segunda a los 4 meses, sin pasar las 24 semanas de vida.","source":"Compendio ADN (7.c.e) · Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 8, Grupo 2f)"},
    {"id":"n6-f-03","nucleo":"6","difficulty":"facil","topic":"Virus de la hepatitis A","q":"¿Cuál es la vía de transmisión del virus de la hepatitis A?","a":["Fecal-oral, por agua o alimentos contaminados","Parenteral, por sangre, agujas o material contaminado","Sexual y perinatal, igual que el VHB y el VHC","Respiratoria, por gotitas y aerosoles"],"c":0,"exp":"El VHA y el VHE ingresan por vía digestiva (fecal-oral); los de ingreso parenteral son el B, el C y el D. Por eso en A y E la prevención es saneamiento, agua segura e higiene.","source":"Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 9, objetivos) · Compendio ADN (7.g)"},
    {"id":"n6-f-04","nucleo":"6","difficulty":"facil","topic":"Giardia lamblia","q":"¿Qué tipo de parásito es Giardia lamblia y cuál es su forma infectante?","a":["Protozoo flagelado; el quiste es la forma infectante","Protozoo flagelado; el trofozoíto es la forma infectante que se ingiere","Nematode; el huevo larvado es la forma infectante","Apicomplexa; el ooquiste es la forma infectante"],"c":0,"exp":"Giardia es un protozoo flagelado con dos formas: trofozoíto (vegetativa, en duodeno y yeyuno) y quiste, que es la forma infectante que se ingiere con agua o alimentos contaminados.","source":"Compendio ADN (7.a.a) · Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 8, Actividad 2b)"},
    {"id":"n6-f-05","nucleo":"6","difficulty":"facil","topic":"Clostridium botulinum","q":"¿Qué alimento se asocia clásicamente al botulismo del lactante?","a":["La miel","El arroz cocido mal conservado","La leche sin pasteurizar","Los huevos crudos o mal cocidos"],"c":0,"exp":"La miel puede contener esporas de C. botulinum que germinan en el intestino del lactante y producen toxina in vivo; la tierra y el polvo contaminados son hoy la fuente más frecuente.","source":"Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 8, Actividad 2) · Compendio ADN (7.e)"},
    {"id":"n6-f-06","nucleo":"6","difficulty":"facil","topic":"Enterobacterias","q":"¿Qué características comparten las bacterias de la familia Enterobacteriaceae?","a":["Bacilos gramnegativos, anaerobios facultativos y oxidasa negativos","Bacilos grampositivos esporulados y anaerobios estrictos","Cocos gramnegativos aerobios estrictos y catalasa negativos","Bacilos curvos microaerófilos que no fermentan hidratos de carbono"],"c":0,"exp":"Las enterobacterias son bacilos gramnegativos, anaerobios facultativos, fermentan glucosa, reducen nitratos a nitritos y son catalasa positivas y oxidasa negativas, lo que las separa de Pseudomonas y Vibrio.","source":"Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 8, Actividad 1a) · Compendio ADN (7.e)"},
    {"id":"n6-f-07","nucleo":"6","difficulty":"facil","topic":"Taenia solium","q":"¿Cómo adquiere una persona la teniosis por Taenia solium?","a":["Comiendo carne de cerdo cruda o mal cocida","Ingiriendo los huevos del parásito con agua o verduras mal lavadas","Por penetración activa de larvas filariformes en la piel","Por la picadura de un insecto hematófago infectado"],"c":0,"exp":"La teniosis (tenia adulta en el intestino delgado) se adquiere al comer carne de cerdo con Cysticercus cellulosae. Si en cambio se ingieren los huevos, lo que se desarrolla es cisticercosis.","source":"Compendio ADN (7.a.f, 7.b caso 2) · Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 8, Actividad 4)"},
    {"id":"n6-f-08","nucleo":"6","difficulty":"facil","topic":"Vibrio cholerae","q":"¿Cómo son las heces típicas del cólera?","a":["Acuosas, en \"agua de arroz\", sin sangre","Con sangre, moco y pus, con pujo y tenesmo","Pastosas, de mal olor, con restos de alimentos","Negras y alquitranadas, con melena"],"c":0,"exp":"V. cholerae no invade la mucosa: la toxina colérica provoca hipersecreción, con diarrea acuosa incolora e inodora (\"agua de arroz\") y pérdidas que llegan a un litro por hora.","source":"Compendio ADN (7.e.f) · Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 8, Actividad 5)"},
    {"id":"n6-f-09","nucleo":"6","difficulty":"facil","topic":"Enterobius vermicularis","q":"¿Cuál es el síntoma más característico de la oxiurosis?","a":["Prurito anal de predominio nocturno","Diarrea con sangre, moco, pujo y tenesmo","Ictericia con coluria y acolia","Mialgias con edema periocular y fiebre alta"],"c":0,"exp":"Las hembras grávidas migran de noche a la región perianal a poner huevos; el prurito se origina por hipersensibilidad a las sustancias que el parásito excreta y secreta.","source":"Compendio ADN (7.a.d) · Cuadernillo Núcleo 6 Digestivo 2026 (TP 12, caso 4)"},
    {"id":"n6-f-10","nucleo":"6","difficulty":"facil","topic":"Echinococcus granulosus","q":"¿Quién es el hospedador definitivo de Echinococcus granulosus?","a":["El perro","La oveja","El cerdo","El ser humano"],"c":0,"exp":"El cestode adulto vive fijo a la mucosa del intestino delgado del perro, que elimina huevos con las heces. Los herbívoros y el humano (accidental) son intermediarios y alojan el quiste hidatídico.","source":"Compendio ADN (7.a.g, 7.b caso 1) · Cuadernillo Núcleo 6 Digestivo 2026 (TP 12, caso 1)"},
    {"id":"n6-f-11","nucleo":"6","difficulty":"facil","topic":"Escherichia coli uropatógena","q":"¿Cuál es el agente que se aísla con más frecuencia en las infecciones urinarias adquiridas en la comunidad?","a":["Escherichia coli","Proteus mirabilis","Enterococcus faecalis","Klebsiella pneumoniae"],"c":0,"exp":"En pacientes sin factores de riesgo ni enfermedad de base, E. coli se aísla en más del 70% de las ITU de la comunidad, seguida por Klebsiella spp., Proteus mirabilis y Enterococcus faecalis.","source":"Cuadernillo Núcleo 6.1 Agentes Urinarios 2026 (Introducción) · Compendio ADN (7.h)"},
    {"id":"n6-f-12","nucleo":"6","difficulty":"facil","topic":"Infección del tracto urinario","q":"¿Por qué las mujeres tienen mayor predisposición a las infecciones urinarias que los varones?","a":["Por una uretra corta y cercana al introito vaginal y al ano","Porque su orina tiene un pH más alcalino que la del varón","Porque no producen proteína de Tamm-Horsfall en el asa de Henle","Porque la vejiga femenina carece de urotelio estratificado"],"c":0,"exp":"La cortedad de la uretra femenina y su proximidad al ano y la vagina facilitan la colonización por uropatógenos intestinales; el coito \"masajea\" la uretra y favorece el ascenso a la vejiga.","source":"Cuadernillo Núcleo 6.1 Agentes Urinarios 2026 (Actividad 1B) · Compendio ADN (7.h)"},
    {"id":"n6-n-01","nucleo":"6","difficulty":"normal","topic":"Vibrio cholerae","q":"¿Cuál es el mecanismo de acción de la toxina colérica?","a":["Se une al gangliósido GM1 y activa la adenilato ciclasa","Inactiva los ribosomas y detiene la síntesis de proteínas","Inhibe la liberación de acetilcolina en las sinapsis colinérgicas","Invade el enterocito, lisa la vacuola y se multiplica en el citoplasma"],"c":0,"exp":"Es una toxina A-B: la cadena B se une al gangliósido GM1 y la cadena A activa la adenilato ciclasa. El AMPc elevado provoca secreción de agua y electrolitos, con diarrea secretora.","source":"Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 8, Actividad 3) · Compendio ADN (7.e.f)"},
    {"id":"n6-n-02","nucleo":"6","difficulty":"normal","topic":"Escherichia coli enterotoxigénica","q":"¿Qué toxinas produce Escherichia coli enterotoxigénica (ECET) y qué cuadro causa?","a":["LT y ST, con diarrea acuosa profusa sin sangre","Toxina Shiga, con colitis hemorrágica y riesgo de SUH","Intimina y toxina Shiga, con lesión del colon y sangre","Enterotoxina termoestable, con vómitos en las primeras horas"],"c":0,"exp":"ECET coloniza el intestino delgado y produce la toxina termolábil (LT, eleva el AMPc) y la termoestable (ST, eleva el GMPc): diarrea acuosa, la clásica \"diarrea del viajero\".","source":"Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 8, Actividad 7) · Compendio ADN (7.e.g)"},
    {"id":"n6-n-03","nucleo":"6","difficulty":"normal","topic":"Shigella spp.","q":"¿Cuál es el mecanismo de patogenia de Shigella spp.?","a":["Invade y se replica en las células del colon","Produce una enterotoxina que eleva el AMPc sin invadir la mucosa","Se adhiere al borde en cepillo del intestino delgado sin invadir","Coloniza la mucosa gástrica protegida por su actividad ureasa"],"c":0,"exp":"Shigella usa un sistema de secreción tipo III (proteínas IpaA-D) para invadir el epitelio del colon, reorganiza la actina y se disemina de célula a célula; induce apoptosis de los macrófagos.","source":"Compendio ADN (7.e.b) · Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 8, Actividad 5)"},
    {"id":"n6-n-04","nucleo":"6","difficulty":"normal","topic":"Rotavirus","q":"¿Cuál es el método de elección para diagnosticar una gastroenteritis por rotavirus?","a":["Detección del antígeno viral en heces por ELISA o látex","Cultivo celular con pretratamiento de la muestra con tripsina","Serología con IgM específica en el suero del paciente","Microscopía electrónica de la materia fecal"],"c":0,"exp":"La concentración de virus en heces es muy alta, así que la detección directa del antígeno (EIA o aglutinación de látex) es el método de elección; el cultivo no se usa para diagnóstico.","source":"Compendio ADN (7.c.e, 7.d) · Cuadernillo Núcleo 6 Digestivo 2026 (TP 13, Actividad 2)"},
    {"id":"n6-n-05","nucleo":"6","difficulty":"normal","topic":"Norovirus","q":"¿Qué rasgo del norovirus explica los brotes explosivos en restaurantes y cruceros?","a":["Bastan unos 10 viriones y resiste el cloro del agua potable","Tiene una envoltura lipídica que lo protege del ácido gástrico","Se transmite por vía respiratoria además de la digestiva","Su genoma segmentado permite reordenamientos frecuentes entre cepas"],"c":0,"exp":"Es un virus desnudo que resiste calor de 60 °C, pH 3, detergentes y el cloro del agua potable, y sólo 10 viriones inician la enfermedad; hasta el 30% de los infectados son asintomáticos y contagian.","source":"Compendio ADN (7.c.d) · Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 8, Grupo 3)"},
    {"id":"n6-n-06","nucleo":"6","difficulty":"normal","topic":"Adenovirus","q":"Un lactante presenta diarrea acuosa, conjuntivitis y tos productiva con probable bronquiolitis. ¿Qué agente explica mejor ese cuadro?","a":["Adenovirus","Rotavirus","Norovirus","Poliovirus"],"c":0,"exp":"Adenovirus infecta a la vez el epitelio respiratorio, el digestivo y la conjuntiva, así que un mismo virus explica la diarrea, la conjuntivitis y el compromiso respiratorio.","source":"Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 8, Grupo 1) · Compendio ADN (7.c.a)"},
    {"id":"n6-n-07","nucleo":"6","difficulty":"normal","topic":"Salmonella spp.","q":"¿Qué diferencia a Salmonella Typhi del resto de las salmonelas en cuanto al reservorio?","a":["Su único reservorio es el ser humano","Su reservorio son los reptiles y las aves de corral","Vive en el ganado bovino y el resto, en el ser humano","Comparte con el resto los mismos reservorios animales"],"c":0,"exp":"S. Typhi y Paratyphi están adaptadas al ser humano, único reservorio, y se contraen por agua o alimentos contaminados por un portador. El resto de las salmonelas viene de reservorios animales.","source":"Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 8, Actividad 6b) · Compendio ADN (7.e.c)"},
    {"id":"n6-n-08","nucleo":"6","difficulty":"normal","topic":"Helicobacter pylori","q":"¿Qué enzima le permite a Helicobacter pylori sobrevivir a la acidez gástrica?","a":["La ureasa","La catalasa","La coagulasa","La fosfolipasa C"],"c":0,"exp":"La gran cantidad de ureasa neutraliza el ácido con el amoníaco que produce; eso mismo se aprovecha en el test del aliento con urea marcada, que detecta en el aire exhalado los productos de la hidrólisis de la urea.","source":"Cuadernillo Núcleo 6 Digestivo 2026 (TP 14, Actividad 2)"},
    {"id":"n6-n-09","nucleo":"6","difficulty":"normal","topic":"Yersinia enterocolitica","q":"¿Qué particularidad del cultivo de Yersinia enterocolitica se aprovecha para aislarla de las heces?","a":["Crece a 4 °C: se usa enriquecimiento en frío","Necesita atmósfera microaerófila con más CO2 a 42 °C","Requiere medios con 10% de cloruro de sodio","Sólo crece en cultivo celular pretratado con tripsina"],"c":0,"exp":"Crece lento a la temperatura habitual de incubación pero tolera los 4 °C: el almacenamiento prolongado en frío mejora selectivamente su aislamiento. Por eso también se multiplica en alimentos refrigerados.","source":"Compendio ADN (7.e.a) · Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 8, Actividad 5)"},
    {"id":"n6-n-10","nucleo":"6","difficulty":"normal","topic":"Campylobacter spp.","q":"¿Qué condiciones de cultivo necesita Campylobacter jejuni?","a":["Poco oxígeno, más CO2 y dos o más días de incubación","Anaerobiosis estricta en jarra con generador de hidrógeno","Medio con alta salinidad y pH alcalino sostenido","Agar chocolate a temperatura ambiente durante siete días"],"c":0,"exp":"Son microaerófilos: necesitan 5-7% de oxígeno y 5-10% de CO2, medios selectivos y, en las especies termófilas, temperaturas elevadas, con dos o más días de incubación.","source":"Compendio ADN (7.e.d) · Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 8, Actividad 5)"},
    {"id":"n6-n-11","nucleo":"6","difficulty":"normal","topic":"Bacillus cereus","q":"¿Qué distingue a las dos formas de intoxicación alimentaria por Bacillus cereus?","a":["La toxina termoestable da vómitos y la termolábil, diarrea","La toxina termoestable da diarrea y la termolábil, vómitos","Una forma cursa con fiebre alta y la otra con hipotermia","Una depende de la espora y la otra de la endotoxina"],"c":0,"exp":"La enterotoxina termoestable causa la forma emética (vómitos, náuseas y espasmos, 1 a 6 h) y la termolábil, parecida a la LT de E. coli y a la colérica, la forma diarreica.","source":"Compendio ADN (7.e.e) · Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 8, Actividad 5)"},
    {"id":"n6-n-12","nucleo":"6","difficulty":"normal","topic":"Staphylococcus aureus","q":"¿Por qué recalentar un alimento no evita la intoxicación alimentaria por Staphylococcus aureus?","a":["Las enterotoxinas resisten 100 °C por 30 minutos","La bacteria forma esporas que germinan al enfriarse el alimento","La endotoxina se libera cuando el calor lisa a la bacteria","El estafilococo se multiplica a temperatura de refrigeración"],"c":0,"exp":"Las enterotoxinas estafilocócicas son superantígenos estables aunque se calienten a 100 °C durante 30 minutos: es una intoxicación por toxina preformada, no una infección.","source":"Compendio ADN (7.e.e) · Cuadernillo Núcleo 6 Digestivo 2026 (TP 14, Actividad 3)"},
    {"id":"n6-n-13","nucleo":"6","difficulty":"normal","topic":"Enfermedades transmitidas por alimentos","q":"¿Cuál es la diferencia entre infección e intoxicación alimentaria?","a":["La infección es por microorganismos vivos y la intoxicación, por toxinas preformadas","En la infección hay fiebre y en la intoxicación nunca aparece","La infección la producen bacterias y la intoxicación, sólo hongos","Un brote de intoxicación exige dos o más casos y la infección puede ser un caso aislado"],"c":0,"exp":"La infección resulta de ingerir patógenos vivos que se multiplican (Salmonella, Shigella, VHA, Trichinella); la intoxicación, de toxinas o químicos presentes en el alimento, aun sin microorganismo viable.","source":"Cuadernillo Núcleo 6 Digestivo 2026 (TP 14, Introducción y Actividad 3b) · Compendio ADN (7.f.b)"},
    {"id":"n6-n-14","nucleo":"6","difficulty":"normal","topic":"Entamoeba histolytica","q":"¿Qué hallazgo microscópico confirma que una ameba es Entamoeba histolytica?","a":["Trofozoítos que fagocitan eritrocitos","Quistes maduros con cuatro núcleos en el examen al fresco","Trofozoítos adheridos por su disco suctor al epitelio","Ooquistes con esporozoítos en su interior"],"c":0,"exp":"E. histolytica es la única ameba humana capaz de fagocitar eritrocitos: ver trofozoítos con seudópodos y eritrofagocitosis la confirma. El quiste tetranucleado es la forma infectante, pero no la distingue de E. dispar.","source":"Compendio ADN (7.a.b) · Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 8, Actividad 2)"},
    {"id":"n6-n-15","nucleo":"6","difficulty":"normal","topic":"Ascaris lumbricoides","q":"¿Qué es el ciclo de Loos en la infección por Ascaris lumbricoides?","a":["La migración de las larvas por hígado, corazón y pulmón","El pasaje de los huevos desde el suelo al agua de riego y las verduras","La autoinfección a partir de los huevos de la región perianal","El ciclo entre el cerdo y el humano que cierra la transmisión"],"c":0,"exp":"Las larvas atraviesan la pared intestinal, llegan por vía porta al hígado, corazón derecho y pulmón, suben por bronquios y tráquea, se degluten y maduran en el intestino delgado.","source":"Compendio ADN (7.a.c y recuadro ciclo de Loos) · Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 8, Actividad 3d)"},
    {"id":"n6-n-16","nucleo":"6","difficulty":"normal","topic":"Trichinella spiralis","q":"¿Cuál es la forma infectante de Trichinella spiralis y cómo se adquiere?","a":["La larva muscular L1, al comer carne cruda o mal cocida","El huevo larvado, ingerido con agua o verduras contaminadas","El quiste, eliminado con las heces del cerdo infectado","La larva filariforme, que penetra activamente la piel"],"c":0,"exp":"La larva muscular L1 está en el músculo de cerdo, jabalí u otros animales; se libera en el estómago por digestión, llega al duodeno, penetra las vellosidades y en dos días muda hasta adulto.","source":"Compendio ADN (7.a.e) · Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 8, Actividad 3)"},
    {"id":"n6-n-17","nucleo":"6","difficulty":"normal","topic":"Diagnóstico de laboratorio","q":"¿Cuál es el método diagnóstico de elección para la oxiurosis?","a":["El test de Graham seriado en la región perianal","El coproparasitológico seriado de materia fecal","La serología por ELISA para IgG específica","La biopsia de apéndice cecal con cortes transversales"],"c":0,"exp":"Los huevos se depositan en los pliegues perianales, no en las heces (allí aparecen sólo en el 10% de los casos). Un Graham detecta el 60%; repetido 5 a 7 días llega al 100%.","source":"Compendio ADN (7.a.d) · Cuadernillo Núcleo 6 Digestivo 2026 (TP 12, caso 4)"},
    {"id":"n6-n-18","nucleo":"6","difficulty":"normal","topic":"Virus de la hepatitis B","q":"¿Qué resultado serológico identifica a una persona vacunada contra hepatitis B?","a":["Anti-HBs positivo, con el resto de los marcadores negativos","Anti-HBc IgG positivo con HBsAg negativo","HBsAg positivo junto con anti-HBe positivo","HBeAg positivo con anti-HBc IgM positivo"],"c":0,"exp":"La vacuna contiene HBsAg, así que genera sólo anti-HBs. Si además hay anti-HBc, hubo contacto con el virus: eso marca infección actual o antigua, no vacunación.","source":"Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 9, Actividad 2) · Compendio ADN (7.g)"},
    {"id":"n6-n-19","nucleo":"6","difficulty":"normal","topic":"Virus de la hepatitis B","q":"¿Por qué se produce el daño hepático en la infección por el virus de la hepatitis B?","a":["Por la respuesta inmune celular contra los hepatocitos infectados","Por el efecto citopático directo del virus sobre el hepatocito","Por la endotoxina que se libera durante la replicación viral","Por la obstrucción mecánica de los canalículos biliares intrahepáticos"],"c":0,"exp":"El VHB no tiene efecto citopático significativo: la inmunidad celular y la inflamación producen los síntomas y, cuando son eficaces, la resolución, al destruir los hepatocitos infectados.","source":"Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 9, Actividades 2c y 3) · Compendio ADN (7.g)"},
    {"id":"n6-n-20","nucleo":"6","difficulty":"normal","topic":"Virus de la hepatitis D","q":"¿Por qué el virus de la hepatitis D no puede infectar por sí solo?","a":["Porque usa el HBsAg del virus de la hepatitis B como envoltura","Porque carece de genoma propio y necesita el ADN del VHB","Porque sólo se replica dentro de los linfocitos T del huésped","Porque requiere una coinfección con el virus de la hepatitis C"],"c":0,"exp":"El VHD es un virus tipo viroide, con ARN monocatenario circular, que usa la envoltura de HBsAg del VHB para ensamblarse y salir: de ahí que la coinfección o sobreinfección con VHB sea obligada.","source":"Compendio ADN (7.g) · Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 9, Grupo 3)"},
    {"id":"n6-n-21","nucleo":"6","difficulty":"normal","topic":"Proteus mirabilis","q":"¿Qué factor de virulencia de Proteus mirabilis favorece la formación de cálculos urinarios?","a":["La ureasa, que alcaliniza la orina","La cápsula polisacárida, que inhibe la fagocitosis","Las fimbrias tipo 1, que median la adherencia","La toxina Shiga, que daña el endotelio renal"],"c":0,"exp":"La ureasa alcaliniza la orina y favorece la precipitación de sales con formación de cálculos de estruvita; además P. mirabilis tiene fimbrias y flagelos para la colonización ascendente.","source":"Cuadernillo Núcleo 6.1 Agentes Urinarios 2026 (Actividad 2) · Compendio ADN (7.h.b)"},
    {"id":"n6-n-22","nucleo":"6","difficulty":"normal","topic":"Micoplasmas genitales","q":"¿Qué rasgo de los micoplasmas explica que no respondan a los antibióticos que actúan sobre la pared celular?","a":["No tienen pared celular","Son intracelulares obligados","Tienen una cápsula muy gruesa","Forman esporas resistentes"],"c":0,"exp":"Son procariotas muy pequeños, pleomórficos y sin pared celular, por lo que resisten a los antibióticos dirigidos a ella; crecen en medios enriquecidos o asociados a membranas celulares.","source":"Cuadernillo Núcleo 6.1 Agentes Urinarios 2026 (Actividad 2) · Compendio ADN (7.h.b)"},
    {"id":"n6-n-23","nucleo":"6","difficulty":"normal","topic":"Infección del tracto urinario","q":"¿Qué mecanismo explica la mayor parte de las infecciones urinarias en el paciente sondado?","a":["El biofilm en la sonda y el ascenso extraluminal","La diseminación hematógena desde un foco infeccioso a distancia","La contaminación de la orina ya emitida en la bolsa colectora","El reflujo vesicoureteral por atonía progresiva del uréter"],"c":0,"exp":"Los uropatógenos forman un biofilm intra y extraluminal que los protege de los antimicrobianos y de la inmunidad; dos tercios ascienden por vía extratransluminal, entre la sonda y la mucosa uretral.","source":"Cuadernillo Núcleo 6.1 Agentes Urinarios 2026 (ITU en el paciente sondado) · Compendio ADN (7.h)"},
    {"id":"n6-n-24","nucleo":"6","difficulty":"normal","topic":"Respuesta inmune","q":"¿Cuál es el perfil de respuesta T helper que predomina frente a los helmintos?","a":["Th2, con IL-4, IL-5 e IL-13","Th1, con IL-12 e IFN-gamma, que activa macrófagos","Th17, con IL-17 y reclutamiento de neutrófilos","Treg, con IL-10 y supresión de la respuesta efectora"],"c":0,"exp":"Los helmintos inducen un perfil Th2: IL-4 e IL-13 activan macrófagos alternativos, IL-5 recluta eosinófilos y la IgE provoca desgranulación de mastocitos y citotoxicidad dependiente de anticuerpos.","source":"Compendio ADN (7.i.e)"},
    {"id":"n6-n-25","nucleo":"6","difficulty":"normal","topic":"Epidemiología","q":"Según el estudio de parasitosis intestinales en poblaciones infantiles de Argentina, ¿qué explica la tendencia descendente de norte a sur?","a":["El clima cálido y húmedo del noreste favorece a los geohelmintos","El norte tiene mayor cobertura de agua de red que el sur del país","Los protozoos necesitan suelos áridos y fríos para enquistarse","En el sur se concentran las poblaciones rurales y periurbanas"],"c":0,"exp":"Los geohelmintos necesitan suelos cálidos y húmedos para desarrollarse: de ahí su mayor prevalencia en Misiones y Formosa y su ausencia en zonas áridas o frías como La Pampa y Chubut.","source":"Cuadernillo Núcleo 6 Digestivo 2026 (TP 12, Actividad 1; Navone y col., 2017) · Compendio ADN (7.b)"},
    {"id":"n6-d-01","nucleo":"6","difficulty":"dificil","topic":"Taenia solium","q":"Un nene de 5 años con convulsiones tiene en la resonancia lesiones quísticas con un escólex en su interior y ELISA para cisticercosis positivo. ¿Qué forma parasitaria ingirió?","a":["Huevos eliminados en heces humanas","Cisticercos de carne de cerdo mal cocida","Quistes presentes en agua de pozo contaminada","Larvas filariformes desarrolladas en el suelo"],"c":0,"exp":"La cisticercosis se adquiere al ingerir huevos de T. solium por vía fecal-oral, con el humano como hospedador intermediario accidental. Comer carne con cisticercos produce teniosis, no neurocisticercosis.","source":"Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 8, Actividad 5a) · Compendio ADN (7.a.f, 7.b caso 2)"},
    {"id":"n6-d-02","nucleo":"6","difficulty":"dificil","topic":"Echinococcus granulosus","q":"¿Por qué el coproparasitológico no sirve para diagnosticar hidatidosis en una persona?","a":["Porque el humano no aloja el adulto y no elimina huevos","Porque los huevos se destruyen al pasar por el jugo gástrico","Porque el quiste libera escólices únicamente en la orina","Porque el coproparasitológico solo detecta protozoos y no huevos de cestodes"],"c":0,"exp":"El humano es hospedador intermediario: aloja el quiste hidatídico, no el cestode adulto, así que no elimina huevos. Se diagnostica por imágenes (ecografía, TAC) y serología (ELISA IgG, HAI).","source":"Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 8, Actividad 4b) · Compendio ADN (7.a.g)"},
    {"id":"n6-d-03","nucleo":"6","difficulty":"dificil","topic":"Strongyloides stercoralis","q":"Un paciente con VIH de larga evolución tiene diarrea acuosa, tos y sibilancias, y en el coproparasitológico se ven larvas rabditoides y filariformes. ¿Qué explica el cuadro?","a":["Autoinfección interna por Strongyloides stercoralis","Ascariosis en fase pulmonar con síndrome de Loeffler","Criptosporidiosis con compromiso biliar en inmunosuprimido","Triquinosis en fase de invasión muscular"],"c":0,"exp":"En inmunocomprometidos las larvas rabditoides se vuelven filariformes en el lumen, penetran la pared intestinal o perianal y repiten el ciclo de Loos: hiperinfección con síntomas digestivos y pulmonares.","source":"Cuadernillo Núcleo 6 Digestivo 2026 (TP 12, caso 5) · Compendio ADN (7.b caso 5)"},
    {"id":"n6-d-04","nucleo":"6","difficulty":"dificil","topic":"Escherichia coli enterohemorrágica","q":"¿Cuál es la tríada que caracteriza al síndrome urémico hemolítico típico?","a":["Anemia hemolítica microangiopática, plaquetopenia e insuficiencia renal","Fiebre, ictericia y hepatomegalia dolorosa","Anemia, leucocitosis y eosinofilia marcada","Diarrea sanguinolenta, fiebre alta y convulsiones con eosinófilos en el LCR"],"c":0,"exp":"Son anemia hemolítica microangiopática (hemoglobina baja, eritrocitos fragmentados, Coombs negativa), plaquetas por debajo de 150.000/mm3 y deterioro de la función renal con creatinina elevada para la edad.","source":"Cuadernillo Núcleo 6 Digestivo 2026 (TP 14, Actividad 5b) · Compendio ADN (7.f.c)"},
    {"id":"n6-d-05","nucleo":"6","difficulty":"dificil","topic":"Escherichia coli enterohemorrágica","q":"¿Cómo daña los tejidos la toxina Shiga?","a":["Inactiva los ribosomas y detiene la síntesis de proteínas","Activa la adenilato ciclasa y eleva el AMPc del enterocito","Degrada el peptidoglicano del endotelio vascular renal","Activa de forma inespecífica a los linfocitos T como superantígeno"],"c":0,"exp":"La subunidad B se une al glucolípido Gb3 de células de riñón, cerebro, intestino y endotelio; la A inactiva los ribosomas y detiene la síntesis proteica, con muerte celular y microangiopatía.","source":"Cuadernillo Núcleo 6 Digestivo 2026 (TP 14, Actividad 5b) · Compendio ADN (7.f.c, 7.e.b)"},
    {"id":"n6-d-06","nucleo":"6","difficulty":"dificil","topic":"Escherichia coli enteroinvasiva","q":"¿Qué categoría de Escherichia coli tiene una patogenia prácticamente idéntica a la de Shigella?","a":["La enteroinvasiva (ECEI)","La enterotoxigénica (ECET)","La enteroagregativa (ECEA)","La enteropatógena (ECEP)"],"c":0,"exp":"ECEI invade las células epiteliales del colon, lisa la vacuola fagocítica, se multiplica en el citoplasma y se propaga a las células vecinas, con una disentería indistinguible de la shigelosis.","source":"Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 8, Actividad 7) · Compendio ADN (7.e.g)"},
    {"id":"n6-d-07","nucleo":"6","difficulty":"dificil","topic":"Salmonella spp.","q":"¿En qué muestra esperaría recuperar Salmonella Enteritidis en un cuadro de gastroenteritis?","a":["En materia fecal","En hemocultivo con medio de enriquecimiento","En orina recogida por chorro medio","En líquido cefalorraquídeo"],"c":0,"exp":"La mayoría de las gastroenteritis por salmonelas no tifoideas queda limitada al intestino: se buscan en coprocultivo con medios selectivos. En lactantes, ancianos o inmunocomprometidos pueden dar bacteriemia; S. Typhi se busca en sangre.","source":"Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 8, Actividad 6b) · Compendio ADN (7.e.c)"},
    {"id":"n6-d-08","nucleo":"6","difficulty":"dificil","topic":"Virus de la hepatitis B","q":"Un paciente tiene HBsAg y HBeAg positivos, anti-HBc IgM positivo y anti-HBs negativo. ¿Qué situación representa?","a":["Hepatitis B aguda en fase replicativa","Hepatitis B crónica sin replicación activa","Infección resuelta hace varios años","Persona vacunada sin contacto previo con el virus"],"c":0,"exp":"La IgM anti-HBc es el mejor marcador de infección aguda reciente, y HBsAg junto con HBeAg indican replicación activa. En la infección crónica predomina la IgG anti-HBc.","source":"Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 9, Actividad 2) · Compendio ADN (7.g)"},
    {"id":"n6-d-09","nucleo":"6","difficulty":"dificil","topic":"Virus de la hepatitis E","q":"¿En qué grupo la hepatitis E tiene una evolución particularmente grave?","a":["En las embarazadas","En los recién nacidos de madre portadora","En los adultos mayores de 60 años","En los pacientes en hemodiálisis crónica"],"c":0,"exp":"En pacientes sanos la mortalidad del VHE es de 1-2%, pero en embarazadas llega al 20%, posiblemente por una respuesta inmunitaria alterada. No deja estado de portador crónico.","source":"Compendio ADN (7.g, tabla comparativa) · Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 9, Grupo 1)"},
    {"id":"n6-d-10","nucleo":"6","difficulty":"dificil","topic":"Clostridium botulinum","q":"¿Cómo explica la toxina botulínica la parálisis flácida del lactante?","a":["Su endopeptidasa inactiva las proteínas que liberan acetilcolina","Bloquea los receptores de glicina de las interneuronas medulares","Inactiva los ribosomas de la neurona motora periférica","Eleva el AMPc en la placa neuromuscular"],"c":0,"exp":"La cadena pesada se une a receptores de la neurona motora y promueve la endocitosis; la cadena ligera, endopeptidasa de zinc, inactiva las proteínas que regulan la liberación de acetilcolina.","source":"Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 8, Actividades 2c y 2d) · Compendio ADN (7.e)"},
    {"id":"n6-d-11","nucleo":"6","difficulty":"dificil","topic":"Diagnóstico de laboratorio","q":"¿Para qué sirve el agar MacConkey en la identificación de enterobacterias?","a":["Es selectivo y diferencial: separa por fermentación de lactosa","Es un medio de enriquecimiento para bacterias nutricionalmente exigentes","Es un medio cromogénico que detecta la actividad de la ureasa","Es un medio básico en el que crece casi cualquier bacteria"],"c":0,"exp":"Permite el crecimiento de bacilos gramnegativos y diferencia por color: las fermentadoras de lactosa dan colonias rosadas, mientras Shigella y Salmonella dan colonias incoloras.","source":"Cuadernillo Núcleo 6 Digestivo 2026 (TP 14, diagnóstico microbiológico) · Compendio ADN (7.e.b, 7.f.a)"},
    {"id":"n6-d-12","nucleo":"6","difficulty":"dificil","topic":"Infección del tracto urinario","q":"¿Qué recuento en orina de micción espontánea define bacteriuria significativa en una embarazada?","a":["Más de 100.000 UFC/ml de un único uropatógeno","Más de 1.000 UFC/ml de un único uropatógeno","Cualquier recuento, siempre que haya piuria en el sedimento","Más de 10.000 UFC/ml de dos o más uropatógenos distintos"],"c":0,"exp":"Por micción espontánea se exige más de 100.000 UFC/ml de un único uropatógeno; por sondaje vesical, más de 1.000, y por punción suprapúbica cualquier cantidad. En el embarazo basta un urocultivo positivo.","source":"Cuadernillo Núcleo 6.1 Agentes Urinarios 2026 (ITU en la embarazada)"},
    {"id":"n6-d-13","nucleo":"6","difficulty":"dificil","topic":"Escherichia coli uropatógena","q":"¿Qué mecanismo de Escherichia coli uropatógena explica las infecciones urinarias recurrentes?","a":["Las comunidades bacterianas intracelulares en la vejiga","La producción de toxina Shiga en el urotelio vesical","La formación de esporas resistentes en la pared de la vejiga","La variación de fase de los antígenos flagelares H y capsulares K"],"c":0,"exp":"Tras adherirse por fimbrias tipo 1, E. coli invade las células vesicales y forma comunidades bacterianas intracelulares (\"pods\"), reservorios desde los que luego sale como filamentos largos.","source":"Compendio ADN (7.h.a) · Cuadernillo Núcleo 6.1 Agentes Urinarios 2026 (Actividad 1C)"},
    {"id":"n6-d-14","nucleo":"6","difficulty":"dificil","topic":"Infección del tracto urinario","q":"¿Cuál es la función de la proteína de Tamm-Horsfall (uromodulina) en la defensa urinaria?","a":["Se une a las fimbrias bacterianas e impide la adherencia","Secuestra los sideróforos para privar a la bacteria de hierro","Opsoniza las bacterias para su fagocitosis por neutrófilos","Forma poros en la membrana bacteriana, como la catelicidina"],"c":0,"exp":"La uromodulina, producida en el asa de Henle, se une a las bacterias por sus fimbrias tipo 1, les impide adherirse a la mucosa vesical y las agrega para eliminarlas con la orina. La NGAL es la que secuestra sideróforos.","source":"Cuadernillo Núcleo 6.1 Agentes Urinarios 2026 (Actividad 1A) · Compendio ADN (7.h)"},
    {"id":"n6-d-15","nucleo":"6","difficulty":"dificil","topic":"Infección del tracto urinario","q":"Una paciente tuvo tres episodios de cistitis en un año, todos por E. coli pero con distinto genotipo y antibiograma. ¿Cómo se denomina cada episodio nuevo?","a":["Reinfección","Recidiva","Bacteriuria asintomática","ITU complicada"],"c":0,"exp":"La recidiva es un segundo episodio por el mismo microorganismo; la reinfección, por uno distinto, aunque ambos sean E. coli con distinto genotipo. Más de 3 episodios por año, o 2 en 6 meses, se llama recurrencia.","source":"Compendio ADN (7.h) · Cuadernillo Núcleo 6.1 Agentes Urinarios 2026 (Actividad 4)"},
    {"id":"n6-d-16","nucleo":"6","difficulty":"dificil","topic":"Diagnóstico de laboratorio","q":"En un sedimento de orina, ¿qué sugiere la presencia de cilindros leucocitarios?","a":["Que la infección compromete el parénquima renal","Que la muestra se recogió de manera inadecuada","Que hay bacterias ureolíticas en la orina fresca","Que existe una fístula entre el intestino y la vía urinaria"],"c":0,"exp":"Los cilindros leucocitarios o bacterianos localizan la infección a nivel renal (parenquimatosa). Los cristales de fosfato amónico-magnésico, en cambio, orientan a bacterias ureolíticas.","source":"Cuadernillo Núcleo 6.1 Agentes Urinarios 2026 (Actividad 3a) · Compendio ADN (7.h)"},
    {"id":"n6-d-17","nucleo":"6","difficulty":"dificil","topic":"Echovirus","q":"Un bebé de 2 meses tiene fiebre, diarrea líquida e irritabilidad, y un hermanito empezó con el mismo cuadro. Entre los Picornaviridae, ¿qué agente es el más probable?","a":["Echovirus","Rinovirus","Poliovirus","Coxsackie A"],"c":0,"exp":"El rinovirus no da diarrea, el poliovirus es neurotrópico y Coxsackie A causa herpangina y exantemas; el echovirus (por ejemplo el 11) coincide con fiebre, diarrea, irritabilidad y transmisión familiar.","source":"Cuadernillo Núcleo 6 Digestivo 2026 (Seminario 8, Grupo 4) · Compendio ADN (7.c.b, 7.c.c)"},
    {"id":"n6-d-18","nucleo":"6","difficulty":"dificil","topic":"Respuesta inmune","q":"¿Qué consecuencia epidemiológica tiene la variación antigénica de los parásitos?","a":["Permite reinfecciones y transmisión continua en zonas endémicas","Genera inmunidad esterilizante tras el primer contacto con el parásito","Impide la aparición de portadores sanos en la población","Hace innecesaria la colaboración de los linfocitos T CD4"],"c":0,"exp":"Al variar sus antígenos, los parásitos evaden la inmunidad adquirida y el huésped se vuelve resistente sólo después de exponerse a numerosas cepas: hay reinfecciones, cronicidad y transmisión sostenida.","source":"Compendio ADN (7.i.f)"},
    {"id":"n7-f-01","nucleo":"7","difficulty":"facil","topic":"Mycobacterium tuberculosis","q":"¿Con qué coloración se visualiza Mycobacterium tuberculosis en una muestra de esputo?","a":["Ziehl-Neelsen","Gram","Giemsa","Grocott"],"c":0,"exp":"Por su pared rica en lípidos es un bacilo ácido-alcohol resistente: se tiñe con fucsina y resiste la decoloración alcohol-ácida (baciloscopia). Grocott tiñe hongos y Giemsa se usa para parásitos y para H. pylori.","source":"Cuadernillo Núcleo 7 Laboratorio 2026 (TP 16 y TP 17) · Compendio ADN (6.e.a)"},
    {"id":"n7-f-02","nucleo":"7","difficulty":"facil","topic":"Bordetella pertussis","q":"¿Qué agente causa la tos convulsa o coqueluche?","a":["Bordetella pertussis","Corynebacterium diphtheriae","Haemophilus influenzae tipo b","Mycoplasma pneumoniae"],"c":0,"exp":"La produce B. pertussis. Se previene con vacunas con componente pertussis: quíntuple (celular) a los 2, 4 y 6 meses, cuádruple a los 15-18 meses, triple bacteriana a los 5-6 años y dTpa (acelular) a los 11 años y en embarazadas.","source":"Cuadernillo Núcleo 7 Seminario 2026 (Seminario 11) · Compendio ADN (6.c.e)"},
    {"id":"n7-f-03","nucleo":"7","difficulty":"facil","topic":"Virus sincicial respiratorio","q":"¿Cuál es la causa más habitual de infección aguda y grave de las vías aéreas inferiores en lactantes?","a":["Virus sincicial respiratorio","Rinovirus","Virus parainfluenza","Adenovirus"],"c":0,"exp":"El VSR es la causa más habitual de bronquiolitis y neumonía en lactantes y niños pequeños; casi todos se infectan antes de los 2 a 4 años y el mayor riesgo está entre las 6 y 12 semanas de vida.","source":"Cuadernillo Núcleo 7 Seminario 2026 (Seminario 10) · Compendio ADN (6.a.b)"},
    {"id":"n7-f-04","nucleo":"7","difficulty":"facil","topic":"Rinovirus","q":"La mayoría de las infecciones de vías aéreas superiores son virales. ¿Qué virus es el principal responsable del resfrío común?","a":["Rinovirus","Virus de la influenza A","Virus sincicial respiratorio","Virus de Epstein-Barr"],"c":0,"exp":"Las IVAS (rinitis, faringitis, laringitis, otitis media) son en su mayoría virales, sobre todo por rinovirus, y suelen ser autolimitadas. Los coronavirus son la segunda causa de resfrío común.","source":"Cuadernillo Núcleo 7 Laboratorio 2026 (TP 15) · Compendio ADN (6.a.d)"},
    {"id":"n7-f-05","nucleo":"7","difficulty":"normal","topic":"Corynebacterium diphtheriae","q":"Un niño con vacunas incompletas presenta fiebre, odinofagia intensa y una seudomembrana adherente en las fauces. ¿Qué agente hay que sospechar?","a":["Corynebacterium diphtheriae","Streptococcus pneumoniae","Mycoplasma pneumoniae","Klebsiella pneumoniae"],"c":0,"exp":"La difteria respiratoria forma una seudomembrana adherente de bacterias, fibrina, linfocitos y células muertas. Se previene con el toxoide diftérico (quíntuple, triple y doble bacteriana).","source":"Cuadernillo Núcleo 7 Seminario 2026 (Seminario 11, caso clínico 1) · Compendio ADN (6.c.h)"},
    {"id":"n7-f-06","nucleo":"7","difficulty":"facil","topic":"Streptococcus pyogenes","q":"¿Qué se observa al estudiar Streptococcus pyogenes en el laboratorio?","a":["Cocos gram positivos en cadenas, beta-hemolíticos","Diplococos gram positivos encapsulados con alfa-hemólisis en agar sangre","Cocobacilos gram negativos muy pequeños que necesitan agar chocolate","Bacilos gram positivos pleomorfos con forma de garrote y tinción irregular"],"c":0,"exp":"S. pyogenes son cocos gram positivos en cadenas que en agar sangre dan colonias blancas de 1 a 2 mm con grandes zonas de beta-hemólisis a las 24 h de incubación.","source":"Cuadernillo Núcleo 7 Seminario 2026 (Seminario 11) · Compendio ADN (6.c.a)"},
    {"id":"n7-f-07","nucleo":"7","difficulty":"facil","topic":"Virus de la influenza","q":"¿En base a qué proteínas de superficie se clasifican las cepas de influenza A, como H1N1 o H3N2?","a":["Hemaglutinina y neuraminidasa","Proteína F y proteína G","Proteína spike y proteína N","Proteínas VP1 a VP4"],"c":0,"exp":"La hemaglutinina (16 subtipos) se une al ácido siálico y la neuraminidasa (9 subtipos) facilita la liberación viral. Sus combinaciones definen las cepas de influenza A.","source":"Cuadernillo Núcleo 7 Seminario 2026 (Seminario 10, Actividad 2) · Compendio ADN (6.a.c)"},
    {"id":"n7-f-08","nucleo":"7","difficulty":"facil","topic":"Prevención","q":"¿A quiénes se aplica la vacuna BCG en el Calendario Nacional argentino?","a":["A todos los recién nacidos","A los niños de 2, 4 y 6 meses","A los contactos adultos de un caso de tuberculosis","A los pacientes inmunodeprimidos con PPD negativa"],"c":0,"exp":"La BCG se da al recién nacido. Reduce mucho la incidencia en personas jóvenes, es menos eficaz en adultos y no se usa en inmunodeprimidos; deja la prueba de tuberculina positiva.","source":"Compendio ADN (6.e.a, vacunación) · Cuadernillo Núcleo 7 Laboratorio 2026 (TP 17)"},
    {"id":"n7-f-09","nucleo":"7","difficulty":"facil","topic":"Streptococcus pneumoniae","q":"¿Qué agente es un diplococo gram positivo encapsulado, alfa-hemolítico, que coloniza la orofaringe?","a":["Streptococcus pneumoniae","Streptococcus pyogenes","Moraxella catarrhalis","Bordetella pertussis"],"c":0,"exp":"El neumococo es un diplococo gram positivo encapsulado, aerobio y anaerobio facultativo, que coloniza la orofaringe y da colonias alfa-hemolíticas en agar sangre.","source":"Cuadernillo Núcleo 7 Seminario 2026 (Seminario 11, cuadro de IVAI) · Compendio ADN (6.c.b)"},
    {"id":"n7-f-10","nucleo":"7","difficulty":"facil","topic":"Respuesta inmune","q":"¿Qué mecanismo atrapa las partículas inhaladas en el moco y las transporta hacia la tráquea antes de que lleguen al alvéolo?","a":["El sistema mucociliar","La opsonización por IgG del alvéolo","La citotoxicidad de las células NK","La activación del complemento por la vía clásica"],"c":0,"exp":"Las secreciones mucosas más el batido de los cilios del epitelio respiratorio barren las partículas hacia la tráquea. Junto a las barreras anatómicas y el reflejo de la tos son la primera línea de defensa.","source":"Cuadernillo Núcleo 7 Seminario 2026 (Seminario 10, Actividad 1) · Compendio ADN (6, inmunidad del sistema respiratorio)"},
    {"id":"n7-n-01","nucleo":"7","difficulty":"normal","topic":"Streptococcus pneumoniae","q":"¿Cuál es el principal factor de virulencia de Streptococcus pneumoniae y cómo actúa?","a":["La cápsula de polisacáridos, que inhibe la fagocitosis","La neumolisina, que degrada la IgA secretora del moco","La proteína M, que bloquea el depósito de C3b sobre la bacteria","El lipopolisacárido, que induce la inflamación de las meninges"],"c":0,"exp":"La cápsula es el principal factor de virulencia: las cepas no encapsuladas no son virulentas. La neumolisina forma poros al unirse al colesterol y la proteasa de IgA es la que degrada la IgA secretora.","source":"Cuadernillo Núcleo 7 Seminario 2026 (Seminario 11, Actividad 2) · Compendio ADN (6.c.b)"},
    {"id":"n7-n-02","nucleo":"7","difficulty":"normal","topic":"Streptococcus pneumoniae","q":"¿Cómo se produce la mayor parte de las infecciones por Streptococcus pneumoniae?","a":["Por diseminación endógena desde la nasofaringe colonizada","Por gotitas respiratorias de persona a persona, con epidemias frecuentes","Por vía fecal-oral a partir de agua o alimentos contaminados","Por contacto con fómites e instrumental del ambiente hospitalario"],"c":0,"exp":"El neumococo coloniza la nasofaringe y llega por aspiración a los pulmones o por vía hematógena a senos, oído medio y meninges. La transmisión interpersonal por gotitas es rara.","source":"Compendio ADN (6.c.b, vías de transmisión) · Cuadernillo Núcleo 7 Seminario 2026 (cuadro de IVAI)"},
    {"id":"n7-n-03","nucleo":"7","difficulty":"normal","topic":"Haemophilus influenzae","q":"¿En qué medio se cultiva Haemophilus influenzae a partir de una muestra respiratoria?","a":["Agar chocolate","Agar sangre al 5%","Löwenstein-Jensen","Agar Sabouraud"],"c":0,"exp":"Necesita factores X (hemina) y V (NAD): al calentar el agar sangre se lisan los glóbulos rojos, se liberan ambos y se inactivan las NADasas; ese es el agar chocolate. Löwenstein-Jensen es para micobacterias y Sabouraud para hongos.","source":"Cuadernillo Núcleo 7 Seminario 2026 (Seminario 11, cuadro de IVAI) · Compendio ADN (6.c.d)"},
    {"id":"n7-n-04","nucleo":"7","difficulty":"normal","topic":"Haemophilus influenzae","q":"¿Cuál es el principal factor de virulencia de Haemophilus influenzae tipo b, que además es el antígeno de la vacuna conjugada?","a":["La cápsula de fosfato de polirribitol (PRP)","El lipopolisacárido con lípido A de su membrana externa","La proteasa de IgA1 que facilita la colonización mucosa","Las adhesinas no pilosas de la superficie bacteriana"],"c":0,"exp":"La cápsula de PRP es antifagocítica y define al serotipo b como el más virulento. La prevención es la inmunización activa con PRP purificado conjugado, que en el país va en la quíntuple.","source":"Compendio ADN (6.c.d) · Cuadernillo Núcleo 7 Seminario 2026 (Seminario 11)"},
    {"id":"n7-n-05","nucleo":"7","difficulty":"normal","topic":"Bordetella pertussis","q":"¿Qué efecto tiene la toxina pertussis sobre la célula del huésped?","a":["Aumenta el AMPc al inactivar la proteína Gi","Produce ciliostasis al interferir la síntesis de ADN de la célula ciliada","Inhibe la síntesis de proteínas y daña el corazón y los nervios","Forma poros en la membrana al unirse al colesterol celular"],"c":0,"exp":"La toxina pertussis inactiva la proteína Gi y sube el AMPc, lo que aumenta las secreciones y la producción de mucosidad de la fase paroxística; además inhibe la fagocitosis y la migración de monocitos.","source":"Compendio ADN (6.c.e, factores de virulencia) · Cuadernillo Núcleo 7 Seminario 2026 (Seminario 11, Actividad 3)"},
    {"id":"n7-n-06","nucleo":"7","difficulty":"normal","topic":"Virus parainfluenza","q":"¿Qué virus respiratorio es la causa más frecuente de laringotraqueobronquitis (crup) en lactantes?","a":["Virus parainfluenza","Virus de Epstein-Barr","Rinovirus","Virus sincicial respiratorio"],"c":0,"exp":"Los parainfluenza (familia Paramyxoviridae, 4 serotipos) dan resfrío común, bronquitis y laringotraqueobronquitis o crup en lactantes; se diagnostican por aspirado nasal con inmunofluorescencia y PCR.","source":"Compendio ADN (6.a, cuadro de parainfluenza y metaneumovirus; el compendio aclara que viene del video seminario y no del cuadernillo)"},
    {"id":"n7-n-07","nucleo":"7","difficulty":"normal","topic":"Corynebacterium diphtheriae","q":"¿De qué depende que una cepa de Corynebacterium diphtheriae produzca toxina diftérica?","a":["De la lisogenia por el fago beta, que aporta el gen tox","De una cápsula de polisacáridos con más de 90 serotipos","De un plásmido que se transfiere entre cepas por conjugación","De los ácidos micólicos de cadena corta de su pared celular"],"c":0,"exp":"La toxina diftérica es una exotoxina A-B codificada por el gen tox, introducido por un bacteriófago lisogénico. La subunidad A inhibe la síntesis de proteínas y afecta sobre todo corazón y sistema nervioso.","source":"Compendio ADN (6.c.h) · Cuadernillo Núcleo 7 Seminario 2026 (Seminario 11, Actividad 3)"},
    {"id":"n7-n-08","nucleo":"7","difficulty":"normal","topic":"Mycoplasma pneumoniae","q":"¿Por qué Mycoplasma pneumoniae es resistente a penicilinas, cefalosporinas y vancomicina?","a":["Porque carece de pared celular","Porque produce una betalactamasa de amplio espectro","Porque es un parásito intracelular obligado inaccesible al fármaco","Porque su pared está formada por ácidos micólicos hidrofóbicos"],"c":0,"exp":"No tiene pared celular y su membrana contiene esteroles, así que los antibióticos que actúan sobre la pared no le hacen nada. Es pleomorfo y tan chico que atraviesa filtros de 0,45 µm.","source":"Compendio ADN (6.c.f) · Cuadernillo Núcleo 7 Seminario 2026 (Seminario 11, Actividad 4)"},
    {"id":"n7-n-09","nucleo":"7","difficulty":"normal","topic":"Mycoplasma pneumoniae","q":"¿Cómo daña Mycoplasma pneumoniae el epitelio respiratorio?","a":["Se adhiere por la adhesina P1 y produce ciliostasis","Invade los neumocitos y se replica dentro de fagosomas celulares","Libera una exotoxina A-B que inhibe la síntesis proteica del epitelio","Forma una seudomembrana de fibrina, bacterias y células muertas"],"c":0,"exp":"Se adhiere a los cilios por una estructura de anclaje con la adhesina P1, causa ciliostasis y destruye primero los cilios y después las células ciliadas: de ahí la tos seca persistente.","source":"Compendio ADN (6.c.f, factores de virulencia) · Cuadernillo Núcleo 7 Seminario 2026 (Seminario 11, Actividad 4)"},
    {"id":"n7-n-10","nucleo":"7","difficulty":"normal","topic":"Chlamydophila pneumoniae","q":"En el ciclo de desarrollo de Chlamydophila pneumoniae, ¿cuál es la forma infecciosa?","a":["El cuerpo elemental","El cuerpo reticulado","El cuerpo de inclusión intranuclear","La forma L sin pared celular"],"c":0,"exp":"El cuerpo elemental es infeccioso y metabólicamente inactivo, resistente como una espora; dentro del fagosoma se transforma en cuerpo reticulado, que se replica por fisión binaria pero no es infeccioso.","source":"Compendio ADN (6.c.g) · Cuadernillo Núcleo 7 Seminario 2026 (Seminario 11, Actividad 4)"},
    {"id":"n7-n-11","nucleo":"7","difficulty":"normal","topic":"Klebsiella pneumoniae","q":"¿Qué caracteriza a Klebsiella pneumoniae como agente de infección de la vía aérea inferior?","a":["Bacilo gram negativo inmóvil y encapsulado, de epidemiología nosocomial","Cocobacilo gram negativo aerobio estricto, que no fermenta carbohidratos","Diplococo gram positivo encapsulado que coloniza la orofaringe del niño","Bacilo ácido-alcohol resistente de crecimiento lento en medios sólidos"],"c":0,"exp":"Klebsiella es una enterobacteria gram negativa, no móvil, cuya cápsula es el determinante de virulencia; su epidemiología es nosocomial y se diagnostica por cultivo de secreciones respiratorias.","source":"Cuadernillo Núcleo 7 Seminario 2026 (Seminario 11, cuadro de IVAI) · Compendio ADN (6.c, cuadro de la cátedra)"},
    {"id":"n7-n-12","nucleo":"7","difficulty":"normal","topic":"Streptococcus pyogenes","q":"¿Cómo contribuye la proteína M a la virulencia de Streptococcus pyogenes?","a":["Bloquea la unión de C3b e interfiere la fagocitosis","Inactiva el C5a y así evita la llegada de los neutrófilos","Degrada el plasminógeno y disuelve los coágulos de fibrina","Lisa eritrocitos y leucocitos y genera anticuerpos ASLO"],"c":0,"exp":"La proteína M interfiere la fagocitosis al bloquear la unión de C3b y unirse al Fc de los anticuerpos o a la fibronectina. El C5a lo inactiva la peptidasa de C5a y la estreptocinasa degrada plasminógeno.","source":"Compendio ADN (6.c.a) · Cuadernillo Núcleo 7 Seminario 2026 (Seminario 11, Actividad 1)"},
    {"id":"n7-n-13","nucleo":"7","difficulty":"normal","topic":"Virus de la influenza","q":"En el virus influenza, ¿qué caracteriza al shift antigénico?","a":["Son rearreglos génicos entre un virus aviar y uno humano, solo en influenza A","Son mutaciones puntuales en HA y NA que ocurren solo en influenza B","Ocurre en influenza A y B y explica las epidemias estacionales","Cambia la polaridad del genoma viral y permite replicar en el citoplasma"],"c":0,"exp":"El shift es un cambio mayor por rearreglo de segmentos entre genomas de un virus aviar y uno humano: solo pasa en influenza A y puede dar pandemias. El drift son mutaciones puntuales y da epidemias.","source":"Cuadernillo Núcleo 7 Seminario 2026 (Seminario 10, Actividad 2) · Compendio ADN (6.a.c)"},
    {"id":"n7-n-14","nucleo":"7","difficulty":"normal","topic":"Virus sincicial respiratorio","q":"¿Qué proteína del virus sincicial respiratorio permite la entrada a la célula y explica la formación de sincitios?","a":["La proteína F, de fusión","La proteína G, de adhesión al receptor","La hemaglutinina-neuraminidasa (HN)","La proteína M de la matriz viral"],"c":0,"exp":"La proteína F fusiona la envoltura con la membrana plasmática y fusiona las células infectadas entre sí, formando sincitios (masas multinucleadas). La G es la que se une al receptor celular.","source":"Compendio ADN (6.a.b y familia Paramyxoviridae) · Cuadernillo Núcleo 7 Seminario 2026 (Seminario 10, Actividad 1)"},
    {"id":"n7-n-15","nucleo":"7","difficulty":"normal","topic":"Adenovirus","q":"¿Qué consecuencia tiene para el adenovirus el hecho de ser un virus desnudo, sin envoltura?","a":["Resiste el pH ácido y la bilis, y se transmite también por vía fecal-oral","Pierde rápido su infectividad sobre fómites y superficies secas del ambiente","Sale de la célula por gemación y adquiere así una envoltura lipídica propia","Replica su genoma en el citoplasma usando una polimerasa de la célula"],"c":0,"exp":"La ausencia de envoltura lo hace resistente a detergentes, desecación, pH ácido, bilis y cloro: sobrevive en el ambiente y se transmite por aerosoles, fómites, vía fecal-oral y agua mal clorada.","source":"Compendio ADN (6.a.a) · Cuadernillo Núcleo 7 Seminario 2026 (Seminario 10, Actividad 1)"},
    {"id":"n7-n-16","nucleo":"7","difficulty":"normal","topic":"Rinovirus","q":"¿Qué receptor celular usa la mayoría de los serotipos de rinovirus para infectar el epitelio nasal?","a":["ICAM-1","El ácido siálico","CD21","La enzima convertidora de angiotensina 2"],"c":0,"exp":"Al menos el 80% de los serotipos usa ICAM-1. Su cultivo se hace en fibroblastos a 33 °C y no replica en el tubo digestivo porque es sensible al pH ácido.","source":"Compendio ADN (6.a.d) · Cuadernillo Núcleo 7 Laboratorio 2026 (TP 15)"},
    {"id":"n7-n-17","nucleo":"7","difficulty":"normal","topic":"Coronavirus (SARS-CoV-2)","q":"¿Qué diferencia hay entre el genoma del virus influenza y el del SARS-CoV-2?","a":["Influenza tiene ARN negativo segmentado y SARS-CoV-2 ARN positivo no segmentado","Influenza tiene ARN positivo no segmentado y SARS-CoV-2 ARN negativo segmentado","Influenza tiene ADN bicatenario nuclear y SARS-CoV-2 ARN positivo segmentado","Los dos tienen ARN negativo segmentado, pero influenza replica en el citoplasma"],"c":0,"exp":"Influenza es ARN monocatenario negativo en 8 segmentos y replica en el núcleo; los coronavirus son ARN positivo no segmentado con replicación citoplasmática. Los dos son virus con envoltura.","source":"Cuadernillo Núcleo 7 Seminario 2026 (Seminario 10, Actividad 3) · Compendio ADN (6.a.c y 6.a.g)"},
    {"id":"n7-n-18","nucleo":"7","difficulty":"normal","topic":"Virus de Epstein-Barr","q":"¿A través de qué receptor infecta el virus de Epstein-Barr a los linfocitos B?","a":["CD21","CD4","ICAM-1","El receptor de Coxsackie-adenovirus"],"c":0,"exp":"La glucoproteína gp350/220 se une a CD21 (receptor de C3d) en los linfocitos B, donde el virus persiste latente de por vida. Se transmite por saliva y causa mononucleosis infecciosa.","source":"Compendio ADN (6.a.f)"},
    {"id":"n7-n-19","nucleo":"7","difficulty":"normal","topic":"Respuesta inmune","q":"¿Cuál es el anticuerpo que constituye la principal defensa en la superficie de la mucosa respiratoria?","a":["La IgA secretora","La IgG4","La IgE unida a mastocitos","La IgM natural de los linfocitos B1"],"c":0,"exp":"La IgA secretora está en altas concentraciones en las secreciones bronquiales, neutraliza toxinas, virus y bacterias, y facilita su eliminación mucociliar. En el espacio alveolar la predominante es la IgG.","source":"Compendio ADN (6, inmunidad adaptativa del pulmón) · Cuadernillo Núcleo 7 Seminario 2026 (Seminario 10, Actividad 1)"},
    {"id":"n7-n-20","nucleo":"7","difficulty":"normal","topic":"Diagnóstico de laboratorio","q":"De estos estudios del laboratorio respiratorio, ¿cuál es un método diagnóstico indirecto?","a":["El enzimoinmunoensayo que detecta anticuerpos","La inmunocromatografía lateral que detecta antígeno viral","El cultivo viral en líneas celulares","La RT-PCR en hisopado nasofaríngeo"],"c":0,"exp":"Los métodos indirectos evalúan la respuesta inmune del paciente, o sea los anticuerpos. Detectar antígeno, genoma o cultivar el agente son métodos directos.","source":"Cuadernillo Núcleo 7 Laboratorio 2026 (TP 15, Actividad 1) · Compendio ADN (6.b)"},
    {"id":"n7-d-01","nucleo":"7","difficulty":"dificil","topic":"Streptococcus pneumoniae","q":"Alejandro, 68 años, sin vacunas desde la adolescencia, con fiebre, expectoración verdosa, dolor en punta de costado y rales en la base derecha. El hemocultivo es positivo a las 18 h con diplococos gram positivos. ¿Cuál es el agente más probable?","a":["Streptococcus pneumoniae","Klebsiella pneumoniae","Haemophilus influenzae","Mycobacterium tuberculosis"],"c":0,"exp":"Diplococos gram positivos en hemocultivo más neumonía de comienzo brusco con dolor pleurítico: neumococo. Conviene pedir esputo y, al alta, indicar la vacunación antineumocócica.","source":"Cuadernillo Núcleo 7 Laboratorio 2026 (TP 16, caso 1) · Compendio ADN (6.c.b)"},
    {"id":"n7-d-02","nucleo":"7","difficulty":"dificil","topic":"Diagnóstico de laboratorio","q":"Coty, 10 años, consulta por odinofagia, fiebre de 38 °C, adenopatía submentoniana y placas blanquecinas en ambas amígdalas. ¿Qué muestra y determinaciones corresponde pedir?","a":["Exudado de fauces con dos hisopos: test rápido de antígeno y cultivo en agar sangre","Hisopado nasofaríngeo para RT-PCR múltiple de virus respiratorios","Esputo seriado de tres días para baciloscopia de Ziehl-Neelsen","Hemocultivos seriados antes de iniciar el tratamiento antibiótico"],"c":0,"exp":"La sospecha es faringitis por S. pyogenes: el test rápido por inmunocromatografía da resultado en minutos y el cultivo en agar sangre al 5% confirma o descarta a las 24-48 h, con hisopos distintos.","source":"Cuadernillo Núcleo 7 Laboratorio 2026 (TP 16, caso 3 y Actividad 2) · Compendio ADN (6.d, cuadro de muestras)"},
    {"id":"n7-d-03","nucleo":"7","difficulty":"dificil","topic":"Mycoplasma pneumoniae","q":"Varón de 22 años, sano, con fiebre de una semana, mialgias, cefalea y tos seca irritativa, sin disnea y con saturación normal. La Rx de tórax muestra infiltrados bilaterales intersticiales. ¿Cuál es el agente más probable?","a":["Mycoplasma pneumoniae","Staphylococcus aureus","Moraxella catarrhalis","Mycobacterium tuberculosis"],"c":0,"exp":"Es una neumonía atípica o ambulatoria: poca semiología frente a una radiografía parcheada llamativa, tos seca y faringitis en un joven. Al no tener pared celular, no responde a betalactámicos.","source":"Cuadernillo Núcleo 7 Seminario 2026 (Seminario 11, caso clínico 2) · Compendio ADN (6.c.f)"},
    {"id":"n7-d-04","nucleo":"7","difficulty":"dificil","topic":"Enterovirus (Coxsackie)","q":"¿Qué cuadros produce el virus Coxsackie del grupo A en niños pequeños?","a":["Herpangina y enfermedad de manos, pies y boca","Crup y bronquiolitis con sibilancias en el lactante","Queratoconjuntivitis epidémica y fiebre faringoconjuntival","Mononucleosis infecciosa con linfocitos atípicos"],"c":0,"exp":"Coxsackie (Picornaviridae, Enterovirus) se transmite por vía fecal-oral y también por gotitas. El grupo A da herpangina y manos-pies-boca; el B, miocarditis, pleurodinia y meningitis aséptica.","source":"Compendio ADN (6.a.e)"},
    {"id":"n7-d-05","nucleo":"7","difficulty":"dificil","topic":"Mycobacterium tuberculosis","q":"Ante sospecha de tuberculosis pulmonar se piden tres esputos, a primera hora de la mañana y en días consecutivos. ¿Por qué se repite la muestra?","a":["Porque la eliminación de bacilos no es constante","Porque recién en la tercera muestra se puede evaluar la resistencia a rifampicina","Porque hacen falta tres cultivos para descartar la flora de las vías aéreas altas","Porque el bacilo se multiplica en el frasco y la primera muestra da falsos negativos"],"c":0,"exp":"La eliminación de bacilos en el esputo es intermitente, así que se repite la toma tres días seguidos, con higiene bucal previa y esfuerzo de tos, para que la muestra represente la vía aérea inferior.","source":"Cuadernillo Núcleo 7 Laboratorio 2026 (TP 17, caso Emiliano y obtención de la muestra)"},
    {"id":"n7-d-06","nucleo":"7","difficulty":"dificil","topic":"Mycobacterium tuberculosis","q":"Julio, 48 años, con VIH y mala adherencia al tratamiento, tiene tos con expectoración, sudoración nocturna y chuchos de frío. ¿Por qué su baciloscopia de esputo puede ser negativa aun teniendo tuberculosis?","a":["Porque sin hipersensibilidad no hay cavitación y los bacilos no se eliminan","Porque en el paciente con VIH la carga de bacilos en el pulmón es menor","Porque en el VIH la tuberculosis es siempre extrapulmonar","Porque el esputo de la mañana diluye los bacilos y da falsos negativos"],"c":0,"exp":"En el paciente VIH positivo hay más bacilos, pero sin respuesta de hipersensibilidad tipo IV no se destruye el parénquima ni se forman cavernas, por lo que el esputo puede resultar negativo.","source":"Cuadernillo Núcleo 7 Laboratorio 2026 (TP 16, caso 4 y TP 17, mecanismo de infección) · Compendio ADN (6.e.a)"},
    {"id":"n7-d-07","nucleo":"7","difficulty":"dificil","topic":"Mycobacterium tuberculosis","q":"¿Dónde se localizan la tuberculosis primaria y la reactivación del adulto?","a":["La primaria en el sector inferior del lóbulo superior o superior del inferior, y la reactivación en el ápice","Las dos en los vértices pulmonares, porque son los sectores mejor ventilados","La primaria en el ápice y la reactivación en las bases, por diseminación hematógena","Las dos en la base derecha, siguiendo el trayecto del bronquio principal"],"c":0,"exp":"La primaria forma el complejo de Ghon (lesión subpleural más ganglio hiliar con necrosis caseosa). La reactivación se da en el ápice, el sector más oxigenado, con cavernas y fibrosis posterior.","source":"Cuadernillo Núcleo 7 Laboratorio 2026 (TP 17, mecanismo de infección) · Compendio ADN (6.e.a)"},
    {"id":"n7-d-08","nucleo":"7","difficulty":"dificil","topic":"Mycobacterium tuberculosis","q":"En un preparado de pulmón con tuberculosis teñido con hematoxilina-eosina, ¿qué se observa en el granuloma?","a":["Necrosis caseosa central rodeada de linfocitos, histiocitos y células de Langhans","Un infiltrado de neutrófilos con abundantes bacilos rosados en el centro","Alvéolos ocupados por exudado fibrinoso sin células inflamatorias","Sincitios multinucleados con cuerpos de inclusión intranucleares"],"c":0,"exp":"El granuloma tiene necrosis caseosa central rodeada de linfocitos, histiocitos y células multinucleadas de Langhans; también hay granulomas sin necrosis. Es la expresión de la hipersensibilidad tipo IV.","source":"Cuadernillo Núcleo 7 Laboratorio 2026 (TP 17, Actividad 2) · Compendio ADN (6.e.a)"},
    {"id":"n7-d-09","nucleo":"7","difficulty":"dificil","topic":"Diagnóstico de laboratorio","q":"¿Qué información aporta el GeneXpert además de detectar Mycobacterium tuberculosis?","a":["Si la cepa tiene genes de resistencia a la rifampicina","El recuento de bacilos ácido-alcohol resistentes por campo","Si el paciente desarrolló hipersensibilidad tipo IV al bacilo","Qué especie de micobacteria atípica acompaña a la infección"],"c":0,"exp":"El GeneXpert es una PCR en tiempo real que detecta específicamente M. tuberculosis y además busca genes de resistencia a la rifampicina, una de sus principales drogas.","source":"Cuadernillo Núcleo 7 Laboratorio 2026 (TP 17, diagnóstico) · Compendio ADN (6.e)"},
    {"id":"n7-d-10","nucleo":"7","difficulty":"dificil","topic":"Diagnóstico de laboratorio","q":"¿Cuánto se incuban los cultivos de micobacterias frente a los de bacterias comunes y hongos?","a":["Micobacterias 60 días, bacterias 24 a 72 h y hongos 21 a 28 días","Micobacterias 21 a 28 días, bacterias 60 días y hongos 24 a 72 h","Los tres grupos entre 24 y 72 h, con repiques semanales posteriores","Micobacterias 7 días, bacterias 48 h y hongos 10 días"],"c":0,"exp":"Cada grupo tiene su velocidad de crecimiento: la mayoría de las bacterias desarrolla en 24 a 72 h, los hongos se incuban 21 a 28 días y las micobacterias 60 días, en medio de Löwenstein-Jensen.","source":"Cuadernillo Núcleo 7 Laboratorio 2026 (TP 16, introducción) · Compendio ADN (6.d)"},
    {"id":"n7-d-11","nucleo":"7","difficulty":"dificil","topic":"Mycobacterium leprae","q":"¿Qué forma de lepra es multibacilar y muy infecciosa?","a":["La lepromatosa, por el déficit de la respuesta celular específica","La tuberculoide, con granulomas, pocos bacilos y máculas hipopigmentadas","La lepromatosa, porque los granulomas limitan la proliferación bacteriana","La tuberculoide, porque los bacilos se concentran en los nervios periféricos"],"c":0,"exp":"En la lepra lepromatosa hay un déficit específico de la respuesta celular frente a M. leprae, con muchos bacilos en macrófagos dérmicos, células de Schwann y secreciones nasales. No se cultiva in vitro.","source":"Compendio ADN (6.e.b) · Cuadernillo Núcleo 7 Laboratorio 2026 (TP 17, introducción)"},
    {"id":"n7-d-12","nucleo":"7","difficulty":"dificil","topic":"Diagnóstico de laboratorio","q":"Una paciente consulta en la tercera semana de un cuadro respiratorio viral, ya sin síntomas, y quiere saber si tuvo la infección. ¿Qué muestra y método conviene?","a":["Sangre periférica para detectar anticuerpos específicos","Hisopado nasofaríngeo para test rápido de antígeno","Hisopado nasofaríngeo para RT-PCR del genoma viral","Lavado broncoalveolar para aislamiento en cultivo celular"],"c":0,"exp":"Los métodos directos rinden en la fase temprana, cuando el virus se está eliminando. Los anticuerpos aparecen varios días después del inicio, así que a las tres semanas sirve la serología.","source":"Cuadernillo Núcleo 7 Laboratorio 2026 (TP 15, Actividades 3 y 4) · Compendio ADN (6.b)"},
    {"id":"n7-d-13","nucleo":"7","difficulty":"dificil","topic":"Diagnóstico de laboratorio","q":"Llega al laboratorio una muestra de esputo de aspecto salivoso. ¿Cómo corresponde interpretarla?","a":["No es representativa de la vía aérea inferior","Es apta si se procesa dentro de las dos horas de la toma","Indica que la infección está en la vía aérea superior","Sirve solo para baciloscopia, no para cultivo bacteriano"],"c":0,"exp":"Un esputo salivoso representa secreciones orales y no del tracto respiratorio inferior, así que no es confiable. La aptitud se evalúa con los criterios de Murray y Washington.","source":"Cuadernillo Núcleo 7 Laboratorio 2026 (TP 15, Actividad 1 y TP 16) · Compendio ADN (6.b y 6.d)"},
    {"id":"n7-d-14","nucleo":"7","difficulty":"dificil","topic":"Respuesta inmune","q":"¿Qué subclase de IgG responde específicamente contra los polisacáridos capsulares de Streptococcus pneumoniae y Haemophilus influenzae?","a":["IgG2","IgG1","IgG3","IgG4"],"c":0,"exp":"La IgG2 es el anticuerpo específico frente a los polisacáridos capsulares de neumococo y Haemophilus. La IgG1 y la IgG3 son las únicas que fijan complemento y la IgG4 participa en respuestas alérgicas.","source":"Compendio ADN (6, inmunoglobulinas del espacio alveolar) · Cuadernillo Núcleo 7 Seminario 2026 (Seminario 10, Actividad 1)"},
    {"id":"n7-d-15","nucleo":"7","difficulty":"dificil","topic":"Adenovirus","q":"Entre adenovirus y virus sincicial respiratorio, ¿en cuál esperaría encontrar diarrea como parte del cuadro, y por qué?","a":["En el adenovirus, por su tropismo gastrointestinal y su resistencia al pH ácido","En el VSR, porque produce viremia y disemina al epitelio intestinal","En el adenovirus, porque su envoltura lipídica lo protege de la bilis","En el VSR, porque su proteína G se une a receptores del enterocito"],"c":0,"exp":"El adenovirus es desnudo, resiste pH ácido, bilis y enzimas digestivas, y además del epitelio respiratorio y conjuntival infecta el gastrointestinal. El VSR queda limitado a la vía aérea y no da viremia.","source":"Compendio ADN (6.a.a y 6.a.b) · Cuadernillo Núcleo 7 Seminario 2026 (Seminario 10, Actividad 1.b)"},
    {"id":"n7_1-f-01","nucleo":"7.1","difficulty":"facil","topic":"Infecciones del SNC","q":"¿Cuál de estas definiciones corresponde a un absceso cerebral?","a":["Una colección de pus dentro del encéfalo","La inflamación de las leptomeninges","La inflamación difusa del tejido encefálico","La obstrucción de la circulación del LCR"],"c":0,"exp":"El absceso cerebral es una colección intracerebral de pus; la meningitis es inflamación de las meninges y la encefalitis, del encéfalo.","source":"Compendio ADN 6.1 (introducción, SNC)"},
    {"id":"n7_1-f-02","nucleo":"7.1","difficulty":"facil","topic":"Anatomía del SNC y LCR","q":"¿En qué espacio circula el líquido cefalorraquídeo?","a":["En el espacio subaracnoideo","Entre la duramadre y el hueso del cráneo","Entre la duramadre y la aracnoides","Dentro del espesor de la piamadre"],"c":0,"exp":"El LCR circula en el espacio subaracnoideo, entre aracnoides y piamadre, y ahí se generan las reacciones inflamatorias de la meningitis.","source":"Compendio ADN 6.1 (anatomía de las meninges)"},
    {"id":"n7_1-f-03","nucleo":"7.1","difficulty":"facil","topic":"Neisseria meningitidis","q":"¿Cómo se transmite Neisseria meningitidis y cuál es su reservorio?","a":["Por gotas respiratorias, y el ser humano es el único reservorio","Por vía fecal-oral, con el agua contaminada como reservorio","Por heridas contaminadas con esporas presentes en el suelo","Por picadura de mosquitos, con reservorio en aves silvestres"],"c":0,"exp":"Se propaga por gotas respiratorias en contactos cercanos y prolongados; los humanos son los únicos hospedadores naturales y los portadores asintomáticos mantienen la transmisión.","source":"Compendio ADN 6.1.a.e (Neisseria meningitidis)"},
    {"id":"n7_1-f-04","nucleo":"7.1","difficulty":"facil","topic":"Clostridium tetani","q":"¿Cuál es la puerta de entrada habitual de Clostridium tetani?","a":["Heridas punzantes o abrasiones contaminadas con tierra","El contacto estrecho con un enfermo de tétanos","La ingesta de conservas caseras mal procesadas en el hogar","La inhalación de esporas aerosolizadas"],"c":0,"exp":"Las esporas, ubicuas en el suelo fértil, entran por heridas punzantes, cortes o abrasiones y germinan en condiciones anaerobias. El tétanos no se transmite de persona a persona.","source":"Compendio ADN 6.1.a.g (Clostridium tetani) · Cuadernillo Núcleo 12 Agentes de Piel 2026 (Actividad 3)"},
    {"id":"n7_1-f-05","nucleo":"7.1","difficulty":"facil","topic":"Clostridium botulinum","q":"¿Qué tipo de parálisis produce la toxina botulínica?","a":["Parálisis flácida descendente","Parálisis espástica con trismo","Parálisis ascendente con espasmos","Hemiparesia de un solo lado"],"c":0,"exp":"La toxina botulínica bloquea la liberación de acetilcolina en la placa neuromuscular y causa parálisis flácida descendente; la tetánica bloquea la inhibición y causa parálisis espástica (trismo, opistótonos).","source":"Compendio ADN 6.1.a.f (prevención) · Cuadernillo Núcleo 6 Agentes con ingreso digestivo 2026 (Actividad 2)"},
    {"id":"n7_1-f-06","nucleo":"7.1","difficulty":"facil","topic":"Enterovirus","q":"¿Cuál es la vía de transmisión de los enterovirus, principales virus causantes de meningitis viral?","a":["Fecal-oral, con alimentos y agua contaminados como fuente","Respiratoria, por aerosoles generados al toser","Sexual, por contacto con mucosa genital","Vectorial, por la picadura de mosquitos"],"c":0,"exp":"Los enterovirus se transmiten por vía fecal-oral: se replican primero en bucofaringe y tubo digestivo y después alcanzan sus tejidos diana. Los alimentos, el agua y las superficies contaminadas son fuentes importantes.","source":"Compendio ADN 6.1.b.a (Enterovirus)"},
    {"id":"n7_1-f-07","nucleo":"7.1","difficulty":"facil","topic":"Prevención","q":"¿Qué vacuna antipoliomielítica se usa hoy en el calendario argentino?","a":["La inactivada IPV/Salk: 2, 4 y 6 meses y refuerzo a los 5 años","La oral atenuada OPV/Sabin, a los 2, 4 y 6 meses","Una dosis única de vacuna atenuada a los 12 meses","Una vacuna conjugada de polisacárido con proteína transportadora"],"c":0,"exp":"Se usa la vacuna inactivada contra la poliomielitis (IPV/Salk) a los 2, 4 y 6 meses con refuerzo a los 5 años; la oral atenuada (OPV/Sabin) ya no se utiliza.","source":"Compendio ADN 6.1.b.a (vacunación) · Cuadernillo Núcleo 3 Memoria inmune 2026 (vacunas inactivadas)"},
    {"id":"n7_1-f-08","nucleo":"7.1","difficulty":"facil","topic":"Streptococcus pneumoniae","q":"¿Qué morfología y comportamiento en agar sangre tiene Streptococcus pneumoniae?","a":["Coco gram positivo encapsulado, en diplococos, alfa-hemolítico","Coco gram positivo en racimos, beta-hemolítico","Diplococo gram negativo con forma de grano de café, oxidasa positivo","Bacilo gram negativo pequeño y pleomórfico"],"c":0,"exp":"S. pneumoniae es un coco gram positivo encapsulado que se dispone en diplococos o cadenas cortas y es alfa-hemolítico en agar sangre, con más de 90 serotipos capsulares.","source":"Compendio ADN 6.1.a.c (Streptococcus pneumoniae)"},
    {"id":"n7_1-f-09","nucleo":"7.1","difficulty":"facil","topic":"Infecciones del SNC","q":"¿Qué tres manifestaciones definen al síndrome meníngeo?","a":["Fiebre, cefalea y rigidez de nuca","Fiebre, convulsiones y deterioro de la conciencia","Cefalea, afectación de pares craneales y signos focales","Fiebre, vómitos y petequias en el tronco"],"c":0,"exp":"El síndrome meníngeo combina fiebre, cefalea y rigidez. Las convulsiones, el deterioro de conciencia y la focalización corresponden al síndrome encefalítico.","source":"Compendio ADN 6.1 (síndromes neurológicos)"},
    {"id":"n7_1-f-10","nucleo":"7.1","difficulty":"facil","topic":"Mycobacterium tuberculosis","q":"¿A quiénes se les aplica la vacuna BCG y en quiénes está contraindicada?","a":["A los recién nacidos; contraindicada en inmunodeprimidos","A los 11 años; está contraindicada en embarazadas","A los adultos de riesgo, con refuerzo cada 10 años","A los lactantes a los 2, 4 y 6 meses, sin contraindicaciones"],"c":0,"exp":"La BCG se aplica al recién nacido y es eficaz sobre todo en niños, con baja eficacia en adultos. Al ser una vacuna viva atenuada está contraindicada en inmunodeprimidos.","source":"Compendio ADN 6.1.a.a (Mycobacterium tuberculosis, vacunación)"},
    {"id":"n7_1-n-01","nucleo":"7.1","difficulty":"normal","topic":"Clostridium botulinum","q":"¿Cuál es el mecanismo de acción de la toxina botulínica?","a":["Impide la liberación de acetilcolina en las sinapsis colinérgicas periféricas","Bloquea la liberación de los neurotransmisores inhibidores glicina y GABA","Destruye la mielina de los nervios periféricos por acción enzimática","Despolariza en forma sostenida la placa neuromuscular"],"c":0,"exp":"Su cadena ligera es una endopeptidasa de zinc que impide la liberación de acetilcolina y bloquea la neurotransmisión colinérgica periférica, lo que produce parálisis flácida.","source":"Compendio ADN 6.1.a.f (factores de virulencia) · Cuadernillo Núcleo 6 Agentes con ingreso digestivo 2026 (Actividad 2.c)"},
    {"id":"n7_1-n-02","nucleo":"7.1","difficulty":"normal","topic":"Clostridium tetani","q":"¿Por qué la tetanospasmina produce parálisis espástica y no flácida?","a":["Porque inactiva la liberación de glicina y GABA","Porque impide la liberación de acetilcolina en las sinapsis colinérgicas","Porque aumenta la síntesis de acetilcolina en la placa neuromuscular","Porque destruye las neuronas inhibidoras de la médula espinal"],"c":0,"exp":"Su cadena ligera, una endopeptidasa de zinc, inactiva las proteínas que regulan la liberación de glicina y GABA; sin esa inhibición, la actividad sináptica excitatoria queda sin control.","source":"Compendio ADN 6.1.a.g (factores de virulencia)"},
    {"id":"n7_1-n-03","nucleo":"7.1","difficulty":"normal","topic":"Neisseria meningitidis","q":"¿Cuál es el principal factor de virulencia de Neisseria meningitidis y qué permite además clasificarla?","a":["La cápsula de polisacárido, que define 13 serogrupos","El lipooligosacárido, que define los serogrupos A, C, Y y W135","Las proteínas PorA y PorB, que forman poros en la membrana externa","Los pili de tipo IV, que definen los serotipos capsulares"],"c":0,"exp":"La cápsula de polisacárido es el principal factor de virulencia: protege de la fagocitosis mediada por anticuerpos y permite clasificar al meningococo en 13 serogrupos.","source":"Compendio ADN 6.1.a.e (factores de virulencia)"},
    {"id":"n7_1-n-04","nucleo":"7.1","difficulty":"normal","topic":"Neisseria meningitidis","q":"¿Qué rasgos caracterizan a la meningococcemia?","a":["Trombosis de pequeños vasos, petequias y afectación multiorgánica","Tumefacción parotídea bilateral con fiebre y cefalea","Parálisis flácida descendente con compromiso respiratorio","Lesiones quísticas en el parénquima encefálico con eosinófilos en el LCR"],"c":0,"exp":"La meningococcemia es una septicemia con trombosis de los pequeños vasos y afectación multiorgánica; aparecen petequias que pueden evolucionar a lesiones hemorrágicas y hasta coagulación intravascular diseminada.","source":"Compendio ADN 6.1.a.e (cuadros clínicos)"},
    {"id":"n7_1-n-05","nucleo":"7.1","difficulty":"normal","topic":"Streptococcus agalactiae","q":"En la enfermedad neonatal tardía por Streptococcus agalactiae, ¿cuál es la manifestación predominante y en qué momento aparece?","a":["Bacteriemia con meningitis, entre la semana y los 3 meses de vida","Bacteriemia con neumonía, en las primeras 24 a 48 horas","Meningitis con petequias, en la primera semana de vida","Sepsis con compromiso osteoarticular, después de los 6 meses"],"c":0,"exp":"La enfermedad de comienzo tardío ocurre entre la primera semana y los 3 meses, se adquiere de fuentes exógenas, la causa predominantemente el serotipo III y predomina la bacteriemia con meningitis.","source":"Compendio ADN 6.1.a.d (cuadros clínicos y epidemiología)"},
    {"id":"n7_1-n-06","nucleo":"7.1","difficulty":"normal","topic":"Streptococcus agalactiae","q":"¿Qué factores aumentan el riesgo de transmisión neonatal de Streptococcus agalactiae?","a":["Parto prematuro, rotura prematura de membranas y fiebre intraparto","El parto por cesárea programada y la edad materna avanzada","La lactancia materna prolongada y el antecedente de bajo peso al nacer","El antecedente de vacunación materna incompleta"],"c":0,"exp":"La colonización vaginal materna es del 10-30% y alrededor del 60% de los hijos de madres colonizadas se coloniza; el riesgo sube con alta carga bacteriana, parto prematuro, rotura prematura de membranas y fiebre intraparto.","source":"Compendio ADN 6.1.a.d (vías de transmisión) · Cuadernillo Núcleo 9 Transmisión vertical 2026 (Actividad 3.a)"},
    {"id":"n7_1-n-07","nucleo":"7.1","difficulty":"normal","topic":"Streptococcus pneumoniae","q":"Además de la cápsula, ¿qué factor de virulencia de Streptococcus pneumoniae es citotóxico y proinflamatorio?","a":["La neumolisina","La tetanolisina","El lipooligosacárido","La proteína Opa de superficie"],"c":0,"exp":"La neumolisina es citotóxica e inflamatoria; la cápsula evita la fagocitosis, la proteasa de IgA permite evadir la mucosa y la fosforilcolina favorece la diseminación.","source":"Compendio ADN 6.1.a.c (factores de virulencia)"},
    {"id":"n7_1-n-08","nucleo":"7.1","difficulty":"normal","topic":"Haemophilus influenzae","q":"¿Qué explica que Haemophilus influenzae tipo b haya sido la causa más común de meningitis en niños antes de la vacunación?","a":["Su cápsula PRP, antifagocítica, la más virulenta de los serotipos","Su crecimiento rápido en agar sangre, que le permite invadir el LCR","Produce una neurotoxina que viaja por los nervios periféricos","Es el único serotipo capaz de colonizar la bucofaringe"],"c":0,"exp":"De los serotipos a-f, el b (cápsula PRP) es el más virulento por su acción antifagocítica; también aportan los pili, el LPS -que produce inflamación meníngea- y la proteasa de IgA1. Crece en agar chocolate.","source":"Compendio ADN 6.1.a.b (Haemophilus influenzae tipo B)"},
    {"id":"n7_1-n-09","nucleo":"7.1","difficulty":"normal","topic":"Mycobacterium tuberculosis","q":"¿En qué contexto aparece la meningitis tuberculosa y qué muestra se usa para buscar el bacilo en el SNC?","a":["En formas extrapulmonares de pacientes inmunodeprimidos, con LCR como muestra no contaminada","En la tuberculosis primaria de pacientes inmunocompetentes, con esputo seriado","Como complicación de la vacunación con BCG, con biopsia de ganglio","En la tuberculosis cavitada del ápice pulmonar, con lavado gástrico"],"c":0,"exp":"Las formas extrapulmonares (ganglios, huesos, meninges, miliar) se ven en inmunodeprimidos, y la diseminación hematógena o linfática puede complicarse con meningitis tuberculosa. El LCR es una muestra naturalmente estéril.","source":"Compendio ADN 6.1.a.a (cuadros clínicos) · Cuadernillo Núcleo 7 Laboratorio Respiratorio 2026 (mecanismo de infección y obtención de la muestra)"},
    {"id":"n7_1-n-10","nucleo":"7.1","difficulty":"normal","topic":"Enterovirus","q":"¿Cómo se caracterizan estructuralmente los enterovirus, de la familia Picornaviridae?","a":["Virus desnudos, icosaédricos, con ARN de polaridad positiva","Virus envueltos, helicoidales, con ARN de polaridad negativa","Virus desnudos con ADN bicatenario y replicación nuclear","Virus envueltos con ADN lineal de doble hebra y latencia neuronal"],"c":0,"exp":"Son los virus más pequeños: desnudos, icosaédricos, con ARN de polaridad positiva (su genoma alcanza para la infección) y replicación en el citoplasma; al ser desnudos producen lisis celular al liberarse.","source":"Compendio ADN 6.1.b.a (Enterovirus)"},
    {"id":"n7_1-n-11","nucleo":"7.1","difficulty":"normal","topic":"Arbovirus","q":"Según el material de la cátedra, ¿qué arbovirosis con compromiso neurológico se reportan con mayor frecuencia en el norte de la Argentina?","a":["La encefalitis equina del oeste y el dengue","La encefalitis japonesa y la fiebre del Nilo Occidental","La rabia y la encefalitis por sarampión","La fiebre amarilla y la fiebre de Oropouche"],"c":0,"exp":"En el norte del país hay casos esporádicos y brotes, y los más frecuentes son la encefalitis equina del oeste y el dengue; los otros arbovirus que producen encefalitis no son frecuentes en nuestro medio. Es el dato de la cátedra; en la vigilancia nacional también se reportan la encefalitis de San Luis y el virus del Nilo Occidental.","source":"Compendio ADN 6.1.b.b (Arbovirus) · Cuadernillo Núcleo 10 Vectores 2026 (tabla de ENO)"},
    {"id":"n7_1-n-12","nucleo":"7.1","difficulty":"normal","topic":"Arbovirus","q":"¿Cómo alcanza el encéfalo un arbovirus después de la viremia inicial?","a":["Infectando las células endoteliales de los vasos encefálicos","Viajando por transporte axonal retrógrado desde la picadura","Atravesando la lámina cribosa desde el epitelio olfatorio","Dentro de macrófagos infectados que cruzan los plexos coroides"],"c":0,"exp":"El virus infecta las células endoteliales de los vasos encefálicos y así accede al tejido; la respuesta inflamatoria que induce produce la destrucción tisular y la encefalitis.","source":"Compendio ADN 6.1.b.b (Arbovirus, patogenia)"},
    {"id":"n7_1-n-13","nucleo":"7.1","difficulty":"normal","topic":"Diagnóstico de laboratorio","q":"Ante la sospecha de meningitis por enterovirus, ¿qué muestra y qué método indica el material de la cátedra?","a":["PCR en LCR obtenido por punción lumbar","Serología de IgM en suero pareado","Coprocultivo con aislamiento viral en materia fecal","Hemocultivo seriado en medio enriquecido"],"c":0,"exp":"El diagnóstico se hace a partir del estudio del LCR, que se obtiene por punción lumbar, con pruebas de amplificación de ácidos nucleicos (PCR).","source":"Compendio ADN 6.1.b.a (método diagnóstico)"},
    {"id":"n7_1-n-14","nucleo":"7.1","difficulty":"normal","topic":"Virus herpes simplex","q":"¿Dónde establece la latencia el virus herpes simplex?","a":["En ganglios sensoriales: trigémino en HSV-1 y sacro en HSV-2","En los linfocitos B de memoria, como el virus de Epstein-Barr","En las células mucoepiteliales donde se replica inicialmente","En las neuronas motoras del asta anterior de la médula espinal"],"c":0,"exp":"Tras replicarse en células mucoepiteliales, el virus viaja en forma retrógrada a los ganglios sensoriales: trigémino en HSV-1 y sacro en HSV-2. En la latencia expresa los transcriptos asociados a latencia (LAT), que inhiben la apoptosis neuronal.","source":"Compendio ADN 6.1.b.c.c (Virus Herpes Simplex)"},
    {"id":"n7_1-n-15","nucleo":"7.1","difficulty":"normal","topic":"Virus de la parotiditis","q":"¿Por qué estructura llega el virus de la parotiditis al SNC durante su diseminación sistémica?","a":["Por el plexo coroideo","Por los nervios olfatorios","Por las vellosidades aracnoideas","Por los ganglios linfáticos cervicales profundos"],"c":0,"exp":"Tras replicarse en el epitelio respiratorio y producir una viremia fugaz, el virus llega al SNC a través del plexo coroideo, infecta células mononucleares y puede causar meningitis o encefalitis.","source":"Compendio ADN 6.1.b.c.b (parotiditis, células blanco)"},
    {"id":"n7_1-n-16","nucleo":"7.1","difficulty":"normal","topic":"Virus del sarampión","q":"¿Qué receptor usan las cepas salvajes del virus del sarampión para entrar a la célula?","a":["CD150 o SLAM, expresada en algunas células T y B","CD46, miembro de la superfamilia de las inmunoglobulinas","CD21, el receptor de C3d","El ácido siálico de la superficie del epitelio respiratorio"],"c":0,"exp":"La proteína H de las cepas salvajes se une a CD150/SLAM; CD46 es el receptor de las cepas vacunales y la nectina-4 funciona como receptor en células epiteliales polarizadas. A diferencia de otros paramixovirus, no usa ácido siálico.","source":"Compendio ADN 6.1.b.c.b (sarampión, células blanco)"},
    {"id":"n7_1-n-17","nucleo":"7.1","difficulty":"normal","topic":"Respuesta inmune","q":"¿Por qué se considera al SNC un sitio de privilegio inmunológico?","a":["No tiene folículos linfoides ni CPA profesionales y expresa poco CMH","La barrera hematoencefálica impide por completo el paso de linfocitos y anticuerpos","Sus neuronas expresan altos niveles de CMH I, lo que bloquea la presentación antigénica","Carece de complemento y de citoquinas proinflamatorias en todo momento"],"c":0,"exp":"En el encéfalo y la médula no hay folículos linfoides, ganglios ni células presentadoras profesionales, y la expresión de CMH I y II es muy baja para evitar autorreactividad. La protección depende de las meninges, el LCR y la barrera hematoencefálica.","source":"Compendio ADN 6.1 (privilegio inmunológico del SNC)"},
    {"id":"n7_1-n-18","nucleo":"7.1","difficulty":"normal","topic":"Respuesta inmune","q":"¿Cómo participa la inmunidad adaptativa en la defensa del SNC si el parénquima no tiene tejido linfoide?","a":["El LCR drena por el sistema glinfático a los ganglios cervicales profundos","Los linfocitos T vírgenes se activan directamente en el parénquima encefálico","Los astrocitos actúan como células presentadoras de antígeno profesionales","Los anticuerpos se producen en los plexos coroides y pasan al espacio subaracnoideo"],"c":0,"exp":"Parte del LCR drena por el sistema glinfático a los ganglios cervicales profundos llevando antígenos. Las dendríticas meníngeas los transportan allí y los linfocitos activados vuelven por homing, con las vitaminas A y D como factores clave.","source":"Compendio ADN 6.1 (inmunidad adaptativa en el SNC)"},
    {"id":"n7_1-n-19","nucleo":"7.1","difficulty":"normal","topic":"Prevención","q":"¿Cómo es el esquema de la vacuna antimeningocócica conjugada tetravalente en el calendario argentino?","a":["Dosis a los 3 y 5 meses, refuerzo a los 15 meses y a los 11 años","Dosis a los 2, 4 y 6 meses con un refuerzo a los 15-18 meses de vida","Dosis única al año de vida y refuerzo cada 10 años","Tres dosis en el primer año y una dosis en el embarazo"],"c":0,"exp":"En lactantes se aplica a los 3 y 5 meses con refuerzo a los 15 meses -el grupo con mayor riesgo de enfermar y morir- y una dosis única a los 11 años. Es la conjugada tetravalente ACYW.","source":"Compendio ADN 6.1.a.e (vacunación, esquema argentino)"},
    {"id":"n7_1-n-20","nucleo":"7.1","difficulty":"normal","topic":"Prevención","q":"¿Por qué hay que vacunar contra el tétanos incluso a alguien que ya tuvo la enfermedad?","a":["Porque la infección natural no induce inmunidad","Porque la inmunidad que deja la enfermedad dura solo un año","Porque la toxina deja anticuerpos bloqueantes que hay que neutralizar","Porque la enfermedad deja inmunidad celular pero no humoral"],"c":0,"exp":"La infección natural no confiere inmunidad: la prevención son tres dosis de toxoide tetánico con refuerzos cada 10 años (doble bacteriana en adultos), y el riesgo es mayor cuando la inmunización es inadecuada.","source":"Compendio ADN 6.1.a.g (vacunación) · Cuadernillo Núcleo 3 Memoria inmune 2026 (toxoides)"},
    {"id":"n7_1-d-01","nucleo":"7.1","difficulty":"dificil","topic":"Clostridium botulinum","q":"Una lactante de 3 meses llega con cinco días de hipoactividad, rechazo del alimento e irritabilidad, sin fiebre. La madre le dio miel por estreñimiento. ¿Qué explica el cuadro?","a":["La ingestión de esporas que colonizan el intestino","La ingestión de toxina botulínica preformada en el alimento","La germinación de esporas en una herida con tejido necrótico","La inhalación de toxina en partículas aerosolizadas"],"c":0,"exp":"En el botulismo del lactante se ingieren esporas (miel, leche en polvo, tierra) que colonizan el intestino y producen la toxina ahí; el estreñimiento y el llanto débil evolucionan a parálisis flácida. La toxina preformada es el botulismo alimentario.","source":"Compendio ADN 6.1.a.f (vías de transmisión y cuadros clínicos) · Cuadernillo Núcleo 6 Agentes con ingreso digestivo 2026 (Actividad 2)"},
    {"id":"n7_1-d-02","nucleo":"7.1","difficulty":"dificil","topic":"Clostridium tetani","q":"Un hombre de 60 años, con una herida punzante en el pie hace una semana, presenta trismus, sonrisa sardónica, espasmos de la espalda y sudoración profusa. ¿Qué cuadro es?","a":["Tétanos generalizado","Botulismo de las heridas","Tétanos localizado","Encefalitis herpética"],"c":0,"exp":"El tétanos generalizado empieza con trismus y sonrisa sardónica, sigue con opistótonos y suma afectación autonómica (arritmias, oscilaciones de la presión, sudoración, deshidratación). En el localizado los espasmos quedan limitados al área de la herida.","source":"Compendio ADN 6.1.a.g (cuadros clínicos)"},
    {"id":"n7_1-d-03","nucleo":"7.1","difficulty":"dificil","topic":"Clostridium tetani","q":"¿De qué depende la duración del período de incubación del tétanos, que va de unos pocos días a semanas?","a":["De la distancia entre la herida primaria y el SNC","De la cantidad de esporas inoculadas en la herida","Del estado de inmunidad celular del paciente","Del tamaño y la profundidad del tejido necrótico"],"c":0,"exp":"El período de incubación se relaciona directamente con la distancia de la herida primaria al sistema nervioso central, porque la toxina tiene que llegar hasta ahí.","source":"Compendio ADN 6.1.a.g (período de incubación)"},
    {"id":"n7_1-d-04","nucleo":"7.1","difficulty":"dificil","topic":"Clostridium botulinum","q":"En el botulismo alimentario, ¿qué alimento y qué tipos de toxina están implicados con mayor frecuencia, y cuándo aparecen los síntomas?","a":["Conservas caseras, toxinas A y B, entre 1 y 3 días después del consumo","Pescado en conserva, toxina E, a las pocas horas del consumo","Miel contaminada, toxina C, luego de 4 días o más","Carne mal cocida, toxinas E y F, entre 7 y 10 días después"],"c":0,"exp":"El botulismo alimentario se asocia a conservas preparadas en casa (toxinas A y B) y los síntomas aparecen entre 1 y 3 días después de consumir el alimento. El pescado en conserva se vincula a la toxina tipo E.","source":"Compendio ADN 6.1.a.f (período de incubación y vías de transmisión)"},
    {"id":"n7_1-d-05","nucleo":"7.1","difficulty":"dificil","topic":"Clostridium botulinum","q":"Dos pacientes tienen parálisis por toxinas de clostridios: uno con debilidad bilateral descendente y flácida, otro con espasmos y rigidez. ¿Qué distingue a los agentes?","a":["C. botulinum da parálisis flácida descendente y C. tetani, parálisis espástica","C. botulinum da parálisis espástica y C. tetani, parálisis flácida ascendente","Ambos dan parálisis flácida, pero la de C. tetani empieza por los pares craneales","Ambos dan parálisis espástica, y se diferencian solo por la vía de entrada"],"c":0,"exp":"El botulismo cursa con visión borrosa, xerostomía y estreñimiento y evoluciona a debilidad bilateral descendente con parálisis flácida por bloqueo de la acetilcolina; el tétanos da parálisis espástica porque se pierde la inhibición por glicina y GABA.","source":"Compendio ADN 6.1.a.f y 6.1.a.g (cuadros clínicos) · Cuadernillo Núcleo 6 Agentes con ingreso digestivo 2026 (Actividad 2.e)"},
    {"id":"n7_1-d-06","nucleo":"7.1","difficulty":"dificil","topic":"Streptococcus agalactiae","q":"Una gestante portadora de EGB no recibe profilaxis intraparto y el recién nacido presenta dificultad respiratoria a las 34 horas de vida. ¿Qué corresponde esperar?","a":["Enfermedad de comienzo precoz, con bacteriemia, neumonía o meningitis","Enfermedad de comienzo tardío por serotipo III adquirido de fuentes exógenas","Una infección transplacentaria con malformaciones congénitas","Una colonización asintomática sin riesgo de enfermedad invasiva"],"c":0,"exp":"La enfermedad precoz se presenta en los primeros 7 días -en general dentro de las 24-48 horas- con bacteriemia, neumonía o meningitis, y se asocia a los serotipos Ia, III y V. La meningitis puede no ser evidente al inicio y exige analizar el LCR.","source":"Compendio ADN 6.1.a.d (cuadros clínicos) · Cuadernillo Núcleo 9 Transmisión vertical 2026 (Actividad 3.a)"},
    {"id":"n7_1-d-07","nucleo":"7.1","difficulty":"dificil","topic":"Neisseria meningitidis","q":"¿Qué grupo tiene un riesgo marcadamente mayor de enfermedad meningocócica invasiva por un defecto inmunitario puntual?","a":["Los pacientes con deficiencias de C5 a C8 del complemento","Los pacientes con neutropenia prolongada","Los pacientes con déficit aislado de IgA secretoria","Los pacientes esplenectomizados por trauma"],"c":0,"exp":"La incidencia más alta se da en menores de 5 años, personas institucionalizadas y pacientes con defectos de los últimos factores del complemento: los déficits de C5-C8 implican un riesgo significativamente mayor.","source":"Compendio ADN 6.1.a.e (epidemiología)"},
    {"id":"n7_1-d-08","nucleo":"7.1","difficulty":"dificil","topic":"Prevención","q":"¿Por qué la vacuna antimeningocócica tetravalente no cubre el serogrupo B?","a":["Porque su polisacárido capsular es un inmunógeno débil y no induce anticuerpos protectores","Porque el serogrupo B no produce enfermedad invasiva en humanos","Porque su cápsula cambia de antígeno con cada brote epidémico","Porque el polisacárido B no puede conjugarse con proteínas transportadoras"],"c":0,"exp":"El polisacárido del grupo B es un inmunógeno débil y no induce respuesta de anticuerpos protectora; la inmunidad contra ese serogrupo depende de la exposición natural a antígenos con reactividad cruzada. Las tetravalentes cubren A, C, Y y W135.","source":"Compendio ADN 6.1.a.e (vacunación)"},
    {"id":"n7_1-d-09","nucleo":"7.1","difficulty":"dificil","topic":"Enterovirus","q":"Según la cátedra, ¿qué define a un caso sospechoso de parálisis aguda fláccida (PAF)?","a":["Parálisis aguda y fláccida en un menor de 15 años, salvo traumatismo grave","Toda parálisis fláccida en un menor de 5 años con aislamiento de poliovirus en materia fecal","Toda parálisis fláccida que aparezca entre 4 y 40 días después de recibir una vacuna","Parálisis asimétrica con arreflexia confirmada por PCR en LCR"],"c":0,"exp":"Caso sospechoso: parálisis aguda y fláccida en un menor de 15 años por cualquier motivo que no sea un traumatismo grave. El caso confirmado exige aislar poliovirus salvaje en materia fecal.","source":"Compendio ADN 6.1.b.a (definiciones de caso de PAF, cátedra)"},
    {"id":"n7_1-d-10","nucleo":"7.1","difficulty":"dificil","topic":"Virus de la parotiditis","q":"En una meningitis por virus de la parotiditis, ¿cuál es el método diagnóstico de elección y en qué ventana se puede aislar el virus del LCR?","a":["RT-PCR en LCR, con aislamiento posible hasta los 8-9 días","Fijación de complemento en suero, útil desde el día 14","Aislamiento en cultivo de saliva, posible hasta 2 semanas","Detección de IgG en LCR, a partir de los 30 días"],"c":0,"exp":"La RT-PCR en LCR es el método de elección en la meningitis por parotiditis. Del LCR el virus se aísla dentro de los 8-9 días del inicio de los síntomas y de orina hasta 2 semanas.","source":"Compendio ADN 6.1.b.c.b (parotiditis, método diagnóstico)"},
    {"id":"n7_1-d-11","nucleo":"7.1","difficulty":"dificil","topic":"Virus herpes simplex","q":"Ante la sospecha de encefalitis herpética, ¿qué técnica conviene usar sobre el LCR y con qué rendimiento?","a":["PCR, con sensibilidad de 98-100% y especificidad del 94%","Inmunofluorescencia directa con monoclonales anti-glicoproteína G","Aislamiento en fibroblastos humanos, que informa en 2-7 días","Serología para distinguir HSV-1 de HSV-2"],"c":0,"exp":"La PCR es la técnica de elección en encefalitis o meningitis herpética, con sensibilidad de 98-100% y especificidad del 94% en LCR. La serología no sirve para infecciones agudas y la tinción de Tzanck tiene baja sensibilidad (40-50%).","source":"Compendio ADN 6.1.b.c.c (HSV, método diagnóstico)"},
    {"id":"n7_1-d-12","nucleo":"7.1","difficulty":"dificil","topic":"Infecciones del SNC","q":"¿Qué distingue el síndrome de una meningitis aséptica del de una meningitis bacteriana aguda?","a":["En la aséptica suele haber solo síndrome meníngeo","En la aséptica predomina la focalización neurológica","En la bacteriana no hay rigidez de nuca ni fiebre","En la bacteriana el compromiso se limita al parénquima encefálico"],"c":0,"exp":"En la meningitis bacteriana aguda predomina el síndrome meníngeo, que puede acompañarse de encefalopatía; en la aséptica suele observarse únicamente el síndrome meníngeo. La focalización es propia de las lesiones focales como los abscesos.","source":"Compendio ADN 6.1 (síndromes neurológicos)"},
    {"id":"n7_1-d-13","nucleo":"7.1","difficulty":"dificil","topic":"Diagnóstico de laboratorio","q":"¿Qué pruebas bioquímicas permiten diferenciar a Neisseria meningitidis de otras especies del género?","a":["Produce ácido por oxidación de glucosa y maltosa","Es catalasa negativa y fermenta carbohidratos con producción de ácido láctico","Es oxidasa negativa y ureasa positiva","Oxida solo la glucosa y no la maltosa"],"c":0,"exp":"N. meningitidis es oxidasa y catalasa positiva y produce ácido por oxidación de glucosa y maltosa, lo que la distingue de otras Neisserias. Crece a 35-37 °C en atmósfera húmeda con 5% de CO2 y medios enriquecidos como agar chocolate.","source":"Compendio ADN 6.1.a.e (características y estructura)"},
    {"id":"n7_1-d-14","nucleo":"7.1","difficulty":"dificil","topic":"Anatomía del SNC y LCR","q":"¿Por qué la barrera hematoencefálica representa un desafío en el tratamiento de la meningitis?","a":["Porque su permeabilidad selectiva obliga a elegir fármacos capaces de atravesarla","Porque se vuelve impermeable a toda molécula durante la inflamación","Porque impide que el LCR distribuya los fármacos por el espacio subaracnoideo","Porque los plexos coroides eliminan los antibióticos antes de que actúen"],"c":0,"exp":"La barrera, formada por endotelio con uniones estrechas, membrana basal y astrocitos, solo deja pasar agua y moléculas pequeñas: hay que elegir fármacos capaces de atravesarla para alcanzar concentraciones efectivas en el SNC.","source":"Compendio ADN 6.1 (barrera hematoencefálica y funciones del LCR)"},
    {"id":"n7_1-d-15","nucleo":"7.1","difficulty":"dificil","topic":"Infecciones del SNC","q":"Un paciente desarrolla un absceso cerebral luego de una sinusitis prolongada. ¿Qué mecanismo de acceso al SNC explica mejor el cuadro?","a":["Contigüidad desde un sitio vecino","Vía hematógena a partir de una bacteriemia","Inóculo directo por un procedimiento quirúrgico","Acceso por los nervios periféricos"],"c":0,"exp":"Un agente puede llegar al SNC por vía hematógena, por contigüidad desde sitios vecinos como los senos paranasales o el oído medio, por inóculo directo (traumatismos, cirugía, derivaciones) o por los nervios periféricos.","source":"Compendio ADN 6.1 (vías de acceso al SNC)"},
    {"id":"n8-f-01","nucleo":"8","difficulty":"facil","topic":"VIH","q":"¿A qué familia pertenece el virus de la inmunodeficiencia humana (VIH)?","a":["Retroviridae","Herpesviridae","Hepadnaviridae","Flaviviridae"],"c":0,"exp":"El VIH es un retrovirus (Retroviridae): genoma de ARN monocatenario que se retrotranscribe a ADN y se integra como provirus.","source":"Cuadernillo Núcleo 8 2026 (tabla de agentes) · Compendio ADN (8.a)"},
    {"id":"n8-f-02","nucleo":"8","difficulty":"facil","topic":"VIH","q":"¿Cuál es el receptor principal que usa la gp120 del VIH para unirse a la célula?","a":["CD4","CD8","CD21","CD81"],"c":0,"exp":"La gp120 se une a CD4 y a un correceptor de quimiocinas (CCR5 o CXCR4); la gp41 media la fusión de membranas.","source":"Compendio ADN (8.a, replicación)"},
    {"id":"n8-f-03","nucleo":"8","difficulty":"facil","topic":"Prevención","q":"¿Contra qué dos ITS virales hay vacunas en el Calendario Nacional de Vacunación argentino?","a":["Hepatitis B y VPH","VIH y hepatitis C","VHS-2 y hepatitis B","VPH y VHS-2"],"c":0,"exp":"El calendario incluye la vacuna contra la hepatitis B para toda la población y contra el VPH a los 11 años.","source":"Cuadernillo Núcleo 8 2026 (Introducción)"},
    {"id":"n8-f-04","nucleo":"8","difficulty":"facil","topic":"Prevención","q":"¿Cuál es la medida de prevención que reduce el riesgo de la mayoría de las ITS durante las relaciones sexuales?","a":["El uso consistente de preservativo","La higiene genital posterior","Los antibióticos preventivos","La vacuna antitetánica"],"c":0,"exp":"El preservativo (de látex, poliuretano o nitrilo) usado en forma consistente cubre mucosas y secreciones y reduce mucho el riesgo.","source":"Cuadernillo Núcleo 8 2026 · Compendio ADN (8.g)"},
    {"id":"n8-f-05","nucleo":"8","difficulty":"facil","topic":"Treponema pallidum","q":"¿Qué enfermedad causa Treponema pallidum subsp. pallidum?","a":["Sífilis","Gonorrea","Linfogranuloma venéreo","Chancroide"],"c":0,"exp":"T. pallidum subsp. pallidum es el agente de la sífilis venérea, que evoluciona en fases primaria, secundaria y terciaria.","source":"Compendio ADN (8.e) · Cuadernillo Núcleo 8 2026"},
    {"id":"n8-f-06","nucleo":"8","difficulty":"facil","topic":"Neisseria gonorrhoeae","q":"¿Cómo se ve Neisseria gonorrhoeae en una tinción de Gram?","a":["Diplococos gramnegativos","Cocos grampositivos en cadena","Bacilos gramnegativos curvos","Espiroquetas finas"],"c":0,"exp":"Son diplococos gramnegativos con lados adyacentes aplanados, en «grano de café».","source":"Compendio ADN (8.g)"},
    {"id":"n8-f-07","nucleo":"8","difficulty":"facil","topic":"Virus del papiloma humano","q":"¿Qué lesión benigna anogenital producen los tipos 6 y 11 del VPH?","a":["Condilomas acuminados","Chancro duro","Vesículas agrupadas","Bubón inguinal"],"c":0,"exp":"Los VPH 6 y 11 causan condilomas acuminados: verrugas anogenitales, proliferaciones benignas del epitelio escamoso.","source":"Cuadernillo Núcleo 8 2026 (galería de lesiones) · Compendio ADN (8.g)"},
    {"id":"n8-f-08","nucleo":"8","difficulty":"facil","topic":"Trichomonas vaginalis","q":"¿Qué tipo de agente es Trichomonas vaginalis?","a":["Un protozoo flagelado","Un hongo levaduriforme","Una bacteria sin pared","Un virus envuelto"],"c":0,"exp":"T. vaginalis es un protozoo flagelado de transmisión sexual; en la mujer produce flujo y en el hombre suele ser asintomático.","source":"Cuadernillo Núcleo 8 2026 (TP 19) · Compendio ADN (8.h)"},
    {"id":"n8-f-09","nucleo":"8","difficulty":"facil","topic":"Epidemiología","q":"¿Por qué el término «enfermedad de transmisión sexual» se reemplazó por «infección de transmisión sexual»?","a":["Porque muchas cursan sin síntomas","Porque ya no se transmiten por vía sexual","Porque todas tienen cura","Porque solo afectan a los genitales"],"c":0,"exp":"Gran parte de las ITS son asintomáticas: la persona puede transmitirlas sin saber que está infectada.","source":"Compendio ADN (Núcleo 8, introducción)"},
    {"id":"n8-f-10","nucleo":"8","difficulty":"facil","topic":"Epidemiología","q":"¿Cuál de estas ITS se puede curar con tratamiento?","a":["Sífilis","Infección por VIH","Infección por VHS-2","Infección por VPH"],"c":0,"exp":"La sífilis, la gonorrea, la clamidiasis y la tricomoniasis se curan con antimicrobianos; la infección por VIH, VHS o VPH no tiene tratamiento curativo y la hepatitis B crónica se controla, pero no se cura.","source":"Cuadernillo Núcleo 8 2026 (Introducción)"},
    {"id":"n8-n-01","nucleo":"8","difficulty":"normal","topic":"VIH","q":"¿Qué función cumple la gp41 en la envoltura del VIH?","a":["Media la fusión de las membranas","Une el virus al receptor CD4","Retrotranscribe el genoma","Integra el ADN proviral"],"c":0,"exp":"La gp120 se une a CD4 y al correceptor; después la gp41 favorece la fusión de la envoltura con la membrana celular.","source":"Compendio ADN (8.a)"},
    {"id":"n8-n-02","nucleo":"8","difficulty":"normal","topic":"VIH","q":"¿Qué correceptor usan los virus M-trópicos que predominan al inicio de la infección por VIH?","a":["CCR5","CXCR4","CD21","DC-SIGN"],"c":0,"exp":"Las cepas M-trópicas iniciales usan CD4 y CCR5; las T-trópicas, más tardías, usan CXCR4.","source":"Compendio ADN (8.a, replicación)"},
    {"id":"n8-n-03","nucleo":"8","difficulty":"normal","topic":"VIH","q":"¿Qué enzima del VIH inserta el ADN viral en el cromosoma de la célula y forma el provirus?","a":["Integrasa","Retrotranscriptasa","Proteasa","ARN polimerasa celular"],"c":0,"exp":"La integrasa inserta el ADNc en el genoma del huésped; la proteasa actúa después, en la maduración tras la gemación.","source":"Compendio ADN (8.a)"},
    {"id":"n8-n-04","nucleo":"8","difficulty":"normal","topic":"VIH","q":"¿Por qué el VIH acumula tantas variantes durante la infección?","a":["Su retrotranscriptasa comete muchos errores","Tiene un genoma segmentado","Su ADN se recombina con el celular","Cambia de familia viral"],"c":0,"exp":"La retrotranscriptasa del VIH tiene una tasa de error alta (cerca de 1 cada 2.000 bases), lo que genera variación antigénica de la gp120.","source":"Compendio ADN (8.a)"},
    {"id":"n8-n-05","nucleo":"8","difficulty":"normal","topic":"VIH","q":"¿Qué tipo y grupo de VIH es el más frecuente en Argentina?","a":["VIH-1, grupo M","VIH-2, grupo A","VIH-1, grupo O","VIH-2, grupo M"],"c":0,"exp":"El VIH-1 causa la pandemia y en Argentina predomina el grupo M; el VIH-2, menos virulento, se asocia a África occidental.","source":"Compendio ADN (8.a, tipos y subtipos)"},
    {"id":"n8-n-06","nucleo":"8","difficulty":"normal","topic":"VIH","q":"¿Qué tejido linfoide se agota temprano de linfocitos T CD4 con CCR5 después de la transmisión sexual del VIH?","a":["El tejido linfoide asociado al intestino","La médula ósea","El timo","Las amígdalas palatinas"],"c":0,"exp":"Poco después de la transmisión, el VIH infecta y agota los linfocitos CD4 con CCR5 del GALT.","source":"Compendio ADN (8.a) · Cuadernillo Núcleo 8 2026 (Actividad 1)"},
    {"id":"n8-n-07","nucleo":"8","difficulty":"normal","topic":"VIH","q":"¿Qué recuento de linfocitos T CD4 define el estadio SIDA?","a":["Menos de 200/µl","Menos de 500/µl","Menos de 1.000/µl","Menos de 50/µl"],"c":0,"exp":"El SIDA aparece con CD4 por debajo de 200/µl, con infecciones oportunistas, neoplasias, síndrome caquectizante o demencia.","source":"Compendio ADN (8.a) · Cuadernillo Núcleo 8 2026 (evolución y CD4)"},
    {"id":"n8-n-08","nucleo":"8","difficulty":"normal","topic":"VIH","q":"Confirmado el diagnóstico de VIH, ¿qué dos parámetros se miden para seguir la infección y el tratamiento antirretroviral?","a":["Recuento de CD4 y carga viral","Western blot y antígeno p24","Anti-VIH y VDRL","Hemograma y hepatograma"],"c":0,"exp":"El recuento de CD4 refleja la inmunosupresión y la carga viral (ARN por PCR), la replicación y la respuesta al tratamiento.","source":"Cuadernillo Núcleo 8 2026 (Actividad 1 i) · Compendio ADN (8.a)"},
    {"id":"n8-n-09","nucleo":"8","difficulty":"normal","topic":"VIH","q":"¿Qué detectan los ensayos de cuarta generación para VIH que se usan en el laboratorio clínico?","a":["Antígeno p24 y anticuerpos anti-VIH","Solo el ARN viral","Solo anticuerpos IgG","El ADN proviral integrado"],"c":0,"exp":"Los inmunoensayos de 4.ª generación detectan a la vez el antígeno p24 y los anticuerpos, lo que acorta el período ventana.","source":"Cuadernillo Núcleo 8 2026 (Anexo, VIH)"},
    {"id":"n8-n-10","nucleo":"8","difficulty":"normal","topic":"Virus del papiloma humano","q":"¿Cuál es la característica estructural del virus del papiloma humano?","a":["ADN circular bicatenario sin envoltura","ARN monocatenario con envoltura","ADN parcialmente bicatenario envuelto","ARN segmentado sin envoltura"],"c":0,"exp":"El VPH (Papillomaviridae) es pequeño, sin envoltura, de cápside icosaédrica y genoma de ADN circular bicatenario.","source":"Compendio ADN (8.b) · Cuadernillo Núcleo 8 2026"},
    {"id":"n8-n-11","nucleo":"8","difficulty":"normal","topic":"Virus del papiloma humano","q":"¿Qué proteínas del VPH de alto riesgo actúan como oncogenes?","a":["E5, E6 y E7","L1 y L2","E1 y E2","gp120 y gp41"],"c":0,"exp":"En los tipos de alto riesgo (16 y 18), E5, E6 y E7 estimulan la proliferación y la transformación; L1 y L2 son estructurales.","source":"Compendio ADN (8.b, factores de virulencia)"},
    {"id":"n8-n-12","nucleo":"8","difficulty":"normal","topic":"Virus del papiloma humano","q":"¿Qué célula característica del Papanicolaou orienta a infección por VPH?","a":["El coilocito","La célula guía","La célula de Tzanck","La célula de Reed-Sternberg"],"c":0,"exp":"El coilocito es la célula epitelial alterada típica del VPH; la lesión coilocitótica puede evolucionar a displasia.","source":"Compendio ADN (8.b) · Cuadernillo Núcleo 8 2026 (TP 19)"},
    {"id":"n8-n-13","nucleo":"8","difficulty":"normal","topic":"Virus del herpes simple tipo 2","q":"¿Dónde establece latencia el virus del herpes simple tipo 2?","a":["En neuronas sensitivas","En linfocitos B","En hepatocitos","En queratinocitos basales"],"c":0,"exp":"El VHS-2 se replica en células mucoepiteliales y queda latente en las neuronas que las inervan; la reactivación causa recurrencias.","source":"Compendio ADN (8.c)"},
    {"id":"n8-n-14","nucleo":"8","difficulty":"normal","topic":"Virus del herpes simple tipo 2","q":"¿Qué lesión genital es típica de la infección por VHS-2?","a":["Vesículas dolorosas sobre base eritematosa","Una úlcera única e indolora de fondo duro","Verrugas indoloras en los pliegues","Una úlcera mínima con bubón inguinal"],"c":0,"exp":"Las vesículas sobre base eritematosa progresan a pústulas, úlceras y costras, con dolor, ardor y recurrencias.","source":"Cuadernillo Núcleo 8 2026 (galería de lesiones) · Compendio ADN (8.c)"},
    {"id":"n8-n-15","nucleo":"8","difficulty":"normal","topic":"Treponema pallidum","q":"¿Por qué Treponema pallidum no se ve con la tinción de Gram?","a":["Es demasiado fino","No tiene pared celular","Es ácido-alcohol resistente","Vive solo dentro de células"],"c":0,"exp":"Es una espiroqueta demasiado fina para el Gram o el Giemsa: se observa con microscopía de campo oscuro o inmunofluorescencia.","source":"Compendio ADN (8.e)"},
    {"id":"n8-n-16","nucleo":"8","difficulty":"normal","topic":"Treponema pallidum","q":"¿Qué detectan las pruebas no treponémicas como la VDRL?","a":["Anticuerpos reagínicos contra lípidos","Antígenos de la pared del treponema","Anticuerpos específicos anti-T. pallidum","ADN del treponema"],"c":0,"exp":"La VDRL detecta reaginas (IgG e IgM) contra antígenos lipoidales liberados por el daño celular; por eso puede dar falsos positivos.","source":"Cuadernillo Núcleo 8 2026 (Anexo) · Compendio ADN (8.e)"},
    {"id":"n8-n-17","nucleo":"8","difficulty":"normal","topic":"Chlamydia trachomatis","q":"¿Cuál es la forma infecciosa de Chlamydia trachomatis?","a":["El cuerpo elemental","El cuerpo reticulado","La inclusión con glucógeno","La espora"],"c":0,"exp":"El cuerpo elemental es infeccioso y metabólicamente inactivo; dentro de la célula se convierte en cuerpo reticulado, que se replica.","source":"Compendio ADN (8.f) · Cuadernillo Núcleo 8 2026 (Actividad 3 b)"},
    {"id":"n8-n-18","nucleo":"8","difficulty":"normal","topic":"Chlamydia trachomatis","q":"¿Cuál es el método de elección para diagnosticar una infección genital por Chlamydia trachomatis?","a":["Amplificación de ácidos nucleicos","Cultivo en agar chocolate","Serología con anticuerpos IgG","Tinción de Gram del flujo"],"c":0,"exp":"Las pruebas moleculares (NAAT/PCR) son sensibles y específicas y son las de elección (SADI 2025); la serología no distingue infección actual de previa.","source":"Cuadernillo Núcleo 8 2026 (TP 19) · Compendio ADN (8.f)"},
    {"id":"n8-n-19","nucleo":"8","difficulty":"normal","topic":"Neisseria gonorrhoeae","q":"¿Qué factor de virulencia de Neisseria gonorrhoeae permite la adhesión inicial y resiste a los neutrófilos?","a":["Los pili","La cápsula de ácido siálico","La toxina tipo AB","El flagelo polar"],"c":0,"exp":"Los pili median la adhesión a células mucosas no ciliadas y resisten a los neutrófilos; Opa y PorB completan la adhesión.","source":"Compendio ADN (8.g)"},
    {"id":"n8-n-20","nucleo":"8","difficulty":"normal","topic":"Trichomonas vaginalis","q":"¿Qué examen rápido permite ver Trichomonas vaginalis en el flujo vaginal?","a":["El examen en fresco","La tinción de Ziehl-Neelsen","El campo oscuro","La tinta china"],"c":0,"exp":"En el examen en fresco de fondo de saco posterior se ve su motilidad; también se observa en el Papanicolaou o con Giemsa.","source":"Cuadernillo Núcleo 8 2026 (TP 19) · Compendio ADN (8.h)"},
    {"id":"n8-d-01","nucleo":"8","difficulty":"dificil","topic":"VIH","q":"Una persona tuvo una exposición sexual de alto riesgo hace pocos días. ¿Qué estudio es más útil por el período ventana?","a":["Antígeno o ARN del VIH","Western blot","VDRL","Cultivo viral"],"c":0,"exp":"Por el período ventana, los anticuerpos pueden faltar; la detección de antígeno o ARN viral identifica antes la infección. En los primeros ~10 días incluso el ARN puede ser indetectable, por eso se repite el estudio.","source":"Cuadernillo Núcleo 8 2026 (Actividad 2 f y Anexo VIH)"},
    {"id":"n8-d-02","nucleo":"8","difficulty":"dificil","topic":"VIH","q":"¿Por qué el diagnóstico de VIH en menores de 18 meses no se basa en anticuerpos?","a":["Pueden tener anticuerpos maternos","Todavía no tienen linfocitos CD4","El virus no se replica en lactantes","La carga viral siempre es indetectable"],"c":0,"exp":"La IgG materna atraviesa la placenta y puede persistir hasta los 18 meses, así que el diagnóstico se hace con métodos directos (PCR de ADN proviral o carga viral).","source":"Cuadernillo Núcleo 8 2026 (Actividad 1 h)"},
    {"id":"n8-d-03","nucleo":"8","difficulty":"dificil","topic":"VIH","q":"¿Qué perfil de laboratorio corresponde a la fase de latencia clínica del VIH?","a":["Carga viral baja y CD4 en descenso","Carga viral alta y CD4 normales","Carga viral alta y CD4 bajo 200/µl","Carga viral nula y CD4 estables"],"c":0,"exp":"En la latencia la replicación es baja (sobre todo en ganglios) y los CD4 bajan gradualmente; en el SIDA la carga sube y los CD4 caen bajo 200/µl.","source":"Compendio ADN (8.a, evolución)"},
    {"id":"n8-d-04","nucleo":"8","difficulty":"dificil","topic":"Respuesta inmune","q":"¿Por qué los anticuerpos neutralizantes contra la gp120 no alcanzan para controlar el VIH?","a":["La gp120 cambia por mutación","No se generan anticuerpos contra la gp120","El virus no circula en la sangre","Los anticuerpos destruyen los CD4"],"c":0,"exp":"El VIH escapa por variación antigénica de la gp120 y por la latencia en reservorios; el virus recubierto de anticuerpos sigue siendo infeccioso.","source":"Compendio ADN (8.a, rol del sistema inmune)"},
    {"id":"n8-d-05","nucleo":"8","difficulty":"dificil","topic":"Diagnóstico de laboratorio","q":"Mujer de 32 años con exantema palmoplantar no pruriginoso y una lesión cicatrizal en un labio menor. ¿Qué agente y estudio corresponden?","a":["T. pallidum; prueba no treponémica y treponémica","VHS-2; PCR de la lesión","C. trachomatis; NAAT de endocérvix","VPH; Papanicolaou"],"c":0,"exp":"El exantema palmoplantar tras un chancro sugiere sífilis secundaria; se estudia con serología no treponémica y treponémica.","source":"Cuadernillo Núcleo 8 2026 (TP 19, caso 3)"},
    {"id":"n8-d-06","nucleo":"8","difficulty":"dificil","topic":"Treponema pallidum","q":"¿Con qué prueba se sigue la respuesta al tratamiento de la sífilis?","a":["Con títulos de la prueba no treponémica","Con la prueba treponémica","Con campo oscuro mensual","Con PCR en sangre"],"c":0,"exp":"Las treponémicas quedan positivas toda la vida; la respuesta se evalúa con la caída de la no treponémica (cuatro veces o dos diluciones).","source":"Cuadernillo Núcleo 8 2026 (Anexo, sífilis)"},
    {"id":"n8-d-07","nucleo":"8","difficulty":"dificil","topic":"Treponema pallidum","q":"Después de tratar una sífilis, la VDRL sube de 1/8 a 1/32. ¿Cómo se interpreta?","a":["Falla del tratamiento o reinfección","Respuesta adecuada al tratamiento","Cicatriz serológica sin importancia","Falso positivo por la vacuna"],"c":0,"exp":"Cuadruplicar los títulos (subir dos diluciones) es significativo: falla del tratamiento o reinfección, según el antecedente.","source":"Cuadernillo Núcleo 8 2026 (Anexo, sífilis)"},
    {"id":"n8-d-08","nucleo":"8","difficulty":"dificil","topic":"Chlamydia trachomatis","q":"¿Qué lesión describe un linfogranuloma venéreo por Chlamydia trachomatis?","a":["Úlcera mínima y bubón inguinal que supura","Úlcera única, dura e indolora","Úlceras indoloras confluentes sin adenopatías","Úlceras múltiples dolorosas de base blanda"],"c":0,"exp":"El LGV empieza con una úlcera mínima y sigue con un bubón fluctuante y doloroso que puede supurar y causar linfedema.","source":"Cuadernillo Núcleo 8 2026 (galería de lesiones)"},
    {"id":"n8-d-09","nucleo":"8","difficulty":"dificil","topic":"Klebsiella granulomatis","q":"Un paciente tiene úlceras genitales indoloras que confluyen y deforman los genitales, sin adenopatías. ¿Qué cuadro sugiere?","a":["Granuloma inguinal","Chancroide","Linfogranuloma venéreo","Herpes genital recurrente"],"c":0,"exp":"El granuloma inguinal (Klebsiella granulomatis) da úlceras no dolorosas que confluyen y deforman, sin adenopatías.","source":"Cuadernillo Núcleo 8 2026 (galería de lesiones)"},
    {"id":"n8-d-10","nucleo":"8","difficulty":"dificil","topic":"Haemophilus ducreyi","q":"¿Qué lesión corresponde al chancroide por Haemophilus ducreyi?","a":["Úlcera blanda, purulenta y muy dolorosa","Úlcera dura, única e indolora","Placas elevadas en pliegues macerados","Vesículas agrupadas que ulceran"],"c":0,"exp":"El chancro blando es una úlcera de base no indurada, purulenta, rodeada de úlceras dolorosas, con adenopatía que fluctúa y se rompe.","source":"Cuadernillo Núcleo 8 2026 (galería de lesiones)"},
    {"id":"n8-d-11","nucleo":"8","difficulty":"dificil","topic":"Neisseria gonorrhoeae","q":"Varón de 25 años con disuria y secreción uretral purulenta. ¿Qué hallazgo del Gram de la secreción orienta a gonorrea?","a":["Diplococos gramnegativos intracelulares en polimorfonucleares","Cocos grampositivos en racimos dentro de neutrófilos","Bacilos gramnegativos extracelulares abundantes","Levaduras con seudohifas sin reacción inflamatoria"],"c":0,"exp":"En el hombre sintomático, los diplococos gramnegativos intracelulares en la secreción uretral son confiables para gonorrea; en mujeres y asintomáticos se usa NAAT o cultivo.","source":"Compendio ADN (8.g) · Cuadernillo Núcleo 8 2026 (TP 19, caso 1)"},
    {"id":"n8-d-12","nucleo":"8","difficulty":"dificil","topic":"Mycoplasma genitalium","q":"Un hombre tiene uretritis persistente con estudios negativos para gonococo y Chlamydia. ¿Qué agente conviene buscar?","a":["Mycoplasma genitalium","Treponema pallidum","Virus del papiloma humano","Phthirus pubis"],"c":0,"exp":"M. genitalium (grupo Mollicutes) causa uretritis no gonocócica; se busca con métodos moleculares.","source":"Cuadernillo Núcleo 8 2026 (TP 19, caso 6)"},
    {"id":"n8-d-13","nucleo":"8","difficulty":"dificil","topic":"Virus de la hepatitis B","q":"¿Qué marcador de hepatitis B indica inmunidad por vacunación o por infección pasada?","a":["Anti-HBs","HBsAg","Anti-HBc IgM","HBeAg"],"c":0,"exp":"El anti-HBs indica inmunidad; el HBsAg, infección actual; el anti-HBc IgM, infección aguda o reciente; el HBeAg, replicación.","source":"Cuadernillo Núcleo 8 2026 (Anexo, hepatitis B)"},
    {"id":"n8-d-14","nucleo":"8","difficulty":"dificil","topic":"Virus de la hepatitis C","q":"Un control de rutina da anti-VHC reactivo. ¿Qué estudio confirma si la infección está activa?","a":["ARN del VHC por PCR","Un segundo anti-VHC","Anti-VHC de tipo IgM","Hepatograma completo"],"c":0,"exp":"El anti-VHC no distingue infección activa de resuelta: ARN detectable confirma infección activa; no detectable sugiere resuelta o falso positivo.","source":"Cuadernillo Núcleo 8 2026 (Anexo, hepatitis C)"},
    {"id":"n8-d-15","nucleo":"8","difficulty":"dificil","topic":"Respuesta inmune","q":"¿Qué rasgo distingue la inmunidad de la mucosa uterina del resto de las mucosas?","a":["Predomina la IgG, no la IgA secretora","No tiene microbiota","Carece de linfocitos T CD8","Predomina la IgE"],"c":0,"exp":"En la mucosa uterina la principal inmunoglobulina es la IgG; además la vagina tiene abundantes Lactobacillus y el endometrio agregados linfoides.","source":"Cuadernillo Núcleo 8 2026 (TP 19, microbiota del tracto reproductor)"},
    {"id":"n9-f-01","nucleo":"9","difficulty":"facil","topic":"Perfil TORCHS","q":"En el perfil TORCHS, ¿qué infección representa la letra S agregada al final de la sigla?","a":["Sífilis","Sarampión","Streptococcus agalactiae","Shigelosis"],"c":0,"exp":"TORCH es la sigla de toxoplasmosis, otras, rubéola, citomegalovirus y herpes simple (el material suma VIH y Chagas); cuando se escribe TORCHS, la S adicional representa la sífilis.","source":"Cuadernillo Núcleo 9 Seminario 2026 (Introducción, perfil TORCHS) · Compendio ADN (9)"},
    {"id":"n9-f-02","nucleo":"9","difficulty":"facil","topic":"Vías de transmisión vertical","q":"La transmisión de un microorganismo de la madre al hijo mediante la lactancia materna se clasifica como transmisión:","a":["Posnatal","Perinatal","Congénita (intraútero)","Ascendente transcervical"],"c":0,"exp":"La transmisión vertical puede ser intraútero (congénita), en el momento del parto o alrededor de él (perinatal) o posterior (posnatal), como la que ocurre por lactancia materna.","source":"Cuadernillo Núcleo 9 Seminario 2026 (Introducción) · Compendio ADN (9)"},
    {"id":"n9-f-03","nucleo":"9","difficulty":"facil","topic":"Virus de la rubéola","q":"¿Con qué vacuna y esquema del Calendario Nacional se previene la rubéola congénita?","a":["Triple viral a los 12 meses y a los 5 años","Gammaglobulina específica a la gestante expuesta","Doble viral durante el segundo trimestre","Lavado de manos tras contacto con secreciones"],"c":0,"exp":"La vacuna antirrubeólica (virus vivo atenuado) va en la triple viral: 1.ª dosis a los 12 meses y 2.ª a los 5 años. El objetivo es que la mujer llegue al embarazo con anticuerpos.","source":"Compendio ADN (9.a, pregunta c) · Cuadernillo Núcleo 9 Seminario 2026 (Actividad 5d, tabla de prevención)"},
    {"id":"n9-f-04","nucleo":"9","difficulty":"facil","topic":"Trypanosoma cruzi","q":"Un recién nacido es hijo de una madre con serología reactiva para Chagas. ¿Qué se indica respecto de la lactancia materna?","a":["No está contraindicada","Se suspende hasta los 10 meses de vida","Solo se permite con leche extraída y hervida","Está contraindicada, igual que en el VIH"],"c":0,"exp":"En hijos de madres con serología reactiva para Chagas la lactancia no está contraindicada (a diferencia del VIH, donde sí lo está).","source":"Compendio ADN (9.j) · Cuadernillo Núcleo 9 Seminario 2026 (Actividad 4c)"},
    {"id":"n9-f-05","nucleo":"9","difficulty":"facil","topic":"Virus herpes simple 1 y 2","q":"Una gestante con herpes genital tiene lesiones activas al comenzar el trabajo de parto. ¿Qué medida reduce el riesgo de herpes neonatal?","a":["Cesárea electiva","Vacunar al recién nacido al nacer","Gammaglobulina hiperinmune a la madre","Penicilina G intravenosa intraparto"],"c":0,"exp":"El VHS se adquiere sobre todo al pasar por el canal de parto con lesiones genitales activas; por eso se indica cesárea electiva si hay lesiones al momento del parto.","source":"Compendio ADN (9.f y tabla de agentes) · Cuadernillo Núcleo 9 Seminario 2026 (Actividad 5a y 5d)"},
    {"id":"n9-f-06","nucleo":"9","difficulty":"facil","topic":"Virus de la hepatitis B","q":"¿Qué se le indica al recién nacido de una madre HBsAg positiva para prevenir la hepatitis B?","a":["Vacuna y gammaglobulina en las primeras 12 h de vida","Solo la vacuna a los 2 meses, con el resto del calendario","Tenofovir oral al recién nacido durante 6 meses","Cesárea electiva y suspensión de la lactancia"],"c":0,"exp":"La prevención en el RN es la vacuna más la inmunización pasiva (gammaglobulina) en las primeras 12 horas de vida. La dosis neonatal está en el Calendario Nacional desde 2000.","source":"Compendio ADN (tabla de agentes, VHB) · Cuadernillo Núcleo 9 Seminario 2026 (Actividad 5d)"},
    {"id":"n9-f-07","nucleo":"9","difficulty":"facil","topic":"Virus de la inmunodeficiencia humana (VIH)","q":"En una gestante con VIH, ¿qué indica el material de la cátedra respecto de la lactancia materna?","a":["Está contraindicada","Se recomienda exclusiva hasta los 6 meses","Se permite si la madre no tiene síntomas","Solo se suspende si aparece mastitis"],"c":0,"exp":"La lactancia es una vía posnatal de transmisión del VIH. La prevención combina TARV efectiva en la gestante, profilaxis antirretroviral al RN y contraindicación de la lactancia.","source":"Compendio ADN (tabla de agentes, VIH) · Cuadernillo Núcleo 9 Seminario 2026 (Prevención; Actividad 5a)"},
    {"id":"n9-f-08","nucleo":"9","difficulty":"facil","topic":"Streptococcus agalactiae","q":"¿Cuál es la morfología de Streptococcus agalactiae (estreptococo del grupo B)?","a":["Coco grampositivo en cadenas, beta-hemolítico","Coco grampositivo en racimos, coagulasa positivo","Diplococo gramnegativo, oxidasa positivo","Bacilo grampositivo corto, beta-hemolítico"],"c":0,"exp":"EGB es un coco grampositivo que forma cadenas cortas en muestras clínicas y más largas en cultivo, con colonias mantecosas y una estrecha zona de beta-hemólisis; grupo B de Lancefield.","source":"Compendio ADN (9.g) · Cuadernillo Núcleo 9 Seminario 2026 (tabla Agentes vistos en este núcleo)"},
    {"id":"n9-f-09","nucleo":"9","difficulty":"facil","topic":"Toxoplasma gondii","q":"¿En qué hospedador completa Toxoplasma gondii su ciclo sexual?","a":["Gato y otros felinos","Roedores silvestres","Ser humano","Aves y ganado"],"c":0,"exp":"El gato doméstico y otros felinos son el reservorio: el ciclo sexual ocurre en sus células intestinales y eliminan ovoquistes por heces, que maduran en el ambiente. Otros animales son hospedadores intermediarios.","source":"Compendio ADN (9.i, cadena epidemiológica) · Cuadernillo Núcleo 9 Laboratorio 2026 (TP 20, Grupo 3)"},
    {"id":"n9-f-10","nucleo":"9","difficulty":"facil","topic":"Toxoplasma gondii","q":"¿Qué medida de prevención de la toxoplasmosis se le recomienda a una gestante?","a":["Evitar carne cruda o poco cocida y heces de gato","Vacunarse antes de buscar el embarazo","Usar repelente y mosquitero en zonas endémicas","Evitar el contacto con niños menores de 5 años"],"c":0,"exp":"Las vías principales son la ingesta de carne poco cocida y de ovoquistes de heces de gato; por eso se indica evitar consumir y manipular carne cruda y el contacto con heces de gato. No hay vacuna.","source":"Compendio ADN (9.i, prevención en embarazadas) · Cuadernillo Núcleo 9 Laboratorio 2026 (TP 20, Grupo 3)"},
    {"id":"n9-n-01","nucleo":"9","difficulty":"normal","topic":"Vías de transmisión vertical","q":"Cuando una infección materna llega al feto por vía ascendente (de la vagina al líquido amniótico por el cuello uterino), ¿qué consecuencias son más frecuentes?","a":["Corioamnionitis, funisitis y parto pretérmino","Villitis y deciduitis por viremia materna","Latencia del agente en ganglios neuronales fetales","Cataratas, sordera y cardiopatía congénita"],"c":0,"exp":"La vía ascendente causa con más frecuencia funisitis y corioamnionitis, con rotura prematura de membranas y parto pretérmino. Villitis y deciduitis son propias de la vía hematógena (sobre todo virus).","source":"Cuadernillo Núcleo 9 Seminario 2026 (Introducción) · Compendio ADN (9)"},
    {"id":"n9-n-02","nucleo":"9","difficulty":"normal","topic":"Prevención","q":"La iniciativa ETMI-plus de la OPS/OMS busca eliminar la transmisión maternoinfantil de:","a":["VIH, sífilis, hepatitis B y Chagas","VIH, rubéola, toxoplasmosis y CMV","Sífilis, EGB, herpes simple y varicela","Hepatitis B y C, CMV y toxoplasmosis"],"c":0,"exp":"ETMI-plus es la eliminación de la transmisión maternoinfantil de VIH, sífilis, hepatitis B y Chagas; organiza tamizaje prenatal, tratamiento oportuno y manejo neonatal.","source":"Cuadernillo Núcleo 9 Seminario 2026 (Prevención de infecciones de transmisión vertical) · Cuadernillo Núcleo 9 Laboratorio 2026 (TP 20, Ley 27.675)"},
    {"id":"n9-n-03","nucleo":"9","difficulty":"normal","topic":"Respuesta inmune","q":"¿Por qué el virus de la rubéola implica riesgo fetal solo ante una infección primaria materna?","a":["La inmunidad previa (infección o vacuna) impide en la práctica el pasaje al feto","El virus no atraviesa la placenta en ninguna etapa del embarazo","Solo se transmite al hijo por la lactancia materna","Hace latencia en ganglios y solo reactiva en inmunodeprimidas"],"c":0,"exp":"Si la madre no tiene anticuerpos, el virus se replica en la placenta y pasa a la sangre fetal; la inmunidad por exposición previa o vacunación lo impide. Tiene un único serotipo y la inmunidad es duradera.","source":"Compendio ADN (9.a, preguntas a y d) · Cuadernillo Núcleo 9 Seminario 2026 (Actividad 5a y 5b)"},
    {"id":"n9-n-04","nucleo":"9","difficulty":"normal","topic":"Virus de la rubéola","q":"Un RN cuya madre tuvo exantema maculopapular con adenopatías en el 1.er trimestre presenta cataratas, sordera neurosensorial y ductus persistente. ¿Agente más probable?","a":["Virus de la rubéola","Citomegalovirus","Virus varicela-zóster","Toxoplasma gondii"],"c":0,"exp":"Es el síndrome de rubéola congénita: cataratas, sordera neurosensorial y cardiopatía (ductus). El riesgo y la gravedad son máximos si la infección materna ocurre en el primer trimestre.","source":"Cuadernillo Núcleo 9 Seminario 2026 (Actividad 5a y 5c) · Compendio ADN (9.a)"},
    {"id":"n9-n-05","nucleo":"9","difficulty":"normal","topic":"Citomegalovirus (CMV)","q":"¿Qué explica que el CMV pueda transmitirse al feto aun sin infección primaria materna durante el embarazo?","a":["Latencia con reactivación, o reinfección por otra cepa, en el embarazo","Que tiene un único serotipo y no deja inmunidad duradera","Que se transmite solo por vía transplacentaria en el 1.er trimestre","Que la IgG materna favorece el pasaje placentario"],"c":0,"exp":"Como herpesvirus, el CMV queda latente (células mieloides, monocitos): puede reactivarse o la gestante puede reinfectarse con otra cepa, y el virus llega al feto, sobre todo por vía transplacentaria. En madres seropositivas suele ser menos grave.","source":"Compendio ADN (9.b, pregunta a) · Cuadernillo Núcleo 9 Seminario 2026 (Actividad 5a y 5b)"},
    {"id":"n9-n-06","nucleo":"9","difficulty":"normal","topic":"Citomegalovirus (CMV)","q":"Sobre la infección congénita por citomegalovirus, ¿cuál de estas afirmaciones es correcta?","a":["Es la causa viral más frecuente de anomalías congénitas","La mayoría de los RN infectados son sintomáticos al nacer","Solo se transmite si la madre cursa infección primaria","Se previene con una vacuna del Calendario Nacional"],"c":0,"exp":"El CMV es la causa vírica más frecuente de anomalías congénitas; el 85-90% de los RN infectados es asintomático al nacer y las secuelas habituales son pérdida auditiva y retraso mental. Se previene con lavado de manos.","source":"Compendio ADN (9.b y tabla de agentes) · Cuadernillo Núcleo 9 Seminario 2026 (Actividad 5c)"},
    {"id":"n9-n-07","nucleo":"9","difficulty":"normal","topic":"Virus de la inmunodeficiencia humana (VIH)","q":"Según el cuadernillo, ¿cuál es la vía principal de transmisión vertical del VIH?","a":["Perinatal y posnatal (lactancia)","Transplacentaria en el primer trimestre","Transplacentaria en cualquier momento del embarazo","Ascendente, con corioamnionitis temprana"],"c":0,"exp":"El VIH se transmite principalmente en el período perinatal y posnatal (lactancia); la vía transplacentaria es posible pero menos frecuente. El riesgo se reduce con tratamiento antirretroviral materno.","source":"Cuadernillo Núcleo 9 Seminario 2026 (Actividad 5a) · Compendio ADN (9.c)"},
    {"id":"n9-n-08","nucleo":"9","difficulty":"normal","topic":"Diagnóstico de laboratorio","q":"¿Cómo se diagnostica la infección por VIH en una gestante según el material de la cátedra?","a":["Prueba rápida o ELISA 4.ª gen. y confirmación por carga viral","PCR de ADN proviral como tamizaje inicial en el primer control","Recuento de linfocitos T CD4 como prueba diagnóstica única","Detección aislada de antígeno p24, sin prueba confirmatoria"],"c":0,"exp":"En la gestante se tamiza con prueba rápida o ELISA de 4.ª generación y se confirma con carga viral. La Ley 25.543 establece la oferta obligatoria del diagnóstico de VIH en el embarazo.","source":"Compendio ADN (tabla de agentes, VIH) · Cuadernillo Núcleo 9 Laboratorio 2026 (TP 20, Introducción y Grupo 5)"},
    {"id":"n9-n-09","nucleo":"9","difficulty":"normal","topic":"Respuesta inmune","q":"¿Por qué hasta el 90% de los lactantes infectados con VHB en forma perinatal evoluciona a portación crónica?","a":["Por la inmadurez de su respuesta inmune celular","Por el pasaje transplacentario de anti-HBs materno","Porque el virus no expresa HBsAg en el lactante","Porque el virus hace latencia en ganglios neuronales"],"c":0,"exp":"La respuesta celular inmadura reduce la capacidad de eliminar el virus: hay menos lesión y síntomas, pero alta cronificación, con riesgo de cirrosis o carcinoma hepatocelular (latencia de 9 a 35 años).","source":"Compendio ADN (9.e) · Cuadernillo Núcleo 9 Seminario 2026 (Actividad 5a)"},
    {"id":"n9-n-10","nucleo":"9","difficulty":"normal","topic":"Virus de la hepatitis B","q":"¿Qué rasgo del virus de la hepatitis B resulta llamativo para un virus de ADN?","a":["Se replica vía un intermediario de ARN (retrotranscriptasa)","Su genoma es ADN bicatenario lineal, el mayor de los herpesvirus","Carece de envoltura, lo que lo hace resistente a la desecación","Hace latencia en ganglios sensitivos y se reactiva"],"c":0,"exp":"El VHB (Hepadnaviridae) tiene ADN circular parcialmente bicatenario, pero codifica una retrotranscriptasa y se replica mediante un intermediario de ARN. Tiene envoltura con HBsAg y tropismo hepático estricto.","source":"Compendio ADN (9.e) · Cuadernillo Núcleo 9 Seminario 2026 (Actividad 5a)"},
    {"id":"n9-n-11","nucleo":"9","difficulty":"normal","topic":"Virus varicela-zóster","q":"Una gestante presenta varicela en los días cercanos al parto. ¿Cuál es el principal riesgo para el recién nacido?","a":["Varicela diseminada grave, con neumonía o encefalitis","Síndrome de varicela congénita con hipoplasia de miembros","Portación crónica asintomática del virus","Cataratas y sordera neurosensorial tardías"],"c":0,"exp":"La exposición periparto puede causar varicela neonatal grave, con diseminación a pulmón, cerebro e hígado por la inmadurez de la inmunidad celular. El síndrome de varicela congénita corresponde a la vía transplacentaria.","source":"Compendio ADN (9.d) · Cuadernillo Núcleo 9 Seminario 2026 (Actividad 5a y 5c)"},
    {"id":"n9-n-12","nucleo":"9","difficulty":"normal","topic":"Virus varicela-zóster","q":"Una gestante seronegativa para varicela tuvo contacto con un caso activo. ¿Qué se indica según el cuadernillo?","a":["IGVZ (gammaglobulina hiperinmune) lo antes posible, idealmente en 96 h","Vacuna antivaricela en forma inmediata a la gestante","Aciclovir solo al recién nacido, al nacer","Serología a las 4 semanas y conducta expectante"],"c":0,"exp":"En la gestante susceptible expuesta se indica gammaglobulina hiperinmune (IGVZ) dentro de las 96 horas y evitar contacto con casos activos. La vacunación de mujeres susceptibles se hace en el posparto. (El CDC la acepta hasta 10 días después del contacto.)","source":"Cuadernillo Núcleo 9 Seminario 2026 (Actividad 5d, tabla de prevención; Prevención primaria) · Compendio ADN (tabla de agentes)"},
    {"id":"n9-n-13","nucleo":"9","difficulty":"normal","topic":"Virus herpes simple 1 y 2","q":"¿Cuáles son las formas clínicas del herpes simple neonatal descriptas en el cuadernillo?","a":["Piel-ojos-boca (SEM), SNC y diseminada","Cataratas, sordera y cardiopatía congénita","Rinitis, exantema y lesiones óseas","Hepatitis aguda, ictericia y coluria"],"c":0,"exp":"El herpes neonatal suele ser sintomático: forma SEM (piel, ojos, boca), forma con compromiso del SNC (letargo, convulsiones) o forma diseminada (coagulopatía, falla multiorgánica).","source":"Cuadernillo Núcleo 9 Seminario 2026 (Actividad 5c, neonato) · Compendio ADN (9.f)"},
    {"id":"n9-n-14","nucleo":"9","difficulty":"normal","topic":"Streptococcus agalactiae","q":"¿Dónde coloniza Streptococcus agalactiae (EGB) a la persona gestante portadora asintomática?","a":["Tracto digestivo inferior y aparato genitourinario","Nasofaringe y piel, de donde pasa al RN por contacto","Glándula mamaria, con pasaje al RN por la lactancia","Placenta, con transmisión transplacentaria temprana"],"c":0,"exp":"EGB coloniza el aparato digestivo inferior y el genitourinario; entre el 10% y el 30% de las embarazadas son portadoras vaginales transitorias, y cerca del 60% de los hijos de madres colonizadas se colonizan.","source":"Compendio ADN (9.g) · Cuadernillo Núcleo 9 Seminario 2026 (Actividad 3a)"},
    {"id":"n9-n-15","nucleo":"9","difficulty":"normal","topic":"Diagnóstico de laboratorio","q":"¿Cuándo y cómo se pesquisa la portación de Streptococcus agalactiae en el embarazo?","a":["Semanas 35-37: hisopado vaginal y rectal, cultivo selectivo","Primer trimestre: urocultivo convencional y antibiograma","Al ingresar en trabajo de parto: hemocultivo materno","Semana 24: serología IgG e IgM contra el antígeno B"],"c":0,"exp":"Se recomienda estudiar a todas las gestantes entre las semanas 35 y 37 con cultivo en medio selectivo con antibióticos (o PCR) de muestras vaginales y rectales.","source":"Compendio ADN (9.g) · Cuadernillo Núcleo 9 Laboratorio 2026 (TP 20, Grupo 1)"},
    {"id":"n9-n-16","nucleo":"9","difficulty":"normal","topic":"Streptococcus agalactiae","q":"Una gestante con cultivo positivo para EGB inicia trabajo de parto. ¿Qué profilaxis corresponde?","a":["Penicilina G intravenosa al menos 4 h antes del parto","Vacuna anti-EGB a la gestante durante el tercer trimestre","Penicilina benzatínica IM en dosis única al RN","Ninguna: es colonización y no causa enfermedad"],"c":0,"exp":"La quimioprofilaxis intraparto es con penicilina G intravenosa al menos 4 horas antes del parto. No hay vacunas disponibles contra EGB.","source":"Compendio ADN (9.g) · Cuadernillo Núcleo 9 Laboratorio 2026 (TP 20, Grupo 1)"},
    {"id":"n9-n-17","nucleo":"9","difficulty":"normal","topic":"Treponema pallidum","q":"Según el cuadernillo, ¿en qué momentos se tamiza sífilis (VDRL/RPR) durante el embarazo?","a":["1.er trimestre, 3.er trimestre y parto o aborto","Solo en el primer control prenatal","Solo si la pareja tiene diagnóstico de sífilis","Entre las semanas 35 y 37, junto con la pesquisa de EGB"],"c":0,"exp":"El tamizaje prenatal de sífilis es universal y seriado: VDRL/RPR en el primer trimestre, en el tercer trimestre y al momento del parto o aborto.","source":"Cuadernillo Núcleo 9 Seminario 2026 (Prevención, tamizaje prenatal universal y seriado)"},
    {"id":"n9-n-18","nucleo":"9","difficulty":"normal","topic":"Treponema pallidum","q":"¿Cuál es el tratamiento de la sífilis en la persona gestante según el cuadernillo?","a":["Penicilina benzatínica y tratamiento de la pareja sexual","Penicilina benzatínica a la gestante, sin tratar a la pareja","Espiramicina hasta el final del embarazo","Penicilina G IV solo durante el trabajo de parto"],"c":0,"exp":"Se indica penicilina benzatínica según el estadio clínico materno, con tratamiento simultáneo de la pareja sexual. La penicilina es de elección; no existe vacuna.","source":"Cuadernillo Núcleo 9 Seminario 2026 (Tratamiento materno oportuno) · Compendio ADN (9.h)"},
    {"id":"n9-n-19","nucleo":"9","difficulty":"normal","topic":"Treponema pallidum","q":"¿Qué cuadro es característico de la sífilis congénita en el recién nacido que manifiesta la enfermedad?","a":["Rinitis seguida de exantema maculopapular descamativo","Vesículas en piel, ojos y boca, con compromiso del SNC","Cataratas, sordera neurosensorial y ductus persistente","Calcificaciones periventriculares y petequias"],"c":0,"exp":"La mayoría nace sin signos, pero puede aparecer rinitis seguida de un exantema maculopapular generalizado y descamativo. En no tratados son frecuentes malformaciones dentales y óseas, ceguera y sordera.","source":"Compendio ADN (9.h) · Cuadernillo Núcleo 9 Seminario 2026 (Actividad 3b)"},
    {"id":"n9-n-20","nucleo":"9","difficulty":"normal","topic":"Trypanosoma cruzi","q":"¿Cómo se diagnostica la infección por Trypanosoma cruzi en una persona gestante?","a":["Dos técnicas serológicas diferentes reactivas","Micrométodo en sangre periférica antes del parto","PCR en sangre materna como única prueba","Una sola ELISA reactiva en el primer trimestre"],"c":0,"exp":"La gestante suele estar en fase crónica indeterminada con baja parasitemia, por eso se buscan anticuerpos: dos pruebas serológicas de métodos distintos (ELISA, IFI, HAI, CMIA); si discordan, se hace una tercera.","source":"Compendio ADN (9.j) · Cuadernillo Núcleo 9 Laboratorio 2026 (TP 20, Grupo 4 y Anexo)"},
    {"id":"n9-d-01","nucleo":"9","difficulty":"dificil","topic":"Toxoplasma gondii","q":"Gestante de 14 semanas: IgG e IgM anti-Toxoplasma no reactivas. En la semana 24: IgG e IgM reactivas. ¿Cómo se interpreta?","a":["Seroconversión: infección aguda adquirida en el embarazo","Infección crónica previa al embarazo, sin riesgo fetal","Reactivación de una infección latente materna","Falso positivo por IgM persistente de años previos"],"c":0,"exp":"En la semana 14 era susceptible (sin exposición previa); el paso de negativo a positivo es una seroconversión e indica infección aguda entre las semanas 14 y 24, con riesgo de transmisión fetal.","source":"Cuadernillo Núcleo 9 Laboratorio 2026 (TP 20, Grupo 3, caso Agustina) · Compendio ADN (9.i)"},
    {"id":"n9-d-02","nucleo":"9","difficulty":"dificil","topic":"Treponema pallidum","q":"¿Por qué el diagnóstico de sífilis en la gestante se apoya en pruebas serológicas y no en el cultivo del agente?","a":["T. pallidum no se desarrolla en cultivos acelulares","El cultivo solo es positivo en la sífilis terciaria","El cultivo no distingue T. pallidum de Leptospira","T. pallidum es aerobio estricto y crece en días"],"c":0,"exp":"T. pallidum es una espiroqueta fina, microaerófila o anaerobia, muy sensible al oxígeno e incapaz de desarrollarse en cultivos acelulares. Se usa VDRL (no treponémica) y una prueba treponémica confirmatoria.","source":"Compendio ADN (9.h) · Cuadernillo Núcleo 9 Laboratorio 2026 (TP 20, Grupo 2)"},
    {"id":"n9-d-03","nucleo":"9","difficulty":"dificil","topic":"Diagnóstico de laboratorio","q":"Una gestante tiene IgG e IgM anti-Toxoplasma reactivas en una única muestra. ¿Por qué eso no alcanza para afirmar una infección aguda?","a":["La IgM puede persistir más de 12 meses tras la infección","En la toxoplasmosis la IgG aparece siempre antes que la IgM","La IgM materna también se detecta en el feto","La IgG reactiva siempre indica reactivación"],"c":0,"exp":"La IgM anti-T. gondii puede persistir más de 12 meses y dar un falso positivo de agudeza. La infección aguda se demuestra por seroconversión o aumento al doble de títulos en muestras seriadas con 3 semanas de separación.","source":"Compendio ADN (9.i, métodos diagnósticos) · Cuadernillo Núcleo 9 Laboratorio 2026 (TP 20, Grupo 3)"},
    {"id":"n9-d-04","nucleo":"9","difficulty":"dificil","topic":"Toxoplasma gondii","q":"Se confirma una toxoplasmosis aguda en una gestante. ¿Qué estudio prenatal permite evaluar si hubo infección fetal?","a":["PCR en líquido amniótico","IgM anti-Toxoplasma en suero materno","Micrométodo en sangre materna","Búsqueda de ovoquistes en heces maternas"],"c":0,"exp":"El diagnóstico prenatal se hace con ecografía y amniocentesis: la PCR del líquido amniótico para T. gondii tiene excelentes valores predictivos positivo y negativo.","source":"Compendio ADN (9.i, métodos diagnósticos) · Cuadernillo Núcleo 9 Laboratorio 2026 (TP 20, Grupo 3, pregunta 3)"},
    {"id":"n9-d-05","nucleo":"9","difficulty":"dificil","topic":"Diagnóstico de laboratorio","q":"Ante un lactante con sospecha de rubéola congénita, ¿qué hallazgo serológico apoya la infección congénita?","a":["IgM específica e IgG persistente más allá de 6-12 meses","IgG al nacer con el mismo título que la madre","IgG que cae hasta negativizarse hacia los 6 meses de vida","IgG e IgM negativas al nacer y a los 6 meses"],"c":0,"exp":"En el neonato el cuadernillo indica IgM específica más persistencia de IgG más allá de los 6-12 meses (producción propia, no materna); también RT-PCR en orina o hisopado nasofaríngeo.","source":"Cuadernillo Núcleo 9 Seminario 2026 (Actividad 5c, neonato)"},
    {"id":"n9-d-06","nucleo":"9","difficulty":"dificil","topic":"Trypanosoma cruzi","q":"Un RN hijo de madre con Chagas crónico nace sin signos clínicos. ¿Qué estudio corresponde antes del egreso hospitalario?","a":["Micrométodo o PCR en sangre del RN","ELISA y HAI en sangre del recién nacido","Ninguno, porque está asintomático","Repetir la serología materna en el parto"],"c":0,"exp":"Antes de los 10 meses se usan métodos directos: la IgG del RN puede ser materna pasiva y cerca del 10% de los RN infectados tiene IgG negativa. Entre el 60% y el 90% de los infectados es asintomático al nacer.","source":"Cuadernillo Núcleo 9 Laboratorio 2026 (TP 20, Grupo 4 y Anexo) · Compendio ADN (9.j)"},
    {"id":"n9-d-07","nucleo":"9","difficulty":"dificil","topic":"Trypanosoma cruzi","q":"Un RN hijo de madre con Chagas tiene un micrométodo negativo antes del egreso. ¿Qué conducta corresponde?","a":["Seguimiento y serología a partir de los 10 meses de vida","Alta definitiva: el micrométodo negativo descarta la infección","Serología al mes de vida para confirmar o descartar","Iniciar benznidazol sin más estudios"],"c":0,"exp":"Un micrométodo negativo no descarta la infección. Hasta los 10 meses la IgG del niño puede ser materna, por eso el diagnóstico final se hace con serología (dos técnicas) a partir de los 10 meses.","source":"Cuadernillo Núcleo 9 Laboratorio 2026 (TP 20, Grupo 4, pregunta 5 y Anexo)"},
    {"id":"n9-d-08","nucleo":"9","difficulty":"dificil","topic":"Streptococcus agalactiae","q":"RN por parto vaginal, de madre portadora de EGB sin profilaxis intraparto, presenta a las 34 h dificultad respiratoria y sospecha de sepsis. ¿Cómo se clasifica?","a":["Enfermedad de comienzo precoz por EGB","Enfermedad de comienzo tardío por EGB","Infección transplacentaria con malformaciones","Colonización benigna sin enfermedad invasiva"],"c":0,"exp":"La enfermedad de comienzo precoz se presenta con bacteriemia, neumonía o meningitis; la tardía, con bacteriemia con meningitis. EGB es la causa más frecuente de septicemia y meningitis en el recién nacido.","source":"Cuadernillo Núcleo 9 Seminario 2026 (Actividad 3a, caso clínico) · Compendio ADN (9.g)"},
    {"id":"n9-d-09","nucleo":"9","difficulty":"dificil","topic":"Virus herpes simple 1 y 2","q":"RN con letargo y convulsiones; su madre tenía lesiones vesiculares genitales al parto. Ante sospecha de herpes neonatal con compromiso del SNC, ¿qué estudio corresponde?","a":["PCR para VHS en LCR","IgG anti-VHS en suero del recién nacido","Test de Tzanck en LCR","Cultivo de LCR en medio selectivo para EGB"],"c":0,"exp":"En el neonato se usa PCR o cultivo viral de hisopado de vesículas o mucosas y, si hay compromiso del SNC, PCR en LCR.","source":"Cuadernillo Núcleo 9 Seminario 2026 (Actividad 5c, neonato) · Compendio ADN (tabla de agentes, HSV)"},
    {"id":"n9-d-10","nucleo":"9","difficulty":"dificil","topic":"Treponema pallidum","q":"Gestante con VDRL reactiva 1/32 y prueba treponémica positiva llega al parto sin tratamiento completo documentado. El RN está asintomático. ¿Qué conducta corresponde?","a":["Evaluar LCR (VDRL), Rx de huesos largos y laboratorio","Alta sin estudios, porque está asintomático al nacer","Solo una prueba treponémica en sangre del RN y alta","Comparar VDRL con la madre y dar el alta si es menor"],"c":0,"exp":"Sin tratamiento materno adecuado, el RN asintomático se evalúa para definir el esquema de tratamiento: LCR (células, proteínas y VDRL), Rx de huesos largos, hemograma, hepatograma y ecografías.","source":"Cuadernillo Núcleo 9 Laboratorio 2026 (TP 20, Grupo 2, caso Sofía y algoritmo) · Compendio ADN (9.h, punto 2)"},
    {"id":"n9-d-11","nucleo":"9","difficulty":"dificil","topic":"Diagnóstico de laboratorio","q":"Gestante con sífilis tratada en forma adecuada y con tiempo antes del parto; RN asintomático. ¿Qué comparación puntual se realiza?","a":["Títulos de VDRL del RN frente a los de la madre","Prueba treponémica del RN frente a la materna","IgM del RN frente a la IgG de la madre","VDRL del RN al nacer frente a la del mes de vida"],"c":0,"exp":"En el RN asintomático de una gestante adecuadamente tratada se comparan los títulos de la prueba no treponémica (VDRL) del neonato con los maternos para definir la conducta.","source":"Cuadernillo Núcleo 9 Laboratorio 2026 (TP 20, Grupo 2, pregunta 4) · Compendio ADN (9.h, punto 1)"},
    {"id":"n9-d-12","nucleo":"9","difficulty":"dificil","topic":"Virus varicela-zóster","q":"Un recién nacido presenta cicatrices cutáneas, hipoplasia de miembros y microoftalmia. ¿Qué agente de transmisión vertical es el más probable?","a":["Virus varicela-zóster","Virus de la rubéola","Citomegalovirus","Treponema pallidum"],"c":0,"exp":"Es el síndrome de varicela congénita: lesiones cutáneas cicatrizales, hipoplasia de miembros y alteraciones oculares (microoftalmia) o del SNC. El diagnóstico se apoya en PCR del líquido vesicular y el antecedente materno.","source":"Compendio ADN (tabla de agentes, varicela) · Cuadernillo Núcleo 9 Seminario 2026 (Actividad 5c)"},
    {"id":"n9-d-13","nucleo":"9","difficulty":"dificil","topic":"Citomegalovirus (CMV)","q":"RN con hepatoesplenomegalia, petequias, microcefalia y calcificaciones periventriculares; la madre tuvo un cuadro mononucleosiforme leve. ¿Agente más probable?","a":["Citomegalovirus","Virus de la rubéola","Virus varicela-zóster","Virus de la hepatitis B"],"c":0,"exp":"El 10-15% de los RN con CMV congénito es sintomático: hepatoesplenomegalia, petequias, microcefalia, calcificaciones periventriculares y coriorretinitis. En la gestante suele ser asintomático o mononucleosiforme.","source":"Cuadernillo Núcleo 9 Seminario 2026 (Actividad 5c) · Compendio ADN (9.b)"},
    {"id":"n9-d-14","nucleo":"9","difficulty":"dificil","topic":"Diagnóstico de laboratorio","q":"Una gestante tiene IgG positiva e IgM negativa para CMV y para rubéola. ¿Qué implica para el riesgo fetal en el embarazo actual?","a":["Rubéola: riesgo prácticamente nulo; CMV: bajo pero no nulo","Ambos sin riesgo, porque la IgG materna protege","Ambos con alto riesgo: IgM negativa indica susceptibilidad","Rubéola: riesgo por reactivación; CMV: sin riesgo"],"c":0,"exp":"Ambos patrones indican infección pasada. En rubéola la inmunidad materna impide en la práctica la transmisión; en CMV el riesgo es bajo pero persiste por reactivación o reinfección por otra cepa.","source":"Compendio ADN (9.b, pregunta d) · Cuadernillo Núcleo 9 Seminario 2026 (Actividad 2d y 5b)"},
    {"id":"n9-d-15","nucleo":"9","difficulty":"dificil","topic":"Virus de la inmunodeficiencia humana (VIH)","q":"Gestante de 17 años sin controles en trabajo de parto; a ella se la estudia con prueba rápida para VIH. ¿Qué método corresponde para diagnosticar VIH en el RN?","a":["PCR de ADN proviral (método directo)","La misma prueba rápida de anticuerpos","ELISA de 4.ª generación al nacer","Recuento de CD4 en sangre de cordón"],"c":0,"exp":"La madre se estudia con métodos indirectos (prueba rápida o ELISA), pero en el RN el cuadernillo indica pruebas virológicas o moleculares: PCR de ADN proviral. Además se indica profilaxis antirretroviral al RN.","source":"Cuadernillo Núcleo 9 Laboratorio 2026 (TP 20, Grupo 5) · Cuadernillo Núcleo 9 Seminario 2026 (Actividad 5c; Manejo neonatal)"},
    {"id":"n10-f-01","nucleo":"10","difficulty":"facil","topic":"Aedes aegypti","q":"¿Cuál es el principal vector del dengue en los ciclos urbanos de nuestro país?","a":["Aedes aegypti","Anopheles hembra, de picadura nocturna","Flebótomos de la subfamilia Phlebotominae","Triatominos domiciliarios como la vinchuca"],"c":0,"exp":"Aedes aegypti es una especie introducida e invasora que se volvió la principal de importancia sanitaria en Argentina: transmite dengue, Zika, chikungunya y fiebre amarilla urbana.","source":"Cuadernillo Núcleo 10 Vectores 2026 (Seminario e Introducción) · Compendio ADN (10)"},
    {"id":"n10-f-02","nucleo":"10","difficulty":"facil","topic":"Virus del dengue","q":"¿A qué familia pertenece el virus del dengue y cuántas variantes circulan?","a":["Flaviviridae (Flavivirus), con cuatro serotipos","Togaviridae (Alphavirus), con cuatro serotipos","Peribunyaviridae, con dos serotipos descriptos","Flaviviridae, pero con un único serotipo circulante"],"c":0,"exp":"El virus del dengue es un Flavivirus de la familia Flaviviridae y existen cuatro variantes: DENV 1, 2, 3 y 4.","source":"Cuadernillo Núcleo 10 Vectores 2026 (Introducción) · Compendio ADN (10.a)"},
    {"id":"n10-f-03","nucleo":"10","difficulty":"facil","topic":"Trypanosoma cruzi","q":"¿Cuál es el vector principal de Trypanosoma cruzi en la enfermedad de Chagas-Mazza?","a":["Los triatominos, como la vinchuca (Triatoma infestans)","El mosquito Aedes aegypti, de hábitos diurnos y urbanos","Los flebótomos de zonas rurales y peridomiciliarias","Los mosquitos Culex que crían en grandes humedales"],"c":0,"exp":"El vector del Chagas son los triatominos; en Argentina Triatoma infestans, antropófila, de hábitos nocturnos y que vuela poco, coloniza la vivienda precaria.","source":"Cuadernillo Núcleo 10 Vectores 2026 (Actividad 5 y TP 21) · Compendio ADN (10.g)"},
    {"id":"n10-f-04","nucleo":"10","difficulty":"facil","topic":"Plasmodium spp.","q":"¿Qué insecto transmite el paludismo y qué hábito de picadura tiene?","a":["El mosquito Anopheles hembra, de picadura nocturna","El mosquito Aedes aegypti, de picadura diurna","El flebótomo hembra, que pica al atardecer","El triatomino, que pica de noche y defeca al alimentarse"],"c":0,"exp":"El vector del paludismo es la hembra de Anopheles, que cría en pantanos y agua estancada, pica de noche y es antropofílica.","source":"Cuadernillo Núcleo 10 Vectores 2026 (TP 21, Actividad 2) · Compendio ADN (10.e)"},
    {"id":"n10-f-05","nucleo":"10","difficulty":"facil","topic":"Leishmania spp.","q":"¿Qué insectos transmiten la leishmaniasis?","a":["Dípteros flebótomos de la subfamilia Phlebotominae","Mosquitos del género Anopheles, de actividad nocturna","Mosquitos Aedes que crían en recipientes artificiales","Chinches triatominas que colonizan el intradomicilio"],"c":0,"exp":"Leishmania se transmite por la picadura de dípteros flebótomos (familia Psychodidae, subfamilia Phlebotominae), de hábitat rural y peridomiciliario y mayor actividad al atardecer y de noche.","source":"Cuadernillo Núcleo 10 Vectores 2026 (Actividad 4 y TP 21) · Compendio ADN (10.f)"},
    {"id":"n10-f-06","nucleo":"10","difficulty":"facil","topic":"Virus de la fiebre amarilla","q":"¿Con qué cepa se prepara la vacuna contra la fiebre amarilla y qué duración de inmunidad genera?","a":["Cepa 17D, con inmunidad para toda la vida","Cepa 17D, pero exige un refuerzo anual","Cepa TAK-003, con dos dosis separadas por tres meses","No hay vacuna: solo se hace control vectorial"],"c":0,"exp":"La vacuna se prepara con la cepa 17D (virus vivo atenuado) y, según la OMS, una dosis protege de por vida. En Argentina el calendario la indica a los 18 meses, con refuerzo a los 11 años, en zonas de riesgo.","source":"Compendio ADN (10.b, punto 4) · Cuadernillo Núcleo 10 Vectores 2026 (Actividad 2)"},
    {"id":"n10-f-07","nucleo":"10","difficulty":"facil","topic":"Aedes aegypti","q":"En el ambiente urbano, ¿dónde pone sus huevos Aedes aegypti?","a":["En recipientes artificiales con agua limpia y estancada","En pantanos y charcas con abundante vegetación","En grietas de paredes de barro y techos de paja","En materia orgánica sombreada del peridomicilio rural"],"c":0,"exp":"Aedes aegypti usa cualquier contenedor que acumule agua (macetas, cubetas, botellas). Por eso la medida central es eliminar criaderos; los pantanos son el criadero de Anopheles.","source":"Cuadernillo Núcleo 10 Vectores 2026 (TP 21, Actividad 1) · Compendio ADN (10)"},
    {"id":"n10-f-08","nucleo":"10","difficulty":"facil","topic":"Virus chikungunya","q":"¿A qué familia pertenece el virus chikungunya?","a":["Togaviridae, es un alphavirus","Flaviviridae, igual que dengue y Zika","Peribunyaviridae, igual que el virus Oropouche","Flaviviridae, aunque sin reactividad cruzada"],"c":0,"exp":"Chikungunya es un alphavirus de la familia Togaviridae, a diferencia de dengue, Zika y fiebre amarilla, que son Flaviviridae. Comparte con ellos el vector Aedes.","source":"Cuadernillo Núcleo 10 Vectores 2026 (cuadro de agentes) · Compendio ADN (10.d)"},
    {"id":"n10-f-09","nucleo":"10","difficulty":"facil","topic":"Plasmodium spp.","q":"Entre los tres protozoos del núcleo, ¿cuál es el apicomplexa?","a":["Plasmodium spp.","Trypanosoma cruzi","Leishmania spp.","Ninguno: los tres son protozoos flagelados"],"c":0,"exp":"Plasmodium es un protozoo apicomplexa (esporozoario); Trypanosoma cruzi y Leishmania son protozoos flagelados.","source":"Cuadernillo Núcleo 10 Vectores 2026 (cuadro de agentes) · Compendio ADN (10)"},
    {"id":"n10-f-10","nucleo":"10","difficulty":"facil","topic":"Prevención","q":"¿En qué se basa la prevención del paludismo en la mayoría de los países?","a":["En el rociado residual intradomiciliario y los mosquiteros con insecticida","En la vacunación masiva y gratuita de toda la población de las zonas endémicas","En el control de los bancos de sangre y el tamizaje de donantes","En el mejoramiento habitacional con revoque y pisos de madera"],"c":0,"exp":"La prevención del paludismo se apoya en el rociado residual intradomiciliario (RRI) y en la distribución de mosquiteros tratados con insecticida (MTI).","source":"Cuadernillo Núcleo 10 Vectores 2026 (Introducción) · Compendio ADN (10)"},
    {"id":"n10-n-01","nucleo":"10","difficulty":"normal","topic":"Arbovirus","q":"¿Qué significa que un virus sea un arbovirus?","a":["Que se agrupa por su transmisión vectorial por artrópodos, no por su taxonomía","Que pertenece a la familia Flaviviridae y tiene ARN de polaridad positiva","Que es un género viral definido por la secuencia de su glucoproteína E","Que solo puede replicarse en células de invertebrados, nunca de vertebrados"],"c":0,"exp":"Arbovirus (arthropod borne viral diseases) no es una clasificación taxonómica sino un agrupamiento ecológico basado en la transmisión por artrópodos; incluye varias familias virales.","source":"Cuadernillo Núcleo 10 Vectores 2026 (Introducción) · Compendio ADN (10)"},
    {"id":"n10-n-02","nucleo":"10","difficulty":"normal","topic":"Arbovirus","q":"Una vez que el mosquito ingiere sangre virémica, ¿cuál es el recorrido del arbovirus dentro del vector?","a":["Epitelio intestinal, lámina basal, hemolinfa y glándulas salivales","Glándulas salivales, hemolinfa y después epitelio intestinal","Hemolinfa, ovarios y transmisión exclusivamente a la descendencia","Epitelio intestinal y luego eliminación en las deyecciones del insecto"],"c":0,"exp":"El virus replica en el epitelio intestinal, atraviesa la lámina basal, viaja por la hemolinfa y se acumula en las glándulas salivales, desde donde se inocula con la saliva.","source":"Cuadernillo Núcleo 10 Vectores 2026 (Introducción, Figura 1) · Compendio ADN (10)"},
    {"id":"n10-n-03","nucleo":"10","difficulty":"normal","topic":"Virus del dengue","q":"¿Cuáles son las características estructurales del virus del dengue?","a":["ARN monocatenario positivo, envuelto, con glucoproteína E externa","ADN bicatenario desnudo, con cápside icosaédrica y replicación nuclear","ARN segmentado de polaridad negativa, envuelto","ARN monocatenario positivo pero sin envoltura lipídica"],"c":0,"exp":"Los cuatro serotipos son ARN monocatenario positivo con envoltura, donde la glucoproteína E forma la capa externa y expresa determinantes antigénicos compartidos entre flavivirus.","source":"Compendio ADN (10.a, punto 1) · Cuadernillo Núcleo 10 Vectores 2026 (Actividad 2)"},
    {"id":"n10-n-04","nucleo":"10","difficulty":"normal","topic":"Vectores","q":"¿Qué combinación de vector y hábitat de cría o refugio es correcta?","a":["Triatoma, grietas de paredes rústicas; Anopheles, cuerpos de agua con vegetación","Triatoma, microcontenedores urbanos; Anopheles, grietas de paredes de barro","Lutzomyia, agua limpia de macetas; Aedes, materia orgánica sombreada","Los cuatro usan los mismos microhábitats urbanos con agua estancada"],"c":0,"exp":"Los vectores de parásitos piden nichos rústicos (grietas para Triatoma, materia orgánica sombreada para Lutzomyia, agua con vegetación para Anopheles); Aedes aegypti usa microcontenedores artificiales urbanos.","source":"Cuadernillo Núcleo 10 Vectores 2026 (TP 21, Introducción)"},
    {"id":"n10-n-05","nucleo":"10","difficulty":"normal","topic":"Virus del dengue","q":"En la primoinfección por dengue, ¿cuándo ocurre la etapa crítica y con qué signo coincide?","a":["Entre los días 4 y 7, al caer la fiebre (defervescencia)","En los primeros dos días, con el pico febril de 40 °C","Después del día 10, cuando la IgM alcanza su máximo","Durante la etapa de recuperación, con la reabsorción del líquido"],"c":0,"exp":"La etapa crítica va aproximadamente del día 4 al 7 y coincide con la defervescencia: es el período de mayor riesgo por extravasación de plasma, hemorragias y daño de órganos.","source":"Compendio ADN (10.a, etapas) · Cuadernillo Núcleo 10 Vectores 2026 (Actividad 1.b.I)"},
    {"id":"n10-n-06","nucleo":"10","difficulty":"normal","topic":"Epidemiología","q":"¿Qué integra la tríada ecoepidemiológica de las infecciones de transmisión vectorial?","a":["Patógeno, vector y hospedador","Vector, reservorio y vacuna disponible","Clima, insecticida y vivienda precaria","Patógeno, hospedador intermedio y hospedador definitivo"],"c":0,"exp":"La tríada es patógeno + vector + hospedador, modulada por la matriz ambiental y socioeconómica: la temperatura, la humedad y el régimen hídrico regulan la competencia vectorial.","source":"Cuadernillo Núcleo 10 Vectores 2026 (TP 21, Introducción)"},
    {"id":"n10-n-07","nucleo":"10","difficulty":"normal","topic":"Virus del dengue","q":"¿Cuál es el mecanismo del fenómeno de amplificación dependiente de anticuerpos (ADA) en el dengue?","a":["Anticuerpos no neutralizantes facilitan la entrada del virus a células mononucleares","Anticuerpos neutralizantes bloquean la glucoproteína E y lisan los hepatocitos","Los linfocitos T citotóxicos destruyen las plaquetas por reconocimiento directo del virus","El interferón inducido por el virus produce la extravasación de plasma"],"c":0,"exp":"Los anticuerpos producidos contra un serotipo no son necesariamente neutralizantes frente a otro: al unirse al virus favorecen su entrada en macrófagos y monocitos vía receptores Fc y amplifican la infección.","source":"Cuadernillo Núcleo 10 Vectores 2026 (Actividad 1.b.IV) · Compendio ADN (10.a, punto 2)"},
    {"id":"n10-n-08","nucleo":"10","difficulty":"normal","topic":"Respuesta inmune","q":"En la inmunopatogenia del dengue, ¿qué citocina se relaciona con las manifestaciones hemorrágicas?","a":["TNF-α","IL-4","IL-10","Interferón gamma producido por linfocitos B"],"c":0,"exp":"Los macrófagos producen citocinas proinflamatorias (IL-1β, IL-2, IL-6, IL-8 y TNF-α); el TNF-α se vincula con las hemorragias al favorecer la trombocitopenia y la disfunción endotelial.","source":"Cuadernillo Núcleo 10 Vectores 2026 (Actividad 1.b.II y III) · Compendio ADN (10, respuesta inmune)"},
    {"id":"n10-n-09","nucleo":"10","difficulty":"normal","topic":"Diagnóstico de laboratorio","q":"Un paciente con sospecha de dengue consulta en el segundo día de fiebre. ¿Qué método diagnóstico corresponde?","a":["RT-PCR para el ARN viral o ELISA de antígeno","IgM específica por ELISA de captura","Comparar títulos de IgG de fase aguda y convaleciente","Inmunofluorescencia indirecta sobre biopsia hepática"],"c":0,"exp":"En la viremia temprana se usa aislamiento viral, RT-PCR o ELISA de antígeno; la IgM recién se hace detectable en la etapa crítica, cuando la viremia desaparece.","source":"Compendio ADN (10.a, punto 5) · Cuadernillo Núcleo 10 Vectores 2026 (TP 21, Actividad 1.d)"},
    {"id":"n10-n-10","nucleo":"10","difficulty":"normal","topic":"Virus de la fiebre amarilla","q":"¿Cómo es la patogenia de la fiebre amarilla en su forma grave?","a":["Enfermedad bifásica con tropismo hepático y renal, ictericia y hemorragias","Enfermedad monofásica con artritis paralizante persistente","Infección leve con sarpullido, conjuntivitis no purulenta y dolor en manos y pies","Accesos febriles periódicos por ruptura sincronizada de eritrocitos"],"c":0,"exp":"Es bifásica: una fase febril inicial y, tras una breve remisión, la forma grave por localización hepática y renal, con ictericia, hemorragias digestivas (vómito negro) y letalidad de hasta 50% en epidemias.","source":"Compendio ADN (10.b, punto 2) · Cuadernillo Núcleo 10 Vectores 2026 (Actividad 2)"},
    {"id":"n10-n-11","nucleo":"10","difficulty":"normal","topic":"Virus del Zika","q":"Según el Ministerio de Salud, ¿qué signo acompaña al sarpullido en el cuadro sintomático del Zika?","a":["Conjuntivitis no purulenta","Ictericia con vómito negro","Esplenomegalia con pancitopenia","Úlcera indolora de fondo granuloso en el sitio de la picadura"],"c":0,"exp":"El cuadro incluye sarpullido más fiebre, conjuntivitis no purulenta, cefalea, dolor corporal y articular (manos y pies), decaimiento e inflamación de miembros inferiores; puede dar problemas neurológicos.","source":"Compendio ADN (10.c, punto 2, sintomatología del Ministerio de Salud)"},
    {"id":"n10-n-12","nucleo":"10","difficulty":"normal","topic":"Virus chikungunya","q":"¿Qué manifestación clínica le da el nombre a la enfermedad por virus chikungunya?","a":["Las artralgias intensas que hacen caminar encorvado","La ictericia de la forma grave","El shock por extravasación de plasma","La microcefalia de la infección congénita"],"c":0,"exp":"El nombre, en lengua makonde, alude a la postura encorvada por las artralgias intensas (el material habla de «artritis paralizante»). No hay antiviral específico ni vacuna en el Calendario Nacional.","source":"Compendio ADN (10.d, puntos 2 y 4) · Cuadernillo Núcleo 10 Vectores 2026 (Actividad 2)"},
    {"id":"n10-n-13","nucleo":"10","difficulty":"normal","topic":"Plasmodium spp.","q":"En el ciclo de Plasmodium, ¿qué papel cumple el mosquito Anopheles?","a":["Es el hospedador definitivo, donde ocurre la fase sexual o esporogónica","Es el hospedador intermedio, donde ocurre la fase eritrocítica","Es solo un transportador mecánico, sin replicación del parásito","Es el reservorio donde el parásito persiste como hipnozoíto"],"c":0,"exp":"El ciclo es heteroxénico: el humano es el hospedador intermedio (fases exoeritrocítica y eritrocítica) y el Anopheles hembra el definitivo, donde se da la fase sexual o esporogónica.","source":"Compendio ADN (10.e, cadena epidemiológica) · Cuadernillo Núcleo 10 Vectores 2026 (Actividad 3)"},
    {"id":"n10-n-14","nucleo":"10","difficulty":"normal","topic":"Plasmodium spp.","q":"¿Qué estadio de Plasmodium entra al ser humano con la picadura y hacia dónde se dirige?","a":["El esporozoíto, que viaja al hígado","El gametocito, que queda en sangre periférica","El merozoíto, que va directo al eritrocito","El tripomastigote metacíclico, que penetra en la dermis"],"c":0,"exp":"El Anopheles inocula esporozoítos maduros de sus glándulas salivales en la dermis y el torrente sanguíneo; los esporozoítos viajan al hígado para la fase preeritrocítica o exoeritrocítica.","source":"Compendio ADN (10.e, puerta de entrada) · Cuadernillo Núcleo 10 Vectores 2026 (Actividad 3)"},
    {"id":"n10-n-15","nucleo":"10","difficulty":"normal","topic":"Plasmodium spp.","q":"¿Cuál es la puerta de salida de Plasmodium desde el hospedador humano?","a":["Los gametocitos de la sangre periférica, ingeridos por el mosquito","Los esporozoítos liberados por el hígado hacia la bilis","Los merozoítos eliminados por orina durante los accesos febriles","Los trofozoítos que salen por las lesiones cutáneas de la picadura"],"c":0,"exp":"El mosquito ingiere micro y macrogametocitos al alimentarse; estos resisten la digestión en el estómago del vector e inician la esporogonia.","source":"Compendio ADN (10.e, puerta de salida) · Cuadernillo Núcleo 10 Vectores 2026 (Actividad 3)"},
    {"id":"n10-n-16","nucleo":"10","difficulty":"normal","topic":"Leishmania spp.","q":"¿Qué formas presenta Leishmania en el mamífero y en el vector, y cuál es su tropismo celular?","a":["Amastigote intracelular en el mamífero y promastigote flagelado en el vector","Promastigote intracelular en el mamífero y amastigote flagelado en el vector","Epimastigote en el mamífero y tripomastigote metacíclico en el vector","Esporozoíto en el mamífero y gametocito en el intestino del vector"],"c":0,"exp":"Es un parásito dimorfo: promastigote flagelado en el vector y amastigote intracelular obligado en las células del sistema fagocítico mononuclear (macrófagos y monocitos) del mamífero.","source":"Compendio ADN (10.f, puntos 1 y I) · Cuadernillo Núcleo 10 Vectores 2026 (Actividad 4.b.I)"},
    {"id":"n10-n-17","nucleo":"10","difficulty":"normal","topic":"Leishmania spp.","q":"¿Qué cuadro clínico define a la leishmaniasis visceral o kala-azar?","a":["Fiebre, esplenomegalia, caquexia y pancitopenia","Úlceras cutáneas indoloras con fondo granuloso","Destrucción del tabique nasal con disfonía","Infiltrados nodulares difusos de aspecto leprómico, sin úlcera"],"c":0,"exp":"La forma visceral (kala-azar) cursa con fiebre, esplenomegalia, caquexia y pancitopenia por compromiso del sistema fagocítico mononuclear: bazo, hígado, médula ósea y ganglios.","source":"Compendio ADN (10.f, punto II) · Cuadernillo Núcleo 10 Vectores 2026 (Actividad 4.b.II y III)"},
    {"id":"n10-n-18","nucleo":"10","difficulty":"normal","topic":"Trypanosoma cruzi","q":"¿Cómo ingresa Trypanosoma cruzi al ser humano en la transmisión vectorial?","a":["Por los tripomastigotes metacíclicos de las deyecciones del triatomino","Por los tripomastigotes inoculados con la saliva del triatomino","Por los amastigotes que el vector regurgita mientras se alimenta","Por los epimastigotes que atraviesan la piel intacta del hospedador"],"c":0,"exp":"La vía vectorial es por las deyecciones del triatomino infectado al picar: los tripomastigotes metacíclicos penetran las células en el sitio de la picadura y se transforman en amastigotes.","source":"Compendio ADN (10.g, vías de transmisión y formas) · Cuadernillo Núcleo 10 Vectores 2026 (Actividad 5)"},
    {"id":"n10-n-19","nucleo":"10","difficulty":"normal","topic":"Trypanosoma cruzi","q":"¿Qué forma de Trypanosoma cruzi se multiplica en el intestino medio del triatomino?","a":["El epimastigote","El amastigote","El tripomastigote metacíclico","El promastigote procíclico, que después hace metaciclogénesis"],"c":0,"exp":"En el vector, los tripomastigotes pasan a esferomastigotes en el estómago y luego a epimastigotes fusiformes y móviles que se reproducen en el intestino medio; en el intestino posterior se forman los metacíclicos.","source":"Compendio ADN (10.g, formas del parásito)"},
    {"id":"n10-n-20","nucleo":"10","difficulty":"normal","topic":"Trypanosoma cruzi","q":"Además de la vectorial, ¿cuáles son otras vías de transmisión de la enfermedad de Chagas-Mazza?","a":["Transfusional, congénita, oral, accidental y por trasplantes","Respiratoria por aerosoles y contacto interhumano casual","Sexual y por fómites contaminados con deyecciones secas","Solo la congénita, porque las demás fueron descartadas"],"c":0,"exp":"La vectorial es la principal en la naturaleza, pero también se transmite por sangre o plasma contaminados, por vía transplacentaria (alrededor del 5 % de los hijos de madres infectadas), oral, accidental y por trasplantes.","source":"Compendio ADN (10.g, vías de transmisión) · Cuadernillo Núcleo 10 Vectores 2026 (Actividad 4, casos clínicos)"},
    {"id":"n10-d-01","nucleo":"10","difficulty":"dificil","topic":"Plasmodium spp.","q":"Un nene de 6 años de una región subtropical tiene fiebre, escalofríos y sudoración cada 48 h. La gota gruesa muestra eritrocitos con trofozoítos y gametocitos. ¿Qué explica la periodicidad?","a":["La esquizogonia eritrocítica sincronizada, que rompe los glóbulos rojos cada 48 h","La esquizogonia exoeritrocítica hepática, que libera merozoítos cada 48 h","La fase esporogónica del mosquito, que dura entre 8 y 12 días","La activación periódica de hipnozoítos latentes en el hepatocito"],"c":0,"exp":"La fiebre terciana corresponde a accesos cada 48 h por el ciclo esquizogónico eritrocítico, cuya ruptura sincronizada libera merozoítos y pigmento y produce las etapas fría, caliente y de sudoración.","source":"Cuadernillo Núcleo 10 Vectores 2026 (Actividad 3.c y casos clínicos, Caso 1) · Compendio ADN (10.e)"},
    {"id":"n10-d-02","nucleo":"10","difficulty":"dificil","topic":"Plasmodium spp.","q":"¿Qué especie de Plasmodium produce fiebre cuartana y qué la caracteriza?","a":["P. malariae, con ciclo de 72 h y persistencia crónica","P. falciparum, con ciclo de 72 h y alta letalidad","P. vivax, con ciclo de 48 h y recaídas por hipnozoítos","P. ovale, con ciclo de 72 h y accesos cada dos días"],"c":0,"exp":"P. malariae da fiebre cuartana (cada 72 h) y persistencia crónica por su tropismo eritrocítico estable sin hipnozoítos. La terciana la causan P. falciparum (maligna), P. vivax y P. ovale.","source":"Compendio ADN (10.e, fiebre terciana y cuartana) · Cuadernillo Núcleo 10 Vectores 2026 (Actividad 3.c)"},
    {"id":"n10-d-03","nucleo":"10","difficulty":"dificil","topic":"Plasmodium spp.","q":"¿Qué ocurre durante la fase esporogónica en el Anopheles y cuánto dura?","a":["Los gametocitos forman ooquistes que liberan miles de esporozoítos en 1-2 semanas","Los esporozoítos se transforman en gametocitos en 18-25 días","Los merozoítos invaden el epitelio intestinal y se replican en 48 h","Los trofozoítos maduran a esquizontes en las glándulas salivales en 72 h"],"c":0,"exp":"Los gametocitos forman gametos, cigoto, oocineto y ooquiste, que libera miles de esporozoítos en 1 a 2 semanas (8-12 días según el material; depende de la temperatura); migran a las glándulas salivales.","source":"Compendio ADN (10.e, modo de transmisión y ciclo en el vector)"},
    {"id":"n10-d-04","nucleo":"10","difficulty":"dificil","topic":"Epidemiología","q":"¿Cuál es la situación de Argentina respecto del paludismo según la OMS?","a":["Está certificada libre de malaria, pero sigue vigilando casos importados","Es endémica en el NOA, con transmisión autóctona sostenida durante todo el año","Nunca tuvo transmisión autóctona, así que no requiere vigilancia","Está en fase de preeliminación, junto con Paraguay y El Salvador"],"c":0,"exp":"Argentina fue certificada libre de malaria por la OMS en 2019 (Paraguay en 2018, El Salvador en 2021, Belice en 2023), pero los sistemas sanitarios siguen vigilando eventuales casos importados.","source":"Cuadernillo Núcleo 10 Vectores 2026 (Introducción) · Cuadernillo TP 21 (Actividad 2.c)"},
    {"id":"n10-d-05","nucleo":"10","difficulty":"dificil","topic":"Diagnóstico de laboratorio","q":"¿Qué resultado serológico indica infección reciente por dengue?","a":["IgM específica en suero agudo o aumento al cuádruple del título de IgG","IgG positiva en una única muestra de la fase convaleciente","IgM negativa con IgG positiva en el primer día de fiebre","Cualquier título de IgG, porque no hay reactividad cruzada entre flavivirus"],"c":0,"exp":"La presencia de IgM específica o un incremento al cuádruple del título entre el suero agudo y el convaleciente indican infección reciente. Hay que considerar la reactividad cruzada entre flavivirus.","source":"Compendio ADN (10.a, punto 5) · Cuadernillo Núcleo 10 Vectores 2026 (TP 21, Actividad 1.d)"},
    {"id":"n10-d-06","nucleo":"10","difficulty":"dificil","topic":"Virus del dengue","q":"¿Qué par de hallazgos de laboratorio define la etapa crítica del dengue?","a":["Plaquetas en su punto más bajo y pico de hematocrito","Plaquetas en su punto más bajo y hematocrito descendido","Plaquetas en recuperación y hematocrito en su valor basal","Viremia alta con IgM e IgG todavía indetectables"],"c":0,"exp":"En la etapa crítica el recuento de plaquetas toca su mínimo y el hematocrito su máximo, por la hemoconcentración que produce la extravasación de plasma. En la recuperación el riesgo es la sobrecarga de líquidos.","source":"Compendio ADN (10.a, etapas) · Cuadernillo Núcleo 10 Vectores 2026 (Actividad 1.b.I)"},
    {"id":"n10-d-07","nucleo":"10","difficulty":"dificil","topic":"Respuesta inmune","q":"¿Cómo contribuye el complemento al aumento de la permeabilidad vascular en el dengue grave?","a":["Los inmunocomplejos activan la vía clásica y aumentan las anafilotoxinas C3a/C5a","La vía de las lectinas lisa de forma directa las plaquetas y el endotelio vascular","El complejo de ataque a la membrana destruye los hepatocitos infectados","La vía alternativa neutraliza la glucoproteína E y bloquea la viremia"],"c":0,"exp":"Los anticuerpos heterólogos no neutralizantes activan el complemento por la vía clásica, con aumento de las anafilotoxinas C3a y C5a, que incrementan la permeabilidad vascular.","source":"Cuadernillo Núcleo 10 Vectores 2026 (Actividad 1.b.III) · Compendio ADN (10, complicaciones)"},
    {"id":"n10-d-08","nucleo":"10","difficulty":"dificil","topic":"Prevención","q":"¿Cómo recomienda el Ministerio de Salud la vacuna contra el dengue en Argentina?","a":["De 15 a 39 años en departamentos priorizados, dos dosis separadas por tres meses","A toda la población de las zonas endémicas del NEA y NOA, en dosis única anual","A los menores de 15 años del NEA y del NOA, con un esquema de tres dosis","De 15 a 39 años en zonas endémicas, y ya integra el Calendario Nacional"],"c":0,"exp":"Es una estrategia focalizada con Qdenga (TAK-003) en departamentos priorizados por carga de dengue del NOA, el NEA y el Centro, con dos dosis separadas por tres meses; no integra el Calendario Nacional.","source":"Compendio ADN (10.a, punto 4) · Cuadernillo Núcleo 10 Vectores 2026 (Actividad 1.c)"},
    {"id":"n10-d-09","nucleo":"10","difficulty":"dificil","topic":"Leishmania spp.","q":"Un maderero de Puerto Iguazú tiene lesiones nodulares en tórax de un año de evolución; la biopsia muestra amastigotes dentro de macrófagos. ¿Cuál es el diagnóstico?","a":["Leishmaniasis tegumentaria","Enfermedad de Chagas-Mazza en fase aguda","Paludismo por P. vivax","Forma cutánea diseminada de la fiebre amarilla"],"c":0,"exp":"Los amastigotes dentro de macrófagos dérmicos confirman leishmaniasis tegumentaria, con especies dermatotrópicas como L. braziliensis y L. guyanensis; la exposición laboral en monte es el antecedente clave.","source":"Cuadernillo Núcleo 10 Vectores 2026 (Actividad 4, casos clínicos, Caso 2) · Compendio ADN (10.f)"},
    {"id":"n10-d-10","nucleo":"10","difficulty":"dificil","topic":"Leishmania spp.","q":"En la leishmaniasis tegumentaria, ¿qué caracteriza al polo anérgico del espectro clínico?","a":["Alta carga parasitaria con respuesta Th2 e infiltrados nodulares sin úlcera","Baja carga parasitaria con respuesta Th1 exagerada y destrucción mucosa","Carga parasitaria intermedia con úlcera que cura de forma espontánea","Ausencia de parásitos con granulomas bien formados y curación rápida"],"c":0,"exp":"El polo anérgico (cutánea difusa) tiene alta carga parasitaria, predominio Th2 con IL-4 e IL-10 y anergia celular, con infiltrados nodulares no ulcerativos y sin granulomas.","source":"Cuadernillo Núcleo 10 Vectores 2026 (Actividad 4.c) · Compendio ADN (10.f, espectro tegumentario)"},
    {"id":"n10-d-11","nucleo":"10","difficulty":"dificil","topic":"Leishmania spp.","q":"¿Por qué la leishmaniasis mucocutánea destruye tejido aunque haya pocos parásitos en las lesiones?","a":["Por una respuesta Th1 exagerada, con IFN-γ y TNF-α","Por la multiplicación masiva de amastigotes en la mucosa","Por la anergia inmune específica con déficit de Th1","Por la acción directa de los promastigotes metacíclicos inoculados"],"c":0,"exp":"La forma mucocutánea, causada principalmente por L. braziliensis, cursa con respuesta hiperinmune (Th1 exagerada, IFN-γ y TNF-α) que produce destrucción necrotizante granulomatosa pese al pausiparasitismo.","source":"Compendio ADN (10.f, cuadro de manifestaciones) · Cuadernillo Núcleo 10 Vectores 2026 (Actividad 4.b.III)"},
    {"id":"n10-d-12","nucleo":"10","difficulty":"dificil","topic":"Leishmania spp.","q":"¿Qué especies causan la leishmaniasis visceral y qué órganos compromete?","a":["L. donovani y L. infantum/chagasi: bazo, hígado, médula ósea y ganglios","L. braziliensis: tabique nasal, orofaringe y epiglotis","L. mexicana y L. amazonensis: macrófagos cutáneos y subcutáneos","L. guyanensis: macrófagos dérmicos, con úlcera única autolimitada"],"c":0,"exp":"La visceral la causan L. donovani y L. infantum/chagasi, con tropismo por el sistema fagocítico mononuclear (bazo, hígado, médula ósea, ganglios); sin tratamiento es mortal en más del 95 % de los casos (OMS).","source":"Compendio ADN (10.f, cuadro de manifestaciones) · Cuadernillo Núcleo 10 Vectores 2026 (Actividad 4.b.III)"},
    {"id":"n10-d-13","nucleo":"10","difficulty":"dificil","topic":"Trypanosoma cruzi","q":"Un hombre de un barrio de Santiago del Estero refiere disnea de esfuerzo, palpitaciones y edema de tobillos de meses de evolución. ¿Qué forma de Chagas corresponde?","a":["La crónica determinada, con cardiopatía chagásica","La aguda, con miocarditis difusa y alta parasitemia","La crónica indeterminada, asintomática y con anatomía normal","La congénita reactivada, con hepatoesplenomegalia"],"c":0,"exp":"La forma crónica determinada (más de 10 años, 30-40% de los infectados) da cardiopatía por inflamación, miocitólisis y fibrosis del miocardio y del sistema excitoconductor, con arritmias y tromboembolismo.","source":"Cuadernillo Núcleo 10 Vectores 2026 (Actividad 4, casos clínicos, Caso 3) · Compendio ADN (10.g, tropismo y fases)"},
    {"id":"n10-d-14","nucleo":"10","difficulty":"dificil","topic":"Trypanosoma cruzi","q":"¿Qué caracteriza a la fase crónica indeterminada de la enfermedad de Chagas-Mazza?","a":["Baja parasitemia con títulos altos de anticuerpos y anatomía normal","Alta parasitemia con tripomastigotes abundantes en sangre y linfa","Megaformaciones digestivas por denervación del esófago y el colon","Fibrosis del sistema excitoconductor con arritmias y tromboembolismo"],"c":0,"exp":"El 60-70 % de los infectados permanece en la forma indeterminada, asintomática: baja parasitemia, títulos elevados de anticuerpos y anatomía normal. Evoluciona 1-2 % por año a formas determinadas.","source":"Compendio ADN (10.g, evolución de las formas) · Cuadernillo Núcleo 10 Vectores 2026 (Actividad 5)"},
    {"id":"n10-d-15","nucleo":"10","difficulty":"dificil","topic":"Prevención","q":"Dentro de las medidas de control del Chagas, ¿cuál corresponde a la prevención secundaria?","a":["Detectar y tratar a tiempo la infección en embarazadas y recién nacidos","Rociar las viviendas con insecticidas y mejorar la vivienda","Colocar marcapasos en la cardiopatía chagásica establecida","Dar educación sanitaria para la participación comunitaria y la vigilancia"],"c":0,"exp":"La prevención secundaria busca detectar y tratar temprano: control de embarazadas y recién nacidos (sangre de cordón y serología a los 10 meses). El control vectorial es primaria y el manejo de la cardiopatía, terciaria.","source":"Compendio ADN (10.g, medidas de control) · Cuadernillo Núcleo 10 Vectores 2026 (Actividad 4, casos clínicos)"},
    {"id":"n11-f-01","nucleo":"11","difficulty":"facil","topic":"Zoonosis (concepto)","q":"Según la cátedra, ¿qué es una zoonosis?","a":["Una enfermedad transmisible entre animales vertebrados y el ser humano","Una infección que se transmite sólo por la picadura de un artrópodo vector","Una infección que el paciente adquiere durante una internación","Una enfermedad que pasa de la madre al feto durante el embarazo"],"c":0,"exp":"Las zoonosis son las enfermedades e infecciones transmisibles entre animales vertebrados y el ser humano, de manera directa o a través del ambiente. De los 1.415 patógenos humanos conocidos, el 61% es zoonótico.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Introducción) · Compendio ADN (11, introducción)"},
    {"id":"n11-f-02","nucleo":"11","difficulty":"facil","topic":"Una Salud","q":"¿A qué se refiere el concepto de Una Salud?","a":["A la conexión entre la salud humana, la animal y la del ambiente","A la cobertura universal de salud para toda la población","A unificar los calendarios de vacunación humana y veterinaria","A tratar a todos los convivientes de un caso confirmado de zoonosis"],"c":0,"exp":"Una Salud reconoce que la salud humana, la animal y la ambiental están conectadas y que el bienestar de cada componente afecta a los otros; por eso las zoonosis se abordan de manera conjunta y multidisciplinaria.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 1) · Compendio ADN (11.e)"},
    {"id":"n11-f-03","nucleo":"11","difficulty":"facil","topic":"Virus de la rabia (Lyssavirus)","q":"¿Cuál es el agente causal de la rabia humana?","a":["El virus de la rabia, género Lyssavirus, familia Rhabdoviridae","Un arenavirus de la familia Arenaviridae, igual que el virus Junín","Un hantavirus de la familia Bunyaviridae, eliminado por roedores","Una espiroqueta del género Leptospira"],"c":0,"exp":"La rabia humana la produce el virus de la rabia, de la familia Rhabdoviridae, género Lyssavirus. Es un virus con envoltura y neurotropismo marcado.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 3) · Compendio ADN (11.a)"},
    {"id":"n11-f-04","nucleo":"11","difficulty":"facil","topic":"Virus Junín (fiebre hemorrágica argentina)","q":"¿Cuál es el reservorio principal del virus Junín, agente de la fiebre hemorrágica argentina?","a":["Calomys musculinus, el ratón maicero","El perro doméstico sin vacunar","Los murciélagos insectívoros","Las aves psitácidas, como loros y cotorras"],"c":0,"exp":"El reservorio principal es Calomys musculinus (ratón maicero); en menor proporción participan Calomys laucha, Akodon azarae y Mus musculus. El virus se elimina con la orina y la saliva de roedores persistentemente infectados.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (cuadro ENO, Actividad 4) · Compendio ADN (11.b)"},
    {"id":"n11-f-05","nucleo":"11","difficulty":"facil","topic":"Hantavirus","q":"¿Cuál es el principal mecanismo de transmisión de los hantavirus al ser humano?","a":["La inhalación de aerosoles de excretas de roedores infectados","La picadura de mosquitos del género Aedes","La ingestión de carne de cerdo mal cocida","El contacto de la piel sana con el agua de red durante el baño diario"],"c":0,"exp":"El virus es eliminado por los roedores infectados en sangre, secreciones y excretas, y se transmite sobre todo por inhalación de aerosoles. También puede haber contagio por contacto con excrementos o secreciones y, raramente, por mordedura del roedor.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (cuadro ENO) · Compendio ADN (11.b)"},
    {"id":"n11-f-06","nucleo":"11","difficulty":"facil","topic":"Leptospira interrogans","q":"¿Cómo se infectan habitualmente las personas con Leptospira?","a":["Por contacto de mucosas o piel lesionada con agua o barro con orina animal","Por inhalar el polvo de excrementos secos de aves enjauladas o de gallineros","Por consumir quesos elaborados con leche sin pasteurizar","Por la mordedura de un perro no vacunado"],"c":0,"exp":"Las personas son hospedadores accidentales y se infectan por contacto directo con orina de animales infectados o indirecto a través de suelo, agua o materiales contaminados, a través de mucosas o piel lesionada.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (cuadro ENO, Leptospirosis) · Compendio ADN (11.g)"},
    {"id":"n11-f-07","nucleo":"11","difficulty":"facil","topic":"Chlamydophila psittaci","q":"¿Cuál es el reservorio principal de Chlamydophila psittaci?","a":["Las aves psitácidas: loros, cotorras y guacamayos","Los roedores silvestres de los géneros Oligoryzomys y Calomys","El ganado caprino y ovino","Los perros y gatos callejeros"],"c":0,"exp":"El reservorio son las aves psitácidas (loros, cotorras, guacamayos); menos frecuente es el contagio desde palomas y aves de corral. Los grupos de riesgo incluyen veterinarios, cuidadores de zoológico y trabajadores de plantas avícolas.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (cuadro ENO, Actividad 5) · Compendio ADN (11.h)"},
    {"id":"n11-f-08","nucleo":"11","difficulty":"facil","topic":"Brucella spp.","q":"Además del contacto con tejidos de animales infectados, ¿cuál es la otra vía clásica de transmisión de la brucelosis?","a":["La ingestión de alimentos no pasteurizados","La picadura de flebótomos infectados","La inhalación de aerosoles de orina de roedor","La ingestión de huevos del parásito en verduras mal lavadas"],"c":0,"exp":"La brucelosis se adquiere por contacto de piel o mucosas con tejidos de animales infectados y por ingestión de alimentos no pasteurizados; también por inhalación. Los grupos de riesgo son quienes consumen lácteos crudos, trabajan con animales o en laboratorio.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (cuadro ENO, Actividad 5) · Compendio ADN (11.f)"},
    {"id":"n11-f-09","nucleo":"11","difficulty":"facil","topic":"Echinococcus granulosus","q":"En el ciclo de Echinococcus granulosus, ¿cuál es el hospedador definitivo?","a":["El perro","La oveja","El cerdo","El ser humano"],"c":0,"exp":"El adulto de E. granulosus vive fijo a la mucosa del intestino delgado del perro, el hospedador definitivo. Ovinos, bovinos, caprinos y porcinos son intermediarios y el ser humano es un intermediario accidental.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (cuadro ENO, Actividad 3) · Compendio ADN (11.d)"},
    {"id":"n11-f-10","nucleo":"11","difficulty":"facil","topic":"Trichinella spiralis","q":"¿Cómo adquiere el ser humano la triquinosis?","a":["Al comer carne cruda o mal cocida de cerdo o de animales de caza","Al ingerir huevos del parásito presentes en el pelaje del perro o en el suelo","Al inhalar aerosoles de excretas de roedores silvestres","Al tomar leche de vaca sin pasteurizar"],"c":0,"exp":"La infección se produce al ingerir carne cruda o poco cocida con larvas musculares, sobre todo de cerdo, jabalí, oso o caballo. En Argentina pesan la faena domiciliaria y los chacinados caseros o de circuitos informales.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 2, laboratorio) · Compendio ADN (11.d)"},
    {"id":"n11-n-01","nucleo":"11","difficulty":"normal","topic":"Virus de la rabia (Lyssavirus)","q":"¿Cómo es el genoma del virus de la rabia?","a":["ARN monocatenario no segmentado de polaridad negativa, con cinco proteínas","ARN monocatenario de polaridad negativa, segmentado en ocho fragmentos distintos","ADN bicatenario circular que se replica en el núcleo","ARN bicatenario segmentado, en un virus sin envoltura"],"c":0,"exp":"El genoma es una única molécula de ARN no segmentado de polaridad negativa que codifica cinco proteínas: N, P, M, G y L. El genoma segmentado en ocho fragmentos corresponde a los virus influenza.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 3.a) · Compendio ADN (11.a)"},
    {"id":"n11-n-02","nucleo":"11","difficulty":"normal","topic":"Virus de la rabia (Lyssavirus)","q":"¿Qué explica el neurotropismo del virus de la rabia?","a":["Que su proteína G interactúa con el receptor nicotínico de acetilcolina y gangliósidos","Que su neuraminidasa se une al ácido siálico del epitelio respiratorio","Que su proteína N se une al receptor CD4 de los linfocitos T","Que el lipopolisacárido de su pared se adhiere al endotelio de los vasos sanguíneos"],"c":0,"exp":"La proteína G interactúa con receptores como el nicotínico de acetilcolina y gangliósidos: el virus penetra en las terminales nerviosas o se replica en el músculo antes de ascender al sistema nervioso central.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 3.a) · Compendio ADN (11.a)"},
    {"id":"n11-n-03","nucleo":"11","difficulty":"normal","topic":"Virus de la rabia (Lyssavirus)","q":"¿Cuál es el mecanismo de transmisión más frecuente de la rabia al ser humano?","a":["La inoculación de saliva infectada por mordedura o en una herida preexistente","La inhalación de aerosoles en cuevas con grandes colonias de murciélagos hematófagos","El trasplante de córnea de un donante infectado","El contacto de saliva del animal con piel sana"],"c":0,"exp":"La transmisión principal es la inoculación de saliva infectada por mordedura o herida preexistente, y también a través de mucosas. Los aerosoles y el trasplante de córnea son excepcionales; la saliva sobre piel sana es un accidente no significativo.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 3.c) · Compendio ADN (11.a)"},
    {"id":"n11-n-04","nucleo":"11","difficulty":"normal","topic":"Virus de la rabia (Lyssavirus)","q":"Ante un accidente potencialmente rábico, ¿cuál es la primera medida sobre la herida?","a":["Lavarla a chorro con agua y jabón lo antes posible","Suturarla de inmediato con la mayor cantidad de puntos","Infiltrar la vacuna antirrábica alrededor de la herida","Esperar los diez días de observación del animal agresor"],"c":0,"exp":"Primero el lavado inmediato y a chorro con agua y jabón: el agua arrastra el virus y el jabón altera su capa lipídica. Después se usan antisépticos, se infiltra el suero antirrábico en la herida y se aplica la vacuna.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 3.f) · Compendio ADN (11.a)"},
    {"id":"n11-n-05","nucleo":"11","difficulty":"normal","topic":"Virus de la rabia (Lyssavirus)","q":"¿Qué estudios permiten confirmar una rabia humana en vida del paciente?","a":["Inmunofluorescencia directa en saliva o piel de nuca, y RT-PCR","Hemocultivos seriados incubados durante dos semanas y serología pareada","Cultivo en medios con vitaminas B2 y B12 a 28-30 °C","Hemaglutinación indirecta en líquido del quiste"],"c":0,"exp":"El diagnóstico antemortem se basa en la detección de antígeno rábico por inmunofluorescencia directa en saliva o biopsia de piel de nuca; también se usa RT-PCR en saliva, LCR o tejidos y ELISA para anticuerpos.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 3.e y 3.g) · Compendio ADN (11.a)"},
    {"id":"n11-n-06","nucleo":"11","difficulty":"normal","topic":"Virus Junín (fiebre hemorrágica argentina)","q":"¿Cómo ingresa el virus Junín al organismo de los trabajadores rurales de la pampa húmeda?","a":["Por vía cutáneo-mucosa: escoriaciones de la piel o inhalación de aerosoles","Por la picadura de la hembra de los flebótomos infectados durante la cosecha","Por ingestión de agua con huevos del parásito","Por mordedura directa del roedor reservorio"],"c":0,"exp":"El virus Junín penetra por vía cutáneo-mucosa, a través de escoriaciones frecuentes en trabajadores rurales o por mucosa conjuntival, oral o nasal al inhalar aerosoles contaminados que se producen durante la cosecha. La incubación es de 6 a 14 días.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 4) · Compendio ADN (11.b)"},
    {"id":"n11-n-07","nucleo":"11","difficulty":"normal","topic":"Virus Junín (fiebre hemorrágica argentina)","q":"¿En qué consiste el tratamiento específico de la fiebre hemorrágica argentina?","a":["En administrar plasma inmune de convalecientes, con anticuerpos anti-virus Junín","En aplicar la vacuna Candid#1 en cuanto se sospecha el caso","En administrar corticoides en altas dosis durante la fase hemorrágica-neurológica","En dar antibióticos por vía parenteral durante dos semanas"],"c":0,"exp":"El tratamiento específico es la administración de anticuerpos anti-virus Junín obtenidos de plasma inmune de personas convalecientes de FHA. Sin tratamiento específico, la mortalidad de la fase hemorrágica-neurológica es alta.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 4) · Compendio ADN (11.b)"},
    {"id":"n11-n-08","nucleo":"11","difficulty":"normal","topic":"Prevención","q":"Entre las zoonosis de este núcleo, ¿cuál cuenta con vacuna para uso humano?","a":["La fiebre hemorrágica argentina, con la vacuna Candid#1","La leptospirosis, con una vacuna indicada a trabajadores rurales","La brucelosis, con la misma vacuna que se aplica al ganado","El síndrome pulmonar por hantavirus, con una vacuna a virus inactivado"],"c":0,"exp":"Candid#1 se aplica a quienes residen o trabajan en el área endémica de FHA. No hay vacuna humana para hantavirosis, leptospirosis, brucelosis, psitacosis ni triquinosis; en leptospirosis y brucelosis sí existen vacunas veterinarias.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividades 2, 4 y 5) · Compendio ADN (11.b, 11.f, 11.g, 11.h)"},
    {"id":"n11-n-09","nucleo":"11","difficulty":"normal","topic":"Hantavirus","q":"¿A qué familia pertenecen los hantavirus y cómo evoluciona el síndrome pulmonar por hantavirus?","a":["Bunyaviridae; en cuatro fases: febril o prodrómica, cardiopulmonar, diurética y de convalecencia","Arenaviridae; en dos fases: prodrómica y hemorrágica-neurológica","Orthomyxoviridae; en una única fase febril autolimitada","Rhabdoviridae; en tres fases: prodrómica, de excitación y paralítica"],"c":0,"exp":"Los hantavirus son Bunyaviridae con ARN monocatenario negativo y envoltura. El SPH evoluciona en cuatro fases: prodrómica (3-5 días, fiebre y mialgias), cardiopulmonar, diurética y de convalecencia. La incubación va de 4 a 42 días. La cátedra los ubica en Bunyaviridae; en la clasificación actual del ICTV integran la familia Hantaviridae (orden Bunyavirales).","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 4) · Compendio ADN (11.b)"},
    {"id":"n11-n-10","nucleo":"11","difficulty":"normal","topic":"Hantavirus","q":"Entre las zoonosis por roedores de este núcleo, ¿en cuál se demostró transmisión de persona a persona?","a":["El virus Andes","El virus Junín","El virus de la rabia","La influenza aviar H5N1"],"c":0,"exp":"Entre las zoonosis por roedores, la transmisión persona a persona sólo se demostró para el virus Andes; en la FHA no ocurre. Para H5N1 no hay, hasta el momento, evidencia de propagación entre humanos.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (cuadro ENO, Actividades 4 y 5) · Compendio ADN (11.b)"},
    {"id":"n11-n-11","nucleo":"11","difficulty":"normal","topic":"Hantavirus","q":"¿Cuál es el ensayo de elección para el diagnóstico de hantavirosis?","a":["La detección de anticuerpos IgM por ELISA","El aislamiento del virus en cultivo celular","La inmunofluorescencia directa en biopsia de piel de nuca","La hemaglutinación indirecta en líquido pleural"],"c":0,"exp":"El ELISA para IgM es el ensayo de elección. La RT-PCR permite detectar ARN viral en sangre entera, coágulo o tejidos obtenidos en los primeros 10 días de enfermedad.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 4.c) · Compendio ADN (11.b)"},
    {"id":"n11-n-12","nucleo":"11","difficulty":"normal","topic":"Virus de la influenza","q":"¿Qué característica del genoma de influenza A le permite el salto de especie y dar pandemias?","a":["Está segmentado en ocho fragmentos de ARN, lo que permite el reordenamiento","Es un ARN no segmentado que sólo acumula mutaciones puntuales en la hemaglutinina","Es un ADN bicatenario que se integra al genoma de la célula","Es un ARN de polaridad positiva que actúa como ARN mensajero"],"c":0,"exp":"El genoma es ARN monocatenario negativo segmentado en ocho fragmentos: cuando dos cepas coinfectan una célula puede haber reordenamiento (shift) y surgir combinaciones nuevas de HA y NA frente a las que la población no tiene inmunidad.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 5.1) · Compendio ADN (11.c)"},
    {"id":"n11-n-13","nucleo":"11","difficulty":"normal","topic":"Virus de la influenza","q":"¿Por qué el cerdo es clave en la ecología zoonótica de la influenza A?","a":["Porque se infecta con cepas aviares y humanas y favorece los virus híbridos","Porque es el reservorio natural del virus en todo el mundo","Porque elimina el virus por la orina y contamina el agua de bebida","Porque es el único mamífero en el que el virus se replica en el núcleo celular"],"c":0,"exp":"Las aves acuáticas son el reservorio natural y el cerdo es hospedador intermediario: puede infectarse con cepas aviares y humanas, y esa mezcla de genes facilita la aparición de virus híbridos capaces de adaptarse al hombre.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 5.2) · Compendio ADN (11.c)"},
    {"id":"n11-n-14","nucleo":"11","difficulty":"normal","topic":"Toxocara canis","q":"¿Cuál es la forma infectante de Toxocara canis para el ser humano y cómo se adquiere?","a":["El huevo larvado del suelo, ingerido por manos, alimentos o pelaje del perro","La larva L1 presente en la carne de cerdo o de jabalí cruda o mal cocida","El protoescólex liberado al romperse un quiste","La larva que penetra activamente la piel descalza"],"c":0,"exp":"El huevo eliminado con las heces del perro se vuelve larvado (L2) en el suelo en 2-3 semanas y sobrevive meses. Se ingiere por manos contaminadas, suelo, agua, alimentos o pelaje de la mascota; el grupo de riesgo son niños con geofagia u onicofagia.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 4, laboratorio) · Compendio ADN (caso 6, Toxocara canis)"},
    {"id":"n11-n-15","nucleo":"11","difficulty":"normal","topic":"Trichinella spiralis","q":"¿Cuál es la forma infectante de Trichinella spiralis y qué tipo de ciclo tiene?","a":["La larva muscular L1; ciclo directo, con dos generaciones en el mismo hospedador","El huevo larvado del suelo; ciclo indirecto, con un hospedador intermediario","El quiste con vesículas hijas; ciclo indirecto entre perro y herbívoros","El cisticerco de la carne de vaca; ciclo con el humano como único definitivo"],"c":0,"exp":"La forma infectante es la larva muscular L1 presente en la carne. El ciclo es directo: no necesita hospedador intermediario y en el mismo hospedador se desarrollan dos generaciones, adultos en el intestino y larvas en el músculo estriado.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividades 1 y 2, laboratorio) · Compendio ADN (11.d; 7.a.e)"},
    {"id":"n11-n-16","nucleo":"11","difficulty":"normal","topic":"Trichinella spiralis","q":"¿Cuáles son las manifestaciones principales de la etapa de invasión muscular de la triquinosis?","a":["Fiebre, edema palpebral y mialgias","Ictericia, hepatomegalia y hemorragias en piel y mucosas","Tos, hemoptisis, dolor torácico y disnea de esfuerzo","Hidrofobia, espasmos musculares generalizados y fonofobia"],"c":0,"exp":"Las manifestaciones principales son fiebre, edema de párpados y periocular, y dolor muscular, con eosinofilia y leucocitosis. Antes puede haber una etapa intestinal con diarrea, dolor abdominal y vómitos.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 2, laboratorio) · Compendio ADN (11.d; 7.a.e)"},
    {"id":"n11-n-17","nucleo":"11","difficulty":"normal","topic":"Echinococcus granulosus","q":"¿Qué forma de Echinococcus granulosus infecta al ser humano y dónde se localiza con más frecuencia el quiste?","a":["El huevo con embrión hexacanto u oncosfera; en el hígado, en el 60-70% de los casos","La larva muscular L1; en los músculos estriados, sobre todo del diafragma","El protoescólex del quiste fértil; en el intestino delgado","El cisticerco presente en la carne; en el sistema nervioso central"],"c":0,"exp":"El humano ingiere accidentalmente huevos con oncosfera o embrión hexacanto; estos penetran la mucosa intestinal, pasan a la circulación portal y forman el quiste hidatídico, sobre todo en hígado (60-70%) y en segundo lugar en pulmón.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 3, laboratorio) · Compendio ADN (11.d; 7.a.g)"},
    {"id":"n11-n-18","nucleo":"11","difficulty":"normal","topic":"Brucella spp.","q":"¿Cómo son las bacterias del género Brucella?","a":["Cocobacilos gramnegativos pequeños, inmóviles y de crecimiento lento","Espiroquetas finas y enroscadas, con un gancho en uno o ambos extremos","Bacilos grampositivos esporulados y aerobios","Bacterias intracelulares obligadas con cuerpos elementales y reticulados"],"c":0,"exp":"Brucella es un cocobacilo gramnegativo pequeño, inmóvil y no encapsulado, aerobio estricto y de crecimiento lento (una semana o más): los hemocultivos se incuban dos semanas antes de informarse negativos.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 5.1) · Compendio ADN (11.f)"},
    {"id":"n11-n-19","nucleo":"11","difficulty":"normal","topic":"Leptospira interrogans","q":"¿Qué característica de Leptospira explica que atraviese mucosas intactas o pequeñas abrasiones de la piel?","a":["Que es una espiroqueta fina y muy móvil, con flagelos periplásmicos","Que forma esporas resistentes a la desecación","Que produce una exotoxina que lisa el epitelio","Que es un parásito intracelular obligado del sistema reticuloendotelial"],"c":0,"exp":"Las leptospiras son espiroquetas finas y enroscadas, con un gancho en los extremos y dos flagelos periplásmicos que les dan movilidad: por eso penetran mucosas intactas o piel con cortes y se diseminan por sangre a todos los tejidos.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 5.6) · Compendio ADN (11.g)"},
    {"id":"n11-n-20","nucleo":"11","difficulty":"normal","topic":"Chlamydophila psittaci","q":"¿Cómo se transmite la psitacosis y qué forma del agente es la infectante?","a":["Por inhalación de excrementos secos o secreciones de aves; el cuerpo elemental","Por mordedura del ave infectada; el cuerpo reticulado","Por ingestión de huevos presentes en el plumaje; la oncosfera hexacanto","Por contacto de la piel con agua con orina de ave; el cuerpo reticulado"],"c":0,"exp":"C. psittaci ingresa por el aparato respiratorio al inhalar excrementos secos, orina o secreciones de aves. El cuerpo elemental es la forma infectante, metabólicamente inactiva y resistente al ambiente; el reticulado es el que se multiplica.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 5, Psitacosis) · Compendio ADN (11.h)"},
    {"id":"n11-d-01","nucleo":"11","difficulty":"dificil","topic":"Virus Junín (fiebre hemorrágica argentina)","q":"Un paciente con fiebre, cefalea, mareos y dolor ocular durmió en el galpón de una casa quinta donde había problemas con el control de roedores de los campos vecinos. ¿Qué agente sospechás?","a":["Virus Junín (Arenaviridae)","Hantavirus (familia Bunyaviridae)","Leptospira interrogans (leptospirosis)","Chlamydophila psittaci (psitacosis)"],"c":0,"exp":"El síndrome febril con cefalea, mareos y dolor retroorbitario más exposición a roedores en un área posiblemente endémica orienta a fiebre hemorrágica argentina por virus Junín, un arenavirus con envoltura y ARN de cadena simple.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 4, caso 1) · Compendio ADN (11.b)"},
    {"id":"n11-d-02","nucleo":"11","difficulty":"dificil","topic":"Hantavirus","q":"Un trabajador del Parque Nacional Los Alerces ingresa a Esquel por insuficiencia respiratoria grave tras tres días de fiebre y mialgias; a los 7 días su esposa inicia síntomas similares. ¿Qué sospechás?","a":["Síndrome pulmonar por hantavirus, probablemente por virus Andes","Fiebre hemorrágica argentina por virus Junín","Leptospirosis en su forma ictérica o síndrome de Weil","Psitacosis con compromiso pulmonar y del sistema nervioso central"],"c":0,"exp":"La progresión rápida a insuficiencia respiratoria en la región surandina y el contagio a la esposa orientan a SPH: la transmisión interhumana sólo se demostró para el virus Andes. No hay tratamiento específico ni vacuna.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 4, caso 2) · Compendio ADN (11.b)"},
    {"id":"n11-d-03","nucleo":"11","difficulty":"dificil","topic":"Hantavirus","q":"¿Cuál es la diferencia correcta entre reservorios y áreas de riesgo de la FHA y de la hantavirosis en Argentina?","a":["La FHA tiene a Calomys musculinus en la pampa húmeda; el hantavirus, a Oligoryzomys","Ambas comparten el mismo reservorio roedor, pero la FHA sólo aparece en la región surandina","La FHA tiene reservorio en roedores urbanos y la hantavirosis en aves acuáticas","La hantavirosis se limita a Buenos Aires, Córdoba y Santa Fe, y la FHA a la Patagonia"],"c":0,"exp":"El área endémica de FHA es la pampa húmeda (Buenos Aires, Córdoba, Santa Fe y La Pampa), con Calomys musculinus como reservorio principal. El SPH se distribuye en NOA, NEA, Centro y surandina, con roedores del género Oligoryzomys.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 4.b) · Compendio ADN (11.b)"},
    {"id":"n11-d-04","nucleo":"11","difficulty":"dificil","topic":"Trichinella spiralis","q":"Confirmás una triquinosis en un paciente que comió ahumado de jabalí en una reunión familiar. ¿Cuál es la conducta correcta del equipo de salud?","a":["Notificar el caso e investigar a los comensales y el alimento","Aislar al paciente en habitación individual durante diez días","Indicar profilaxis a los convivientes con gammaglobulina específica","Pedir coproparasitológico seriado a toda la familia"],"c":0,"exp":"La triquinosis es un evento de notificación obligatoria: hay que notificar, identificar a los contactos que pudieron comer la misma carne, intervenir sobre el alimento y el establecimiento, tratar al paciente y educar sobre la cocción.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 2, laboratorio, consignas 2 y 3) · Compendio ADN (11.d)"},
    {"id":"n11-d-05","nucleo":"11","difficulty":"dificil","topic":"Diagnóstico de laboratorio","q":"¿Qué hallazgos de laboratorio y qué estudio confirman una sospecha de triquinosis?","a":["Eosinofilia con CPK y LDH elevadas, y ELISA IgG para Trichinella","Leucopenia con plaquetopenia, y RT-PCR en sangre del período agudo","Eosinofilia con anemia ferropénica, y coproparasitológico seriado","Bilirrubina y creatinina elevadas, y hemaglutinación indirecta"],"c":0,"exp":"El hemograma muestra eosinofilia y leucocitosis, con CK y LDH elevadas por el daño muscular. La confirmación es serológica (ELISA IgG, detectable entre 12 y 60 días) y, si hace falta, digestión artificial de músculo.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 2, laboratorio) · Compendio ADN (11.d; 7.a.e)"},
    {"id":"n11-d-06","nucleo":"11","difficulty":"dificil","topic":"Toxocara canis","q":"Un nene de 10 años con perros sin desparasitar tiene disminución de la agudeza visual, granuloma macular en el fondo de ojo y eosinofilia. ¿Qué parásito y qué estadio explican el cuadro?","a":["Toxocara canis; la larva L2 encapsulada en un granuloma","Echinococcus granulosus; el quiste hidatídico con vesículas hijas","Trichinella spiralis; la larva L1 enquistada en el músculo","Taenia solium; el cisticerco en el tejido ocular"],"c":0,"exp":"En la toxocariasis el humano es hospedador accidental: las larvas L2 migran por la circulación sistémica y quedan encapsuladas en granulomas (larva migrans visceral u ocular). El diagnóstico es serológico, no coproparasitológico.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 4, laboratorio) · Compendio ADN (caso 6, Toxocara canis)"},
    {"id":"n11-d-07","nucleo":"11","difficulty":"dificil","topic":"Echinococcus granulosus","q":"¿Por qué no se usa materia fecal como muestra para diagnosticar hidatidosis en el ser humano?","a":["Porque el humano no alberga el parásito adulto y no elimina huevos","Porque los huevos se destruyen al pasar por el intestino humano","Porque los huevos de Echinococcus no se distinguen de los de Taenia","Porque el quiste se calcifica y deja de liberar material al intestino"],"c":0,"exp":"El humano es hospedador intermediario accidental: desarrolla el quiste pero no el adulto intestinal, así que no elimina huevos por heces. El coproparasitológico y el ELISA de coproantígenos sí son útiles en el perro.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 3, laboratorio) · Compendio ADN (11.d; 7.a.g)"},
    {"id":"n11-d-08","nucleo":"11","difficulty":"dificil","topic":"Echinococcus granulosus","q":"¿Con qué método de imagen se busca el quiste hidatídico hepático y en qué regiones del país es endémica la enfermedad?","a":["Ecotomografía; en la Patagonia y sectores de la región Centro","Radiografía simple de abdomen; sólo en las provincias del NOA y el NEA","Resonancia magnética; exclusivamente en la pampa húmeda","Centellograma hepático; sólo en el NEA"],"c":0,"exp":"La ecotomografía muestra el quiste y sus vesículas hijas y es de gran utilidad en el hígado; TC y RM aportan detalle anatómico. Las áreas endémicas son la Patagonia y sectores de Buenos Aires, La Pampa, sur de Santa Fe y Córdoba.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 3, laboratorio) · Compendio ADN (11.d; 7.a.g)"},
    {"id":"n11-d-09","nucleo":"11","difficulty":"dificil","topic":"Brucella spp.","q":"¿Qué resultado serológico se considera diagnóstico de brucelosis?","a":["Un aumento de cuatro veces del título o un único título de 1:160 o mayor","Cualquier título de IgG positivo, por bajo que sea","La detección de IgM, que desaparece en la primera semana","La presencia de IgA en orina durante la convalecencia"],"c":0,"exp":"Los anticuerpos anti-Brucella pueden persistir mucho tiempo, así que el diagnóstico exige un aumento de cuatro veces del título o un único título igual o mayor a 1:160. Puede haber reactividad cruzada con otras bacterias.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 5.2) · Compendio ADN (11.f)"},
    {"id":"n11-d-10","nucleo":"11","difficulty":"dificil","topic":"Respuesta inmune","q":"¿Cómo sobrevive Brucella dentro de los macrófagos que la fagocitan?","a":["Inhibe la fusión fagosoma-lisosoma, suprime el TNF-alfa y produce catalasa","Libera una exotoxina potente que lisa al fagocito desde adentro","Se recubre de una cápsula que impide el reconocimiento por las opsoninas","Escapa al citoplasma gracias a la cadena O rugosa de su lipopolisacárido"],"c":0,"exp":"Brucella es un parásito intracelular del sistema reticuloendotelial: inhibe la fusión fagosoma-lisosoma, suprime el TNF-alfa e inactiva el peróxido de hidrógeno y el superóxido con catalasa y superóxido dismutasa.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 5.1) · Compendio ADN (11.f)"},
    {"id":"n11-d-11","nucleo":"11","difficulty":"dificil","topic":"Chlamydophila psittaci","q":"¿Cómo se manifiesta la psitacosis y cuánto dura su período de incubación?","a":["Fiebre alta, cefalea y tos no productiva, tras 5 a 14 días","Diarrea acuosa y vómitos, tras 24 a 48 horas de incubación","Edema facial y mialgias con eosinofilia, tras 1 a 2 semanas","Ictericia con insuficiencia renal y hemorragias, tras 6 a 14 días"],"c":0,"exp":"Tras 5 a 14 días de incubación aparecen cefalea, fiebre alta, escalofríos, mialgias y tos no productiva con crepitantes y consolidación. Es frecuente el compromiso del sistema nervioso central y puede haber hepatomegalia y esplenomegalia.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 5, Psitacosis) · Compendio ADN (11.h)"},
    {"id":"n11-d-12","nucleo":"11","difficulty":"dificil","topic":"Respuesta inmune","q":"¿Qué es el síndrome de Weil y qué papel tiene la respuesta inmune en la leptospirosis?","a":["Es la forma ictérica grave; parte del daño, como la meningitis y la nefropatía, es inmunológico","Es la forma leve seudogripal; la respuesta inmune no participa del daño","Es una reacción anafiláctica por rotura de un quiste, mediada por IgE","Es la fase convaleciente con eliminación urinaria prolongada de la bacteria"],"c":0,"exp":"El síndrome de Weil es la forma ictérica grave (cerca del 10% de las infecciones sintomáticas), con insuficiencia hepática y renal, vasculitis, miocarditis y mortalidad del 10-15%. La meningitis y la nefropatía por inmunocomplejos son inmunológicas.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 5.7) · Compendio ADN (11.g)"},
    {"id":"n11-d-13","nucleo":"11","difficulty":"dificil","topic":"Virus de la rabia (Lyssavirus)","q":"¿Qué afirmación sobre la profilaxis post-exposición antirrábica es correcta?","a":["Se prefiere el esquema de Zagreb: 4 dosis en 3 visitas, con dos dosis el día 0","El esquema de Essen se reserva para pacientes inmunocomprometidos","El embarazo contraindica la vacunación antirrábica","Las dosis son menores en niños que en adultos"],"c":0,"exp":"Zagreb (día 0 con dos dosis, una en cada brazo, día 7 y día 21) se prefiere porque reduce una visita y el abandono. Essen modificado son 4 dosis en 4 visitas y no se usa en inmunocomprometidos; el embarazo no contraindica la vacuna.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 3.f) · Compendio ADN (11.a)"},
    {"id":"n11-d-14","nucleo":"11","difficulty":"dificil","topic":"Epidemiología argentina","q":"El único caso confirmado de rabia humana desde 2021 fue una mujer mordida por un gato callejero al que había contagiado un murciélago. ¿Qué muestra este caso?","a":["Un spillover: la vigilancia animal sigue siendo clave aunque no haya casos humanos","Que el ciclo doméstico canino es hoy la principal fuente de rabia humana","Que la profilaxis post-exposición perdió eficacia frente a variantes de murciélago","Que la rabia dejó de ser un problema de salud pública en el país"],"c":0,"exp":"El caso (Buenos Aires, 2021) es un ejemplo de spillover: un murciélago Tadarida brasiliensis contagió al gato y este a la mujer, que no consultó ni recibió PPE. La ausencia de casos humanos no implica ausencia de circulación viral.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 3, BEN N.º 799 SE 9 2026)"},
    {"id":"n11-d-15","nucleo":"11","difficulty":"dificil","topic":"Epidemiología argentina","q":"¿Por qué la triquinosis y la hantavirosis tienen estacionalidades opuestas en Argentina?","a":["La triquinosis sube en los meses fríos y la hantavirosis, en los cálidos","Las dos suben en invierno, cuando los roedores se refugian en las viviendas","La triquinosis sube en verano por el consumo de carne al aire libre","La hantavirosis sube en invierno porque el virus resiste mejor el frío"],"c":0,"exp":"La triquinosis se concentra en los meses fríos, asociada a la faena domiciliaria de cerdos y animales silvestres y a chacinados caseros o de circuitos informales; la hantavirosis concentra sus casos en los meses cálidos.","source":"Cuadernillo Núcleo 11 Zoonosis 2026 (Actividad 2.b del seminario y Actividad 2 del laboratorio)"},
    {"id":"n12-f-01","nucleo":"12","difficulty":"facil","topic":"Staphylococcus aureus","q":"¿Cómo se describe la morfología y la tinción de Gram de Staphylococcus aureus?","a":["Coco grampositivo agrupado en racimos","Coco grampositivo agrupado en cadenas","Bacilo grampositivo esporulado","Bacilo ácido alcohol resistente"],"c":0,"exp":"S. aureus es un coco grampositivo en racimos, de la familia Staphylococcaceae; las cadenas corresponden a Streptococcus.","source":"Cuadernillo Núcleo 12 Seminario 2026 (cuadro de agentes) · Compendio ADN (12.2.b)"},
    {"id":"n12-f-02","nucleo":"12","difficulty":"facil","topic":"Streptococcus pyogenes","q":"¿Qué patrón de hemólisis en agar sangre y qué grupo de Lancefield corresponden a Streptococcus pyogenes?","a":["Beta hemólisis, grupo A","Alfa hemólisis, grupo A","Beta hemólisis estrecha, grupo B","Alfa hemólisis, sin grupo de Lancefield"],"c":0,"exp":"S. pyogenes es beta hemolítico del grupo A; S. agalactiae es beta estrecha grupo B y S. pneumoniae es alfa hemolítico.","source":"Cuadernillo Núcleo 12 Laboratorio 2026 (cuadro de Streptococcus) · Compendio ADN (12.2.a)"},
    {"id":"n12-f-03","nucleo":"12","difficulty":"facil","topic":"Clostridium tetani","q":"¿Cuál es la vía de transmisión de Clostridium tetani?","a":["Herida contaminada con esporas del suelo","Gotitas respiratorias de persona a persona","Picadura de un artrópodo vector","Ingesta de carne mal refrigerada"],"c":0,"exp":"El tétanos se adquiere por heridas contaminadas con esporas presentes en la mayoría de los suelos; en el recién nacido, la puerta de entrada es el muñón umbilical.","source":"Cuadernillo Núcleo 12 Seminario 2026 (Actividad 3) · Compendio ADN (12.2.b Clostridium tetani)"},
    {"id":"n12-f-04","nucleo":"12","difficulty":"facil","topic":"Clostridium perfringens","q":"¿Dónde se encuentra habitualmente Clostridium perfringens?","a":["En la tierra, el agua y el tracto intestinal","Solo en las fosas nasales humanas","En suelos arenosos de playas tropicales","En el excremento de murciélagos"],"c":0,"exp":"C. perfringens es ubicuo: está en tierra, agua y tracto intestinal, y llega a los tejidos blandos por contaminación de heridas y traumatismos.","source":"Cuadernillo Núcleo 12 Seminario 2026 (Actividad 3) · Compendio ADN (12.2.b Clostridium perfringens)"},
    {"id":"n12-f-05","nucleo":"12","difficulty":"facil","topic":"Mycobacterium leprae","q":"¿Qué característica de tinción define a Mycobacterium leprae?","a":["Bacilo ácido alcohol resistente","Coco grampositivo en racimos","Bacilo gramnegativo curvo","Bacilo grampositivo esporulado"],"c":0,"exp":"M. leprae es un bacilo débilmente grampositivo y fuertemente ácido alcohol resistente (BAAR), con pared rica en lípidos.","source":"Cuadernillo Núcleo 12 Seminario 2026 (cuadro de agentes) · Compendio ADN (12.2.c)"},
    {"id":"n12-f-06","nucleo":"12","difficulty":"facil","topic":"Sarcoptes scabiei","q":"¿Qué agente produce la escabiosis o sarna?","a":["Sarcoptes scabiei","Pediculus humanus capitis","Tunga penetrans","Dermatobia hominis"],"c":0,"exp":"La escabiosis la produce el ácaro Sarcoptes scabiei variedad hominis, que cava túneles en el estrato córneo de la epidermis.","source":"Cuadernillo Núcleo 12 Laboratorio 2026 (TP 25) · Compendio ADN (12.3.a)"},
    {"id":"n12-f-07","nucleo":"12","difficulty":"facil","topic":"Ancylostoma braziliense / caninum","q":"¿Cómo adquiere una persona la larva migrans cutánea?","a":["Por larvas que penetran la piel desde el suelo","Por ingesta de huevos en agua contaminada","Por contacto directo piel a piel con un enfermo","Por picadura de una mosca hematófaga"],"c":0,"exp":"Las larvas filariformes de Ancylostoma de perros y gatos están en la arena o el suelo húmedo y penetran la piel, con frecuencia en pies descalzos.","source":"Cuadernillo Núcleo 12 Laboratorio 2026 (TP 25, Actividad 1) · Compendio ADN (12.3.e)"},
    {"id":"n12-f-08","nucleo":"12","difficulty":"facil","topic":"Dermatofitos","q":"¿Qué tejidos afectan los hongos dermatofitos?","a":["Piel y faneras (pelos y uñas)","Tejido celular subcutáneo profundo","Pulmón y sistema nervioso central","Endotelio vascular y médula ósea"],"c":0,"exp":"Los dermatofitos son queratinofílicos: invaden la queratina de piel, pelo y uñas, sin llegar a los tejidos profundos.","source":"Cuadernillo Núcleo 12 Seminario 2026 (micosis superficiales) · Compendio ADN (12.6.a)"},
    {"id":"n12-f-09","nucleo":"12","difficulty":"facil","topic":"Respuesta inmune","q":"¿Qué célula de la epidermis capta antígenos y los presenta a los linfocitos en los ganglios linfáticos?","a":["La célula de Langerhans","El melanocito","La célula de Merkel","El queratinocito basal"],"c":0,"exp":"Las células de Langerhans son las dendríticas de la epidermis: captan, procesan y presentan antígenos para iniciar la respuesta adaptativa.","source":"Cuadernillo Núcleo 12 Seminario 2026 (Actividad 1) · Compendio ADN (12.1)"},
    {"id":"n12-f-10","nucleo":"12","difficulty":"facil","topic":"Prevención","q":"¿Contra qué agentes protege la vacuna triple viral del calendario argentino?","a":["Sarampión, rubéola y paperas","Sarampión, rubéola y varicela","Sarampión, parvovirus B19 y paperas","Rubéola, paperas y herpes zóster"],"c":0,"exp":"La triple viral cubre sarampión, rubéola/síndrome de rubéola congénita y paperas; se aplica a los 12 meses y a los 5 años.","source":"Compendio ADN (12.5.a y 12.5.b, calendario nacional)"},
    {"id":"n12-n-01","nucleo":"12","difficulty":"normal","topic":"Staphylococcus aureus","q":"¿Cuál es el mecanismo de acción de la proteína A de Staphylococcus aureus?","a":["Se une al Fc de las inmunoglobulinas e impide la opsonización","Convierte el fibrinógeno en fibrina formando un coágulo protector","Separa las capas superficiales de la epidermis","Estimula la proliferación de linfocitos T como superantígeno"],"c":0,"exp":"La proteína A es un factor de superficie que une el fragmento Fc de la IgG y bloquea la eliminación mediada por anticuerpos.","source":"Cuadernillo Núcleo 12 Seminario 2026 (Actividad 2.b) · Compendio ADN (12.2.b)"},
    {"id":"n12-n-02","nucleo":"12","difficulty":"normal","topic":"Staphylococcus aureus","q":"¿Qué toxinas de Staphylococcus aureus producen el síndrome de la piel escaldada?","a":["Las toxinas exfoliativas","Las enterotoxinas A-R","La toxina del síndrome del shock tóxico-1","La coagulasa"],"c":0,"exp":"Las toxinas exfoliativas ETA/ETB rompen los puentes intercelulares del estrato granuloso y causan el síndrome de la piel escaldada o enfermedad de Ritter.","source":"Cuadernillo Núcleo 12 Seminario 2026 (Actividad 2.b) · Compendio ADN (12.2.b)"},
    {"id":"n12-n-03","nucleo":"12","difficulty":"normal","topic":"Streptococcus pyogenes","q":"¿Qué factor de virulencia de Streptococcus pyogenes inactiva un quimioatrayente de neutrófilos?","a":["La peptidasa de C5a","La estreptoquinasa","La hialuronidasa","La estreptolisina S"],"c":0,"exp":"La peptidasa de C5a inactiva el C5a y evita el reclutamiento temprano de neutrófilos; las otras degradan tejidos o lisan células.","source":"Cuadernillo Núcleo 12 Seminario 2026 (Actividad 2.c) · Compendio ADN (12.2.a)"},
    {"id":"n12-n-04","nucleo":"12","difficulty":"normal","topic":"Streptococcus pyogenes","q":"¿Qué función cumplen las exotoxinas pirógenas estreptocócicas como SpeA y SpeC?","a":["Actúan como superantígenos y liberan citocinas proinflamatorias","Degradan el ácido hialurónico y facilitan el pasaje por los tejidos","Lisan eritrocitos, leucocitos y plaquetas","Bloquean la unión de C3b a la pared bacteriana"],"c":0,"exp":"SpeA y SpeC actúan como superantígenos que estimulan macrófagos y linfocitos T cooperadores (escarlatina, shock tóxico, fascitis necrosante); SpeB es además una proteasa que degrada tejido.","source":"Cuadernillo Núcleo 12 Seminario 2026 (Actividad 2.c) · Compendio ADN (12.2.a)"},
    {"id":"n12-n-05","nucleo":"12","difficulty":"normal","topic":"Streptococcus pyogenes","q":"Dentro de las infecciones por Streptococcus pyogenes, ¿cómo se clasifican la fiebre reumática y la glomerulonefritis aguda?","a":["Complicaciones no supurativas","Infecciones supurativas profundas","Cuadros mediados por toxinas","Infecciones localizadas superficiales"],"c":0,"exp":"Son complicaciones posestreptocócicas no supurativas, mediadas por la respuesta inmune (reacción cruzada y depósito de complejos inmunes).","source":"Cuadernillo Núcleo 12 Seminario 2026 (Actividad 2.c.2) · Compendio ADN (12.2.a)"},
    {"id":"n12-n-06","nucleo":"12","difficulty":"normal","topic":"Clostridium perfringens","q":"¿Cuál es la toxina más importante de Clostridium perfringens y qué actividad tiene?","a":["La toxina alfa, una lecitinasa que lisa eritrocitos y endotelio","La tetanospasmina, que bloquea la liberación de neurotransmisores inhibidores","Una enterotoxina termoestable que produce vómitos precoces","Una toxina exfoliativa que separa el estrato granuloso"],"c":0,"exp":"La toxina alfa es una lecitinasa (fosfolipasa C) responsable del daño tisular de la mionecrosis o gangrena gaseosa.","source":"Cuadernillo Núcleo 12 Seminario 2026 (Actividad 3) · Compendio ADN (12.2.b Clostridium perfringens)"},
    {"id":"n12-n-07","nucleo":"12","difficulty":"normal","topic":"Clostridium tetani","q":"¿Cómo actúa la tetanospasmina de Clostridium tetani?","a":["Bloquea la liberación de GABA y glicina en las sinapsis inhibidoras","Inhibe la liberación de acetilcolina en la placa motora","Lisa las membranas de los eritrocitos y los leucocitos","Activa de forma masiva a los linfocitos T como superantígeno"],"c":0,"exp":"La tetanospasmina es una neurotoxina que impide la liberación de neurotransmisores inhibidores, de ahí la hipertonía y los espasmos.","source":"Cuadernillo Núcleo 12 Seminario 2026 (Actividad 3) · Compendio ADN (12.2.b Clostridium tetani)"},
    {"id":"n12-n-08","nucleo":"12","difficulty":"normal","topic":"Clostridium tetani","q":"¿Cómo se previene el tétanos según el material de la cátedra?","a":["Con tres dosis de toxoide tetánico y refuerzos cada 10 años","Con una sola dosis de toxoide que deja inmunidad de por vida","Con la inmunidad que deja haber padecido la enfermedad","Con profilaxis antibiótica prolongada después de cualquier herida"],"c":0,"exp":"La prevención es la vacunación con tres dosis de toxoide y refuerzos cada 10 años; la infección no induce inmunidad. En el Calendario Nacional el esquema primario se da con quíntuple (2, 4 y 6 meses), refuerzos a los 15-18 meses y al ingreso escolar, y después dT cada 10 años.","source":"Compendio ADN (12.2.b, prevención) · Cuadernillo Núcleo 12 Seminario 2026 (Actividad 3.b)"},
    {"id":"n12-n-09","nucleo":"12","difficulty":"normal","topic":"Virus herpes simple 1 y 2","q":"¿Dónde establece latencia el virus herpes simple tipo 1?","a":["En los cuerpos neuronales del ganglio del trigémino","En los ganglios sacros","En los linfocitos B de memoria de los ganglios linfáticos","En las células basales de la epidermis"],"c":0,"exp":"El HSV-1 llega por transporte axonal retrógrado al ganglio trigémino, donde queda latente; el HSV-2 lo hace en el ganglio sacro.","source":"Compendio ADN (12.4.a.a y 12.4.a.b)"},
    {"id":"n12-n-10","nucleo":"12","difficulty":"normal","topic":"Virus herpes simple 1 y 2","q":"¿Qué estructura y material genético tienen los virus de la familia Herpesviridae?","a":["ADN bicatenario lineal, cápside icosaédrica con envoltura","ARN monocatenario negativo con nucleocápside helicoidal","ADN bicatenario circular sin envoltura","ARN monocatenario positivo con envoltura"],"c":0,"exp":"Los herpesvirus tienen genoma de ADN lineal de doble hebra, cápside icosaédrica, tegumento y envoltura lipídica, y establecen latencia.","source":"Cuadernillo Núcleo 12 Laboratorio 2026 (cuadro de virus) · Compendio ADN (12.4.a)"},
    {"id":"n12-n-11","nucleo":"12","difficulty":"normal","topic":"Virus varicela-zóster","q":"¿Dónde permanece latente el virus varicela-zóster después de la varicela?","a":["En las células neurales de los ganglios sensitivos","En los linfocitos B y los monocitos de la sangre periférica","En las células basales de la epidermis","En los macrófagos del tejido reticuloendotelial"],"c":0,"exp":"La latencia del VVZ se establece en células neuronales y gliales de los ganglios sensoriales; su reactivación produce el herpes zóster.","source":"Compendio ADN (12.4.a.c y 12.5.c)"},
    {"id":"n12-n-12","nucleo":"12","difficulty":"normal","topic":"Virus del molusco contagioso","q":"¿A qué familia pertenece el virus del molusco contagioso y qué material genético tiene?","a":["Poxviridae, ADN bicatenario","Papillomaviridae, ADN bicatenario circular","Herpesviridae, ADN bicatenario lineal","Parvoviridae, ADN monocatenario"],"c":0,"exp":"El molusco contagioso es un Poxviridae (género Molluscipoxvirus) con ADN lineal bicatenario; los poxvirus son los virus más grandes conocidos.","source":"Cuadernillo Núcleo 12 Laboratorio 2026 (TP 23, caso 5) · Compendio ADN (12.4.b)"},
    {"id":"n12-n-13","nucleo":"12","difficulty":"normal","topic":"Virus del papiloma humano (VPH)","q":"¿Qué características estructurales tiene el virus del papiloma humano?","a":["Virus desnudo, cápside icosaédrica, ADN bicatenario circular","Virus con envoltura, cápside icosaédrica, ADN bicatenario lineal","Virus desnudo con ARN monocatenario positivo","Virus con envoltura y nucleocápside helicoidal"],"c":0,"exp":"El HPV es un virus sin envoltura, de cápside icosaédrica, con genoma de ADN doble cadena circular cerrado (episoma).","source":"Compendio ADN (12.4.c) · Cuadernillo Núcleo 12 Laboratorio 2026 (TP 23, caso 6)"},
    {"id":"n12-n-14","nucleo":"12","difficulty":"normal","topic":"Herpesvirus humanos 6 y 7","q":"¿Qué enfermedad exantemática producen el HHV-6B y, a veces, el HHV-7?","a":["El exantema súbito o sexta enfermedad","El eritema infeccioso o quinta enfermedad","La escarlatina","La rubéola"],"c":0,"exp":"El exantema súbito o roséola cursa con fiebre alta de 3-5 días y después exantema maculopapular rosado en cara y tronco que dura 24-48 horas.","source":"Compendio ADN (12.5.f)"},
    {"id":"n12-n-15","nucleo":"12","difficulty":"normal","topic":"Virus de Epstein-Barr","q":"¿Cuáles son las características clínicas principales de la mononucleosis infecciosa por virus de Epstein-Barr?","a":["Faringitis, fiebre, adenopatías y esplenomegalia","Fiebre alta de 3 días y después exantema rosado en tronco","Exantema en mejillas con aspecto de cachetada","Trismo, risa sardónica y espasmos generalizados"],"c":0,"exp":"La primoinfección por EBV cursa con faringitis, fiebre, adenopatías y esplenomegalia; suele ser benigna y resuelve en 3 a 6 semanas.","source":"Compendio ADN (12.5.d)"},
    {"id":"n12-n-16","nucleo":"12","difficulty":"normal","topic":"Diagnóstico de laboratorio","q":"En el examen directo con KOH de una muestra de piel, ¿cómo se observan los dermatofitos?","a":["Como hifas hialinas tabicadas y ramificadas","Como levaduras con pseudohifas y blastoconidios","Como hifas cortas mezcladas con cúmulos de levaduras","Como esférulas de doble pared con endosporas"],"c":0,"exp":"El KOH digiere la queratina y deja ver hifas hialinas, tabicadas y ramificadas de 4 a 6 micrones, propias de los dermatofitos.","source":"Cuadernillo Núcleo 12 Laboratorio 2026 (anexo de técnicas, KOH) · Compendio ADN (12.6.a)"},
    {"id":"n12-n-17","nucleo":"12","difficulty":"normal","topic":"Candida spp.","q":"¿Qué estructuras de Candida se observan en un raspado tratado con KOH o en una tinción de PAS?","a":["Pseudohifas y blastoconidios","Artroconidios dentro del tallo piloso","Hifas no tabicadas de diámetro irregular","Esférulas con endosporas"],"c":0,"exp":"Candida se ve como levaduras ovaladas en gemación (blastoconidios) con pseudohifas; la PAS las resalta por su contenido de carbohidratos.","source":"Cuadernillo Núcleo 12 Laboratorio 2026 (TP 24, casos 2 y 4) · Compendio ADN (12.6.a)"},
    {"id":"n12-n-18","nucleo":"12","difficulty":"normal","topic":"Respuesta inmune","q":"¿Cuál es el perfil de respuesta inmune que predomina frente a los parásitos en la piel?","a":["Th2, con eosinófilos, mastocitos e IgE","Th1, con macrófagos activados y granulomas","Th17, con reclutamiento masivo de neutrófilos","Citotóxica CD8 con interferón tipo I"],"c":0,"exp":"La respuesta antiparasitaria cutánea es Th2: IL-4, IL-5 e IL-13, IgE, eosinófilos, mastocitos y basófilos.","source":"Cuadernillo Núcleo 12 Laboratorio 2026 (TP 25, Actividad 3)"},
    {"id":"n12-n-19","nucleo":"12","difficulty":"normal","topic":"Pediculus humanus capitis","q":"¿Dónde deposita sus huevos (liendres) el piojo de la cabeza?","a":["Adheridos al tallo del pelo","En los surcos que cava en el estrato córneo","En las costuras de la ropa","Libres sobre la superficie del cuero cabelludo"],"c":0,"exp":"Las liendres quedan fuertemente adheridas al tallo piloso a 1-2 mm del cuero cabelludo por una sustancia quitinosa; son ovoides y operculadas.","source":"Cuadernillo Núcleo 12 Laboratorio 2026 (TP 25, Actividad 2.D) · Compendio ADN (12.3.b)"},
    {"id":"n12-n-20","nucleo":"12","difficulty":"normal","topic":"Micosis sistémicas endémicas","q":"¿Cuál es la puerta de entrada habitual de Histoplasma capsulatum, Coccidioides spp. y Paracoccidioides brasiliensis?","a":["Inhalatoria, por esporas del ambiente","Traumatismo cutáneo con material contaminado","Endógena, desde la microbiota de la piel","Digestiva, por alimentos contaminados"],"c":0,"exp":"Las micosis sistémicas endémicas se inician por inhalación de esporas ambientales y luego se diseminan por vía hematógena o linfática, incluso a la piel.","source":"Cuadernillo Núcleo 12 Seminario 2026 (micosis sistémicas 5.1) · Compendio ADN (12.6.b)"},
    {"id":"n12-d-01","nucleo":"12","difficulty":"dificil","topic":"Staphylococcus aureus","q":"Un nene de 8 años tiene costras melicéricas con ampollas rotas alrededor de la boca, sin fiebre, y tuvo un furúnculo axilar hace dos semanas. ¿Cuál es el diagnóstico más probable?","a":["Impétigo","Erisipela","Fascitis necrosante","Síndrome de la piel escaldada"],"c":0,"exp":"Las costras color miel con ampollas y autoinoculación por rascado, sin compromiso sistémico, definen el impétigo, con S. aureus como agente más frecuente.","source":"Cuadernillo Núcleo 12 Laboratorio 2026 (TP 23, caso clínico 1)"},
    {"id":"n12-d-02","nucleo":"12","difficulty":"dificil","topic":"Diagnóstico de laboratorio","q":"De una lesión cutánea se informan cocos grampositivos en racimos y prueba de coagulasa positiva. ¿Qué permite concluir ese resultado?","a":["Se trata de Staphylococcus aureus","Se trata de un estafilococo coagulasa negativo","Se trata de Streptococcus pyogenes","Se trata de Clostridium perfringens"],"c":0,"exp":"La coagulasa separa S. aureus (positiva) de los estafilococos coagulasa negativos; es la prueba de identificación principal de S. aureus.","source":"Cuadernillo Núcleo 12 Laboratorio 2026 (TP 23, caso 1, puntos 3 y 4) · Compendio ADN (12.2.b)"},
    {"id":"n12-d-03","nucleo":"12","difficulty":"dificil","topic":"Streptococcus pyogenes","q":"Una nena de 6 años tiene fiebre y, tras un raspón, una placa eritematosa caliente de bordes netos y sobreelevados con piel de naranja y adenopatía inguinal. ¿Qué cuadro es?","a":["Erisipela","Impétigo","Celulitis por Clostridium perfringens","Pitiriasis versicolor inflamatoria"],"c":0,"exp":"La placa de bordes netos y sobreelevados, con fiebre y adenopatía, es una erisipela, cuyo agente típico es S. pyogenes, que entró por el raspón.","source":"Cuadernillo Núcleo 12 Laboratorio 2026 (TP 23, caso clínico 2)"},
    {"id":"n12-d-04","nucleo":"12","difficulty":"dificil","topic":"Clostridium tetani","q":"Un hombre de 62 años tiene trismo, risa sardónica y espasmos ante estímulos, 10 días después de una herida punzante con tierra. ¿Qué espera ver en el Gram de esa herida?","a":["Bacilos grampositivos con esporas terminales redondeadas","Cocos grampositivos en racimos","Bacilos grandes grampositivos sin esporas ni leucocitos","Bacilos ácido alcohol resistentes"],"c":0,"exp":"C. tetani es un bacilo grampositivo esporulado con esporas terminales en palillo de tambor; el diagnóstico sigue siendo clínico porque el cultivo es positivo solo en el 30%.","source":"Cuadernillo Núcleo 12 Laboratorio 2026 (TP 23, caso clínico 3) · Compendio ADN (12.2.b)"},
    {"id":"n12-d-05","nucleo":"12","difficulty":"dificil","topic":"Prevención","q":"Ante una herida tetanígena en una persona con esquema de vacunación desconocido, ¿qué corresponde según la pauta del material?","a":["Una dosis de Td más inmunoglobulina antitetánica","Solo una dosis de Td, sin inmunoglobulina antitetánica","Solo inmunoglobulina antitetánica","Nada, porque la herida ya cerró"],"c":0,"exp":"Con menos de 3 dosis o situación desconocida y herida tetanígena se indica vacuna Td (completando el esquema) más IGT en otro sitio de aplicación.","source":"Compendio ADN (12.2.b, tabla de inmunoprofilaxis) · Cuadernillo Núcleo 12 Seminario 2026 (Actividad 3.b)"},
    {"id":"n12-d-06","nucleo":"12","difficulty":"dificil","topic":"Mycobacterium leprae","q":"En la lepra tuberculoide, ¿qué combinación de respuesta inmune y hallazgos corresponde?","a":["Perfil Th1, granulomas con escasos bacilos y lepromina fuertemente positiva","Perfil Th2, macrófagos repletos de bacilos y lepromina negativa","Perfil Th2, lesiones escasas y lepromina positiva","Perfil Th1, carga bacilar altísima y compromiso multiorgánico"],"c":0,"exp":"La lepra tuberculoide es paucibacilar: respuesta Th1 con granulomas y lepromina muy positiva, a diferencia de la lepromatosa, Th2 y multibacilar.","source":"Cuadernillo Núcleo 12 Seminario 2026 (Actividad 4.b) · Compendio ADN (12.2.c)"},
    {"id":"n12-d-07","nucleo":"12","difficulty":"dificil","topic":"Virus herpes simple 1 y 2","q":"Una mujer de 20 años tiene vesículas agrupadas y dolorosas en el labio que reaparecen en el mismo lugar antes de cada examen. En el raspado de la lesión, ¿qué se observa?","a":["Células multinucleadas o sincicios","Cuerpos de inclusión eosinofílicos intracitoplasmáticos","Coilocitos con gránulos de queratohialina prominentes","Artroconidios rodeando el tallo piloso"],"c":0,"exp":"El efecto citopático del HSV-1 es la formación de sincicios con núcleos claros y cromatina marginada, además de cuerpos de Cowdry tipo A.","source":"Cuadernillo Núcleo 12 Laboratorio 2026 (TP 23, caso 4, Herpes tipo I)"},
    {"id":"n12-d-08","nucleo":"12","difficulty":"dificil","topic":"Virus de Epstein-Barr","q":"¿Qué perfil serológico confirma una primoinfección por virus de Epstein-Barr?","a":["IgM anti-VCA presente y anticuerpos anti-EBNA ausentes","IgG anti-VCA y anti-EBNA presentes","Altos títulos de anticuerpos contra antígenos tempranos","IgG anti-EBNA aislada sin anticuerpos anti-VCA"],"c":0,"exp":"La infección aguda se confirma con IgM contra la cápside viral en ausencia de anti-EBNA; el portador sano tiene IgG anti-VCA y anti-EBNA.","source":"Compendio ADN (12.5.d, métodos indirectos)"},
    {"id":"n12-d-09","nucleo":"12","difficulty":"dificil","topic":"Virus de la rubéola","q":"¿Cuándo se produce el síndrome de rubéola congénita y qué defectos incluye?","a":["Por infección materna en el primer trimestre; da cataratas y sordera","Por infección materna en el último mes, con neumonía neonatal grave","Por infección perinatal en el canal de parto, con meningitis y sepsis","Por reactivación materna del virus latente, con anemia fetal"],"c":0,"exp":"El SRC aparece cuando la infección materna ocurre en el primer trimestre y puede dar cardiopatías, cataratas y sordera; se previene con la vacunación.","source":"Compendio ADN (12.5.b)"},
    {"id":"n12-d-10","nucleo":"12","difficulty":"dificil","topic":"Parvovirus B19","q":"¿Qué complicación produce el parvovirus B19 en un paciente con anemia hemolítica crónica?","a":["Crisis aplásica transitoria con reticulocitopenia","Hydrops fetalis","Poliartritis de manos y muñecas","Púrpura trombocitopénica por complejos inmunes"],"c":0,"exp":"Al lisar los precursores eritroides, el B19 provoca crisis aplásica transitoria con reticulocitopenia de 7-10 días y caída de la hemoglobina.","source":"Compendio ADN (12.5.e, complicaciones hematológicas)"},
    {"id":"n12-d-11","nucleo":"12","difficulty":"dificil","topic":"Sarcoptes scabiei","q":"¿Qué forma clínica de escabiosis corresponde a un paciente inmunodeprimido con escasa respuesta frente al ácaro?","a":["Sarna costrosa o noruega","Sarna nodular o hiperérgica","Sarna clásica","Larva migrans cutánea"],"c":0,"exp":"La sarna anérgica (costrosa o noruega) aparece en inmunodeprimidos; la nodular es la forma hiperérgica y la clásica, la del huésped inmunocompetente.","source":"Cuadernillo Núcleo 12 Laboratorio 2026 (TP 25, Actividad 1.B) · Compendio ADN (12.3.a)"},
    {"id":"n12-d-12","nucleo":"12","difficulty":"dificil","topic":"Malassezia furfur","q":"Un paciente de 20 años tiene máculas hipopigmentadas con descamación furfurácea en dorso y pecho, más notorias tras el verano. ¿Qué imagen microscópica se espera?","a":["Hifas cortas y cúmulos de levaduras","Hifas hialinas tabicadas y ramificadas","Pseudohifas con blastoconidios en gemación","Artroconidios en el interior del tallo piloso"],"c":0,"exp":"La pitiriasis versicolor por Malassezia muestra levaduras esféricas u ovaladas de pared gruesa mezcladas con hifas cortas poco ramificadas.","source":"Cuadernillo Núcleo 12 Laboratorio 2026 (TP 24, caso 1) · Compendio ADN (12.6.a)"},
    {"id":"n12-d-13","nucleo":"12","difficulty":"dificil","topic":"Dermatofitos","q":"Un nene de 7 años tiene una placa alopécica con descamación grisácea y pelos fracturados; en el tallo piloso se ven artroconidios. ¿Qué agente es el más probable en nuestro medio?","a":["Microsporum canis","Malassezia furfur","Candida albicans","Histoplasma capsulatum"],"c":0,"exp":"Es una tiña capitis por dermatofitos y en nuestro medio el agente aislado con mayor frecuencia es M. canis, de origen zoófilo.","source":"Cuadernillo Núcleo 12 Laboratorio 2026 (TP 24, caso 3) · Compendio ADN (12.6.a)"},
    {"id":"n12-d-14","nucleo":"12","difficulty":"dificil","topic":"Histoplasma capsulatum","q":"Un paciente inmunocomprometido con tos y lesiones papulares en tronco trabajó en el norte del país con excremento de murciélago. En la biopsia de piel, ¿qué forma del hongo espera?","a":["Levaduras","Hifas tabicadas","Hifas no tabicadas","Esférulas con endosporas"],"c":0,"exp":"Histoplasma es dimórfico: en los tejidos a 37 grados se presenta como levaduras, mientras que la forma filamentosa corresponde al ambiente.","source":"Cuadernillo Núcleo 12 Laboratorio 2026 (TP 24, Actividad 2, caso 2) · Compendio ADN (12.6.b)"},
    {"id":"n12-d-15","nucleo":"12","difficulty":"dificil","topic":"Coccidioides spp.","q":"En una biopsia de piel con Grocott de un trasplantado oriundo de una zona árida del norte argentino se ven esférulas de doble pared con endosporas. ¿Qué agente es?","a":["Coccidioides spp.","Histoplasma capsulatum","Paracoccidioides brasiliensis","Mucor sp."],"c":0,"exp":"Las esférulas de doble pared con endosporas son típicas de Coccidioides; la zona árida y la inmunosupresión orientan a coccidioidomicosis diseminada.","source":"Cuadernillo Núcleo 12 Laboratorio 2026 (TP 24, Actividad 2, caso 3)"},
    {"id":"n13_14-f-01","nucleo":"13-14","difficulty":"facil","topic":"Infecciones oportunistas","q":"¿Qué define a un microorganismo como \"oportunista\"?","a":["Causa infecciones más frecuentes o graves en inmunocomprometidos","Solo causa enfermedad en personas con inmunidad conservada","Proviene siempre de la microbiota y nunca del ambiente","Se adquiere exclusivamente durante una internación"],"c":0,"exp":"Son oportunistas los que causan infecciones con mayor frecuencia o gravedad en inmunodeficientes o inmunosuprimidos. Pueden venir de la microbiota o del ambiente y dar cuadros atípicos o generalizados.","source":"Cuadernillo Núcleo 13 2026 (Seminario, Introducción) · Compendio ADN (Núcleo 13)"},
    {"id":"n13_14-f-02","nucleo":"13-14","difficulty":"facil","topic":"Virus de la inmunodeficiencia humana (VIH)","q":"En una persona con VIH, ¿qué recuento de linfocitos T CD4+ alcanza por sí solo para clasificarla como caso de SIDA?","a":["Menor de 200/mm³","Menor de 500/mm³","Menor de 350/mm³","Menor de 1000/mm³"],"c":0,"exp":"Según el CDC, toda persona con VIH y CD4 < 200/mm³ es caso de SIDA, tenga o no eventos definidores (infecciones oportunistas, neoplasias, etc.).","source":"Cuadernillo Núcleo 13 2026 (Seminario, Act. 2a) · Compendio ADN (13.a.a)"},
    {"id":"n13_14-f-03","nucleo":"13-14","difficulty":"facil","topic":"Virus varicela-zóster","q":"¿Para cuál de estos herpesvirus oportunistas se cuenta con una vacuna?","a":["Virus varicela-zóster","Citomegalovirus","Virus herpes simple 1","Virus de Epstein-Barr"],"c":0,"exp":"El VVZ tiene vacuna a virus vivo atenuado contra la varicela (calendario: 15 meses y refuerzo) y una vacuna recombinante contra el herpes zóster; para CMV, VHS y EBV no hay vacunas en uso.","source":"Cuadernillo Núcleo 13 2026 (Seminario, Act. 4b) · Compendio ADN (13.a.c)"},
    {"id":"n13_14-f-04","nucleo":"13-14","difficulty":"facil","topic":"Herpesvirus humano 8","q":"¿Qué herpesvirus se asocia al sarcoma de Kaposi epidémico de los pacientes con SIDA?","a":["Herpesvirus humano 8","Virus de Epstein-Barr","Citomegalovirus","Virus herpes simple 2"],"c":0,"exp":"El HHV-8 causa el sarcoma de Kaposi (forma epidémica asociada al SIDA), el linfoma primario de efusiones y la enfermedad multicéntrica de Castleman.","source":"Cuadernillo Núcleo 13 2026 (Seminario, Act. 4a) · Compendio ADN (13.a.c)"},
    {"id":"n13_14-f-05","nucleo":"13-14","difficulty":"facil","topic":"Cryptococcus neoformans","q":"¿Cuál es la fuente ambiental típica de Cryptococcus neoformans / gattii?","a":["Excretas de palomas y eucaliptos","Bambú y roedores del sudeste asiático","Zonas áridas del continente americano","Microbiota de piel y tracto digestivo"],"c":0,"exp":"Cryptococcus se asocia a excretas de palomas y a eucaliptos, y se adquiere por inhalación. Bambú y roedores corresponde a Talaromyces; las zonas áridas, a Coccidioides.","source":"Cuadernillo Núcleo 13 2026 (Laboratorio, Introducción) · Compendio ADN (Micosis oportunistas, cuadro)"},
    {"id":"n13_14-f-06","nucleo":"13-14","difficulty":"facil","topic":"Histoplasma capsulatum","q":"¿Qué hongo dimórfico vive en suelos con excretas de aves y murciélagos y a 37 °C se ve como levadura dentro de macrófagos?","a":["Histoplasma capsulatum","Coccidioides posadasii","Paracoccidioides brasiliensis","Blastomyces dermatitidis"],"c":0,"exp":"Histoplasma es micelial a 25 °C (macroconidios tuberculados) y levadura intracelular a 37 °C. Da lesiones pulmonares parecidas a la TBC y se disemina en inmunocomprometidos.","source":"Cuadernillo Núcleo 13 2026 (listado de agentes) · Compendio ADN (Micosis sistémicas primarias, cuadro)"},
    {"id":"n13_14-f-07","nucleo":"13-14","difficulty":"facil","topic":"Cryptosporidium spp.","q":"¿Cómo se infecta habitualmente una persona con Cryptosporidium?","a":["Agua o alimentos con ooquistes","Penetración de larvas a través de la piel","Picadura de un triatomino","Inhalación de esporas del suelo"],"c":0,"exp":"El estadio infectante es el ooquiste maduro y la transmisión es sobre todo por agua o alimentos contaminados. El ooquiste eliminado en heces es también el estadio diagnóstico.","source":"Cuadernillo Núcleo 13 2026 (Seminario, Act. 5a) · Compendio ADN (13.b)"},
    {"id":"n13_14-f-08","nucleo":"13-14","difficulty":"facil","topic":"Pseudomonas aeruginosa","q":"Un bacilo gramnegativo no fermentador, oxidasa positiva, que produce pigmento azul-verdoso y coloniza jabones y tubos de PVC. ¿Qué agente es?","a":["Pseudomonas aeruginosa","Acinetobacter baumannii","Stenotrophomonas maltophilia","Klebsiella pneumoniae"],"c":0,"exp":"Pseudomonas: BGN no fermentador, aerobio estricto, oxidasa positivo y con pigmentos. Se disemina por las manos y es oportunista en usuarios de catéteres y lentes de contacto.","source":"Cuadernillo Núcleo 13 2026 (Laboratorio, Introducción y Act. 1c) · Compendio ADN (13.c.a)"},
    {"id":"n13_14-f-09","nucleo":"13-14","difficulty":"facil","topic":"Situaciones de compromiso inmune","q":"Según la clasificación de situaciones de compromiso inmune, ¿cuál de estas es un defecto de barrera?","a":["Quemaduras extensas","Trasplante con inmunosupresores","Error innato de la inmunidad","VIH avanzado"],"c":0,"exp":"Son defectos de barrera las quemaduras, las prótesis y catéteres y la fibrosis quística. El trasplante y el VIH son defectos secundarios de la inmunidad; el error innato es un defecto primario.","source":"Cuadernillo Núcleo 13 2026 (Seminario, Act. 1c) · Compendio ADN (Núcleo 13, cuadro de compromiso inmune)"},
    {"id":"n13_14-f-10","nucleo":"13-14","difficulty":"facil","topic":"Pneumocystis jirovecii","q":"¿Cuál es la infección oportunista más frecuente en pacientes con SIDA?","a":["Neumonía por Pneumocystis jirovecii","Meningitis por Cryptococcus neoformans","Retinitis por citomegalovirus","Toxoplasmosis cerebral"],"c":0,"exp":"La neumocistosis es la infección oportunista más frecuente en SIDA, típicamente con CD4 < 200: neumonía intersticial con disnea progresiva, tos seca y fiebre.","source":"Cuadernillo Núcleo 13 2026 (Laboratorio, Act. 2) · Compendio ADN (13.c.b, cuadro y ficha de neumocistosis)"},
    {"id":"n13_14-n-01","nucleo":"13-14","difficulty":"normal","topic":"Neutropenia","q":"¿Cómo se define la neutropenia según el material de la cátedra?","a":["PMN ≤ 500/mm³, o ≤ 1000/mm³ si se prevé caída a < 500 en 48 h","PMN ≤ 1500/mm³ sostenido durante más de 48 horas","Leucocitos totales < 4000/mm³, sin importar la fórmula","PMN ≤ 100/mm³ mantenido durante 7 días o más"],"c":0,"exp":"Neutropenia: PMN ≤ 500/mm³, o ≤ 1000/mm³ con descenso previsto a < 500 en 48 h. Con ≤ 100/mm³ es profunda, y si dura ≥ 7 días, prolongada.","source":"Cuadernillo Núcleo 13 2026 (Seminario, Act. 3a) · Compendio ADN (13.a.b)"},
    {"id":"n13_14-n-02","nucleo":"13-14","difficulty":"normal","topic":"Neutropenia","q":"En un paciente con neutropenia febril post quimioterapia, ¿qué tipo de infecciones son las más prevalentes?","a":["Bacterianas","Fúngicas invasivas desde el inicio","Virales","Parasitarias intestinales"],"c":0,"exp":"Predominan las bacterianas, con focos digestivo, respiratorio, catéteres y piel. También hay virales, y las fúngicas invasivas suelen aparecer más tarde.","source":"Cuadernillo Núcleo 13 2026 (Seminario, Act. 3c) · Compendio ADN (13.a.b)"},
    {"id":"n13_14-n-03","nucleo":"13-14","difficulty":"normal","topic":"Prevención","q":"¿Qué recomendación le darías a un paciente neutropénico para ayudarlo a evitar infecciones?","a":["Evitar plantas en el ambiente y la exposición a obras","Tener plantas en la habitación para mejorar el aire","No usar barbijo para no alterar la microbiota","Suspender todas las vacunas hasta recuperarse"],"c":0,"exp":"Se recomienda mantener las vacunas al día, evitar plantas, obras en construcción, revistas, diarios y mate (dispersión de hongos ambientales) y usar barbijo durante la atención.","source":"Cuadernillo Núcleo 13 2026 (Seminario, Act. 3d) · Compendio ADN (13.a.b)"},
    {"id":"n13_14-n-04","nucleo":"13-14","difficulty":"normal","topic":"Herpesviridae","q":"¿Qué falla permite que los herpesvirus latentes se reactiven y den cuadros graves en inmunocomprometidos?","a":["Falla de la vigilancia por inmunidad celular","Déficit aislado de IgA secretoria en las mucosas","Neutropenia funcional","Rotura de barreras por catéteres"],"c":0,"exp":"Todos los Herpesviridae quedan latentes tras la primoinfección, controlados por la inmunidad celular. Su falla (SIDA, trasplante, corticoides) permite la reactivación.","source":"Cuadernillo Núcleo 13 2026 (Seminario, Act. 4a) · Compendio ADN (13.a.c)"},
    {"id":"n13_14-n-05","nucleo":"13-14","difficulty":"normal","topic":"Citomegalovirus (CMV)","q":"En pacientes con SIDA, ¿cuál es la manifestación más frecuente de la infección por citomegalovirus?","a":["Retinitis","Leucoplasia oral vellosa","Linfoma primario de efusiones","Hepatitis aislada"],"c":0,"exp":"En inmunodeprimidos el CMV da enfermedad diseminada (neumonitis, esofagitis, colitis, hepatitis, encefalitis); en SIDA, la retinitis es la manifestación más frecuente.","source":"Compendio ADN (13.a.c, cuadro de virus oportunistas) · Cuadernillo Núcleo 13 2026 (Seminario, Act. 4a)"},
    {"id":"n13_14-n-06","nucleo":"13-14","difficulty":"normal","topic":"Virus de Epstein-Barr","q":"¿Qué lesión oral de un paciente con SIDA se asocia al virus de Epstein-Barr?","a":["Leucoplasia oral vellosa","Candidiasis orofaríngea (muguet)","Úlceras herpéticas crónicas","Sarcoma de Kaposi en paladar"],"c":0,"exp":"En inmunosuprimidos el EBV causa leucoplasia oral vellosa y diversos linfomas, incluidos los asociados al SIDA.","source":"Cuadernillo Núcleo 13 2026 (Seminario, Act. 4a) · Compendio ADN (13.a.c)"},
    {"id":"n13_14-n-07","nucleo":"13-14","difficulty":"normal","topic":"Virus varicela-zóster","q":"Un paciente trasplantado se expone a la varicela. ¿Por qué no se lo vacuna y qué se le indica?","a":["La vacuna es a virus vivo; se indica VZIG o antiviral profiláctico","La vacuna es inactivada y no protege; se lo aísla sin tratamiento","La vacuna es a subunidades; se aplica un refuerzo inmediato","La vacuna es a virus vivo; se aplica igual, en doble dosis"],"c":0,"exp":"La vacuna contra VVZ es a virus vivo atenuado y está contraindicada en inmunocomprometidos; ante una exposición se usa inmunoglobulina hiperinmune (VZIG) o antivirales profilácticos.","source":"Cuadernillo Núcleo 13 2026 (Seminario, Act. 4b) · Compendio ADN (13.a.c)"},
    {"id":"n13_14-n-08","nucleo":"13-14","difficulty":"normal","topic":"Toxoplasma gondii","q":"¿Cómo se produce la toxoplasmosis cerebral en un paciente con SIDA?","a":["Por reactivación: se rompen quistes y los bradizoítos pasan a taquizoítos","Por primoinfección con ooquistes que se enquistan directo en el SNC","Por taquizoítos de origen congénito que nunca se enquistaron","Por larvas que migran desde el intestino hacia el cerebro"],"c":0,"exp":"Es la reactivación de una toxoplasmosis crónica por caída de la inmunidad celular: los quistes se rompen, los bradizoítos se convierten en taquizoítos y causan lesiones cerebrales focales.","source":"Cuadernillo Núcleo 13 2026 (Seminario, Act. 5b) · Compendio ADN (13.b)"},
    {"id":"n13_14-n-09","nucleo":"13-14","difficulty":"normal","topic":"Cryptosporidium spp.","q":"¿Qué tinción se usa en materia fecal para observar ooquistes de Cryptosporidium?","a":["Ziehl-Neelsen modificada o Kinyoun","Tinta china en examen en fresco","Grocott con metenamina de plata","PAS (ácido peryódico de Schiff)"],"c":0,"exp":"Los ooquistes son ácido-alcohol resistentes: se ven con Ziehl-Neelsen modificada o Kinyoun. La IFD con anticuerpos monoclonales es el estándar de oro de rutina y la PCR es más sensible.","source":"Cuadernillo Núcleo 13 2026 (Seminario, Act. 5a) · Compendio ADN (13.b)"},
    {"id":"n13_14-n-10","nucleo":"13-14","difficulty":"normal","topic":"Strongyloides stercoralis","q":"¿Qué mecanismo explica el síndrome de hiperinfección por Strongyloides stercoralis?","a":["Autoinfección acelerada sin control inmune","Reinfección masiva por agua contaminada","Ruptura de quistes tisulares con bradizoítos","Multiplicación de ooquistes en el intestino"],"c":0,"exp":"En el inmunocompetente la autoinfección está controlada. Con la inmunidad disminuida el ciclo se acorta y acelera, sube mucho la carga parasitaria y se exacerban los síntomas pulmonares y digestivos.","source":"Cuadernillo Núcleo 13 2026 (Seminario, Act. 5c) · Compendio ADN (13.b)"},
    {"id":"n13_14-n-11","nucleo":"13-14","difficulty":"normal","topic":"Strongyloides stercoralis","q":"¿En cuál de estos pacientes sospecharías un síndrome de hiperinfección por Strongyloides stercoralis?","a":["Tratamiento prolongado con glucocorticoides","Fibrosis quística con colonización bronquial","Quemaduras extensas","Uso de lentes de contacto"],"c":0,"exp":"Se sospecha con inmunosupresores (glucocorticoides, antineoplásicos), trasplante de riñón o médula, infección por VIH o HTLV-1, hipogammaglobulinemia o malnutrición severa.","source":"Cuadernillo Núcleo 13 2026 (Seminario, Act. 5c) · Compendio ADN (13.b)"},
    {"id":"n13_14-n-12","nucleo":"13-14","difficulty":"normal","topic":"Mycobacterium tuberculosis","q":"¿Qué caracteriza a la tuberculosis en pacientes con VIH e inmunodepresión severa?","a":["Formas extrapulmonares y diseminadas, con cavitación infrecuente","Cavitaciones apicales en la gran mayoría de los casos","Localización exclusivamente pulmonar y focal","Curso asintomático hasta que aparece la cavitación"],"c":0,"exp":"Predominan las formas extrapulmonares y diseminadas; con CD4 < 200 suele verse fiebre sin foco, y la Rx muestra infiltrados intersticiales difusos o es normal. Las cavitaciones son muy infrecuentes.","source":"Cuadernillo Núcleo 13 2026 (Laboratorio, Act. 1a) · Compendio ADN (13.c.a)"},
    {"id":"n13_14-n-13","nucleo":"13-14","difficulty":"normal","topic":"Micobacterias atípicas (MAC)","q":"¿Cuál es la presentación más frecuente de Mycobacterium kansasii en inmunocomprometidos?","a":["Cuadro pulmonar con infiltrados, a veces cavitados","Úlceras cutáneas, sinovitis y osteomielitis","Enfermedad diseminada con diarrea crónica y adenopatías","Linfadenitis cervical aislada"],"c":0,"exp":"M. kansasii es la segunda micobacteria atípica en frecuencia: puede diseminarse, pero lo más común es un cuadro pulmonar con tos, fiebre e infiltrados. Úlceras y sinovitis son de M. haemophilum.","source":"Cuadernillo Núcleo 13 2026 (Laboratorio, Act. 1b) · Compendio ADN (13.c.a)"},
    {"id":"n13_14-n-14","nucleo":"13-14","difficulty":"normal","topic":"Nocardia spp.","q":"¿Qué descripción corresponde a Nocardia spp.?","a":["Bacilo grampositivo filamentoso, aerobio y ácido resistente","Bacilo grampositivo ramificado, anaerobio, con gránulos de azufre","Cocobacilo gramnegativo inmóvil y aerobio","Bacilo gramnegativo no fermentador, oxidasa positiva"],"c":0,"exp":"Nocardia es un bacilo grampositivo aerobio, filamentoso, ácido resistente y de crecimiento lento. Se adquiere por inhalación o heridas y no se transmite de persona a persona.","source":"Cuadernillo Núcleo 13 2026 (Laboratorio, Act. 1c) · Compendio ADN (13.c.a, cuadros)"},
    {"id":"n13_14-n-15","nucleo":"13-14","difficulty":"normal","topic":"Actinomyces spp.","q":"En el pus de un absceso cervicofacial de un paciente con mala higiene bucal, ¿qué hallazgo orienta a actinomicosis?","a":["Gránulos de azufre","Cápsula visible con tinta china","Hifas ramificadas a 45°","Esférulas con endosporas"],"c":0,"exp":"Actinomyces (bacilo grampositivo anaerobio, de la flora de la boca) da infección endógena cuando se rompen las barreras mucosas y forma \"gránulos de azufre\" en los abscesos.","source":"Cuadernillo Núcleo 13 2026 (Laboratorio, Act. 1c) · Compendio ADN (13.c.a, cuadro comparativo)"},
    {"id":"n13_14-n-16","nucleo":"13-14","difficulty":"normal","topic":"Acinetobacter baumannii","q":"¿Qué bacteria ESKAPE es un cocobacilo gramnegativo inmóvil, sobrevive en superficies secas y se asocia a heridas, quemaduras y UCI?","a":["Acinetobacter baumannii","Pseudomonas aeruginosa","Stenotrophomonas maltophilia","Klebsiella pneumoniae"],"c":0,"exp":"Acinetobacter es no fermentador, vive en agua y suelo y sobrevive en superficies húmedas y secas. Los brotes son hospitalarios y las infecciones se asocian a heridas, quemaduras y catéteres.","source":"Cuadernillo Núcleo 13 2026 (Laboratorio, Introducción y Act. 1c) · Compendio ADN (13.c.a)"},
    {"id":"n13_14-n-17","nucleo":"13-14","difficulty":"normal","topic":"Clostridioides difficile","q":"En pacientes oncohematológicos, ¿qué factores predisponen a la colitis pseudomembranosa por Clostridioides difficile?","a":["Antibióticos, antineoplásicos e internación prolongada","Uso de lentes de contacto y sondas urinarias permanentes","Déficit de IgA y fibrosis quística","Exposición a excretas de aves"],"c":0,"exp":"C. difficile (bacilo grampositivo esporulado, anaerobio estricto) es emergente en oncohematología. Además de los antibióticos, muchas drogas antineoplásicas y la internación prolongada predisponen; puede dar megacolon tóxico.","source":"Cuadernillo Núcleo 13 2026 (Laboratorio, Introducción y Act. 1d) · Compendio ADN (13.c)"},
    {"id":"n13_14-n-18","nucleo":"13-14","difficulty":"normal","topic":"Aspergillus spp.","q":"¿Qué se observa en una biopsia de pulmón con aspergilosis invasiva?","a":["Hifas hialinas septadas que se ramifican en ángulo agudo","Hifas anchas no septadas con esporangios","Levaduras con gemación de base estrecha y cápsula gruesa","Quistes en forma de taza teñidos de negro"],"c":0,"exp":"Aspergillus: hifas hialinas tabicadas, de grosor uniforme, con ramificación dicotómica en ángulo agudo (~45°). Son angioinvasivas: provocan trombosis e infartos necróticos.","source":"Cuadernillo Núcleo 13 2026 (Laboratorio, Act. 3) · Compendio ADN (13.c.b, ficha de aspergilosis)"},
    {"id":"n13_14-n-19","nucleo":"13-14","difficulty":"normal","topic":"Mucorales","q":"¿Qué morfología caracteriza a los Mucorales (Rhizopus, Mucor, Lichtheimia) en el laboratorio?","a":["Hifas no septadas, esporangios grandes y crecimiento rápido","Hifas septadas con macroconidios en forma de banana","Levaduras con pseudohifas y tubo germinativo","Levaduras con artroconidios"],"c":0,"exp":"Los Mucorales son filamentosos no septados, con esporangios grandes y crecimiento rápido; causan mucormicosis rinoorbitocerebral, pulmonar o diseminada. Los macroconidios en banana son de Fusarium.","source":"Cuadernillo Núcleo 13 2026 (listado de agentes) · Compendio ADN (Micosis oportunistas, cuadros)"},
    {"id":"n13_14-n-20","nucleo":"13-14","difficulty":"normal","topic":"Virus de la inmunodeficiencia humana (VIH)","q":"Para evaluar el estado inmune de una persona con VIH, ¿qué estudios se piden?","a":["Recuento de linfocitos T CD4 y carga viral","Hemograma con recuento de neutrófilos solamente","Dosaje de IgA e IgG séricas","Western blot y prueba de Sabin-Feldman"],"c":0,"exp":"El equilibrio entre la replicación viral (carga viral) y el sistema inmune se mide con el recuento de CD4. Sin tratamiento, la carga viral sube y los CD4 caen progresivamente hasta el SIDA.","source":"Cuadernillo Núcleo 13 2026 (Seminario, Act. 2b) · Compendio ADN (13.a.a)"},
    {"id":"n13_14-d-01","nucleo":"13-14","difficulty":"dificil","topic":"Pneumocystis jirovecii","q":"Varón de 28 años sin antecedentes, con disnea de 2 semanas, tos seca, saturación 88%, TC con vidrio esmerilado bilateral que respeta la periferia y LDH 850. ¿Qué agente sospechás?","a":["Pneumocystis jirovecii","Aspergillus fumigatus","Cryptococcus neoformans","Mycobacterium kansasii"],"c":0,"exp":"Neumonía intersticial insidiosa con vidrio esmerilado bilateral e hipoxemia sugiere neumocistosis, típica del SIDA con CD4 < 200: obliga a pensar en un VIH no diagnosticado.","source":"Cuadernillo Núcleo 13 2026 (Laboratorio, Act. 2, caso 1) · Compendio ADN (13.c.b)"},
    {"id":"n13_14-d-02","nucleo":"13-14","difficulty":"dificil","topic":"Pneumocystis jirovecii","q":"Para confirmar una neumonía por Pneumocystis jirovecii, ¿qué estudio corresponde?","a":["Grocott en lavado broncoalveolar","Cultivo de esputo en medio para hongos","Galactomanano en suero","Antígeno capsular en suero"],"c":0,"exp":"Pneumocystis no se cultiva: se diagnostica por microscopía de LBA, esputo inducido o biopsia, con GMS/Grocott (pared del quiste, en negro), Giemsa (formas tróficas) o inmunofluorescencia.","source":"Cuadernillo Núcleo 13 2026 (Laboratorio, Act. 2 y 3) · Compendio ADN (13.c.b)"},
    {"id":"n13_14-d-03","nucleo":"13-14","difficulty":"dificil","topic":"Aspergillus spp.","q":"Varón de 48 años con LMA en inducción, neutropénico hace 7 días, con fiebre, puntada de costado y hemoptisis. TC: cavitación con signo del halo; galactomanano sérico positivo. ¿Diagnóstico?","a":["Aspergilosis pulmonar invasiva","Neumonía por Pneumocystis jirovecii","Criptococosis pulmonar","Tuberculosis cavitaria"],"c":0,"exp":"La aspergilosis pulmonar invasiva es devastadora en neutropénicos (< 500/mm³): fiebre, infiltrados, dolor pleurítico y hemoptisis por angioinvasión. El galactomanano sérico positivo apoya el diagnóstico.","source":"Cuadernillo Núcleo 13 2026 (Laboratorio, Act. 2, caso 2) · Compendio ADN (13.c.b)"},
    {"id":"n13_14-d-04","nucleo":"13-14","difficulty":"dificil","topic":"Aspergillus spp.","q":"Sobre el diagnóstico de laboratorio de la aspergilosis invasiva, ¿qué afirmación es correcta?","a":["Los hemocultivos rara vez son positivos","El antígeno capsular en LCR es de elección","No se cultiva: requiere tinción de Grocott","La prueba del tubo germinativo lo confirma"],"c":0,"exp":"Se diagnostica por anatomía patológica (hifas en tejido), cultivo y detección de galactomanano en suero; los hemocultivos rara vez dan positivo.","source":"Compendio ADN (13.c.b, cuadro de micosis) · Cuadernillo Núcleo 13 2026 (Laboratorio, Act. 2)"},
    {"id":"n13_14-d-05","nucleo":"13-14","difficulty":"dificil","topic":"Cryptococcus neoformans","q":"Mujer de 35 años con VIH (CD4 152), cefalea de 10 días, vómitos en escopeta, presión de apertura del LCR de 40 cmH2O y tinta china positiva. ¿Qué otro estudio en LCR es rápido y sensible?","a":["Antígeno capsular polisacárido","Galactomanano","Ziehl-Neelsen del sedimento centrifugado","IgM anti-Toxoplasma"],"c":0,"exp":"Es una meningitis criptocócica. La cápsula polisacárida es su marcador: detectar el antígeno capsular en LCR o suero es rápido y sensible; se complementa con tinta china y cultivo.","source":"Cuadernillo Núcleo 13 2026 (Laboratorio, Act. 2, caso 3) · Compendio ADN (13.c.b)"},
    {"id":"n13_14-d-06","nucleo":"13-14","difficulty":"dificil","topic":"Candida spp.","q":"Paciente en UCI con catéter venoso central hace 21 días, nutrición parenteral y antibióticos, febril sin foco. Hemocultivos y cultivo del catéter desarrollan levaduras. ¿Agente más probable?","a":["Candida spp.","Aspergillus fumigatus","Pneumocystis jirovecii","Mucorales"],"c":0,"exp":"Candida da infección endógena en pacientes con catéteres, antibióticos, neutropenia o cirugía. La candidemia es una causa frecuente de infección nosocomial, con mortalidad atribuible cercana al 50%.","source":"Cuadernillo Núcleo 13 2026 (Laboratorio, Act. 2, caso 4) · Compendio ADN (13.c.b)"},
    {"id":"n13_14-d-07","nucleo":"13-14","difficulty":"dificil","topic":"Toxoplasma gondii","q":"En un paciente con SIDA y sospecha de toxoplasmosis cerebral, ¿qué particularidad tiene el diagnóstico?","a":["Suele no haber IgM; puede requerir RNM, biopsia y PCR","La IgM siempre es positiva y confirma la reactivación","Se confirma al ver ooquistes en materia fecal","El método directo en sangre tiene alto rendimiento"],"c":0,"exp":"En el inmunocomprometido casi nunca hay IgM y los títulos de IgG e IgA son bajos: el diagnóstico suele requerir RNM o biopsia cerebral con PCR. La IgM sirve en el inmunocompetente.","source":"Cuadernillo Núcleo 13 2026 (Seminario, Act. 5b) · Compendio ADN (13.b, cuadro comparativo)"},
    {"id":"n13_14-d-08","nucleo":"13-14","difficulty":"dificil","topic":"Strongyloides stercoralis","q":"¿Qué define a la estrongiloidosis diseminada, a diferencia del síndrome de hiperinfección?","a":["Larvas en órganos que el parásito normalmente no alcanza","Mayor carga de larvas, pero limitada a pulmón e intestino","Quistes en músculo estriado","Ooquistes en heces por más de 1 mes"],"c":0,"exp":"La hiperinfección exacerba el ciclo habitual (pulmón e intestino). La diseminación es el hallazgo de larvas en casi todos los órganos que normalmente no alcanza, y suele ser fatal.","source":"Cuadernillo Núcleo 13 2026 (Seminario, Act. 5c) · Compendio ADN (13.b)"},
    {"id":"n13_14-d-09","nucleo":"13-14","difficulty":"dificil","topic":"Eventos definidores de SIDA","q":"¿Cuál de estas situaciones es un evento definidor de SIDA?","a":["Sarcoma de Kaposi en un paciente de 45 años","Candidiasis orofaríngea","Citomegalovirosis limitada al hígado y los ganglios","Criptosporidiosis con diarrea de 2 semanas"],"c":0,"exp":"El Kaposi en menores de 60 años es definidor. La candidiasis tiene que ser esofágica o respiratoria, el CMV fuera de hígado y ganglios, y la criptosporidiosis con diarrea de más de 1 mes.","source":"Cuadernillo Núcleo 13 2026 (Seminario, Act. 2) · Compendio ADN (13.a.a)"},
    {"id":"n13_14-d-10","nucleo":"13-14","difficulty":"dificil","topic":"Trypanosoma cruzi","q":"¿Qué manifestación de la infección por Trypanosoma cruzi se considera evento definidor de SIDA?","a":["Encefalopatía chagásica","Miocardiopatía dilatada","Megaesófago","Chagoma de inoculación"],"c":0,"exp":"La encefalopatía chagásica figura entre los eventos definidores: es una manifestación no habitual de una enfermedad frecuente, que aparece por el deterioro inmune del SIDA.","source":"Cuadernillo Núcleo 13 2026 (Seminario, Act. 2) · Compendio ADN (13.a.a)"},
    {"id":"n13_14-d-11","nucleo":"13-14","difficulty":"dificil","topic":"Micobacterias atípicas (MAC)","q":"Paciente con SIDA muy avanzado, con fiebre persistente, sudoración nocturna, diarrea crónica, hepatoesplenomegalia y adenopatías mesentéricas. ¿Qué sospechás?","a":["Micobacteriosis diseminada por MAC","Neumonía por Mycobacterium kansasii","Úlceras por Mycobacterium haemophilum","Nocardiosis cutánea localizada"],"c":0,"exp":"M. avium-intracellulare es la micobacteria atípica principal: aparece en fases muy avanzadas del SIDA, con CD4 muy bajos, como enfermedad diseminada. La micobacteriosis diseminada por M. avium es definidora.","source":"Cuadernillo Núcleo 13 2026 (Laboratorio, Act. 1b; Seminario, Act. 2) · Compendio ADN (13.c.a)"},
    {"id":"n13_14-d-12","nucleo":"13-14","difficulty":"dificil","topic":"Giardia lamblia","q":"Un niño tiene giardiasis a repetición. Según el cuadro de compromiso inmune del material, ¿qué defecto primario sugiere este agente?","a":["Déficit de IgA o de anticuerpos","Enfermedad granulomatosa crónica","Falla de linfocitos T por VIH","Neutropenia post quimioterapia"],"c":0,"exp":"Algunos agentes son indicadores de inmunodeficiencias primarias: Giardia sugiere déficit de IgA o de anticuerpos; Nocardia y S. aureus, enfermedad granulomatosa crónica.","source":"Compendio ADN (Núcleo 13, aclaración del cuadro de compromiso inmune) · Cuadernillo Núcleo 13 2026 (Seminario, Act. 1c)"},
    {"id":"n13_14-d-13","nucleo":"13-14","difficulty":"dificil","topic":"Neutropenia","q":"Un paciente en quimioterapia tiene 80 neutrófilos/mm³ desde hace 9 días. ¿Cómo se clasifica su neutropenia?","a":["Profunda y prolongada","Funcional y transitoria","Leve pero prolongada","Profunda pero no prolongada"],"c":0,"exp":"Neutropenia profunda o severa: PMN ≤ 100/mm³; prolongada: dura ≥ 7 días. La funcional es la de neutrófilos defectuosos con recuento normal o aumentado.","source":"Compendio ADN (13.a.b) · Cuadernillo Núcleo 13 2026 (Seminario, Act. 3a)"},
    {"id":"n13_14-d-14","nucleo":"13-14","difficulty":"dificil","topic":"Fusarium spp.","q":"Paciente neutropénico con fungemia. En el cultivo crece un hongo filamentoso hialino con macroconidios en forma de banana. ¿Qué agente es?","a":["Fusarium spp.","Aspergillus fumigatus","Mucorales","Trichosporon spp."],"c":0,"exp":"Fusarium es un filamentoso hialino con macroconidios en banana, del suelo y las plantas; causa infección cutánea, queratitis y fungemia en neutropénicos.","source":"Cuadernillo Núcleo 13 2026 (listado de agentes) · Compendio ADN (Micosis oportunistas, cuadros)"},
    {"id":"n13_14-d-15","nucleo":"13-14","difficulty":"dificil","topic":"ESKAPE","q":"Del grupo ESKAPE, ¿cuál clasifica la OMS como de prioridad \"alta\" y no \"crítica\" para la investigación de nuevos fármacos?","a":["Staphylococcus aureus","Acinetobacter baumannii","Enterobacter spp.","Klebsiella pneumoniae"],"c":0,"exp":"En las listas de la OMS, A. baumannii y las enterobacterias resistentes (K. pneumoniae, Enterobacter) son de prioridad crítica; S. aureus resistente a meticilina es de prioridad alta. Son multirresistentes y los colonizados actúan como reservorio.","source":"Compendio ADN (13.c.a, siglas ESKAPE)"}
  ].map(Object.freeze));
  const porNucleo = (id) => PREGUNTAS.filter((p) => p.nucleo === id);
  return Object.freeze({ PREGUNTAS, porNucleo });
});
